window.SESSIONS = [{"code": "KEY-DEV", "title": "Developer Keynote", "abstract": "re:Invent 2026 Developer Keynote. The Venetian and virtual.", "type": "Keynote", "level": "", "topic": "Keynote", "area_of_interest": "", "industry": "", "features": "Keynote", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "keynote-dev-1130", "sources": ["keynote"], "ko_desc": "개발자 키노트 — 개발자 대상 신규 기능·도구 발표. (베네시안 / 가상 중계)", "company": "AWS", "thu_am": null, "start_time": "19:30", "length": 75}, {"code": "KEY-CEO", "title": "CEO Keynote featuring Matt Garman", "abstract": "re:Invent 2026 CEO Keynote featuring Matt Garman. The Venetian and virtual.", "type": "Keynote", "level": "", "topic": "Keynote", "area_of_interest": "", "industry": "", "features": "Keynote", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "keynote-ceo-1201", "sources": ["keynote"], "ko_desc": "CEO 키노트 (Matt Garman) — re:Invent 핵심 발표. 최대 규모 메인 키노트. (베네시안 / 가상 중계)", "company": "AWS", "thu_am": null, "start_time": "08:30", "length": 120}, {"code": "KEY-DATA-AI", "title": "Data & AI Keynote", "abstract": "re:Invent 2026 Data & AI Keynote. The Venetian and virtual.", "type": "Keynote", "level": "", "topic": "Keynote", "area_of_interest": "", "industry": "", "features": "Keynote", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "keynote-dataai-1202", "sources": ["keynote"], "ko_desc": "데이터 & AI 키노트 — 데이터·AI 신규 서비스/전략 발표. (베네시안 / 가상 중계)", "company": "AWS", "thu_am": null, "start_time": "08:30", "length": 90}, {"code": "KEY-TECH", "title": "Technology Innovations Keynote", "abstract": "re:Invent 2026 Technology Innovations Keynote. The Venetian and virtual.", "type": "Keynote", "level": "", "topic": "Keynote", "area_of_interest": "", "industry": "", "features": "Keynote", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "keynote-tech-1203", "sources": ["keynote"], "ko_desc": "테크놀로지 이노베이션 키노트 — 기술 혁신 발표. (베네시안 / 가상 중계)", "company": "AWS", "thu_am": true, "start_time": "08:30", "length": 90}, {"code": "PARTY-APJC", "title": "APJC Kick Off Party (APJ on Tour)", "abstract": "AWS re:Invent APJC Kick Off Party. Networking with APJC peers, partners, and AWS leaders at Las Vegas's top rooftop with a world-class DJ. Pre-registration required (Attendee Portal > Explore your ancillary invitations > APJC Kick Off Party RSVP). re:Invent pass required for entry.", "type": "Party", "level": "", "topic": "Party", "area_of_interest": "", "industry": "", "features": "Party", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Soleia Nightclub (3595 Las Vegas Blvd S)", "sessionID": "party-apjc-1130", "sources": ["party"], "ko_desc": "APJC 킥오프 파티 (APJ on Tour) — 라스베이거스 루프탑에서 APJC 고객·AWS 리더십과 네트워킹. 사전 등록 필수(Attendee Portal), 입장 시 re:Invent 패스 필요. 장소: Soleia Nightclub. ※ 본문 18:30~22:30 / RSVP 카드 6:30~11:30 PM 표기 상이.", "company": "AWS (APJC)", "thu_am": null, "start_time": "18:30", "length": 240}, {"code": "PARTY-AMPED", "title": "AMPED: A Startup + Industry Event", "abstract": "An evening at re:Invent 2026 where startup founders and industry leaders come together for networking. One night inside AREA15's immersive space. Confidential, non-transferable invitation.", "type": "Party", "level": "", "topic": "Party", "area_of_interest": "", "industry": "", "features": "Party", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Area15 Zone 1 (3215 S Rancho Dr)", "sessionID": "party-amped-1202", "sources": ["party"], "ko_desc": "AMPED 스타트업+인더스트리 이벤트 — 스타트업 창업자·업계 리더 네트워킹의 밤. 장소: AREA15. 초대장 기반(양도 불가).", "company": "AWS", "thu_am": null, "start_time": "19:00", "length": 210}, {"code": "ANT411-R1", "title": "Simplify identity and security management in an open data architecture on AWS", "abstract": "As organizations unify data across Amazon S3 data lakes, S3 Tables, and Amazon Redshift using the open data lakehouse architecture, securing access at scale becomes critical. In this chalk talk, we dive deep into simplifying trusted identity propagation so end-user identities — not shared service roles — reach the data plane, designing multi-dimensional tag-based access control taxonomies that scale automatically through inheritance, enforcing column-level and cell-level security across federated catalogs, and auditing every access event to individual users.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Analytics", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358256107001ip9e", "sources": ["customer_story"], "ko_desc": "오픈 데이터 아키텍처(S3, Redshift 통합)에서 신뢰된 신원 전파와 태그 기반 접근 제어로 대규모 보안을 단순화하는 방법을 다룬다.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "INV501-R1", "title": "AtoZ AI Co-Scientist: Multi-Agent Systems That Do Research With You", "abstract": "Can an AI system move beyond answering questions to actually conducting research alongside you? We built one. AtoZ AI Co-Scientist is a multi-agent orchestration platform where specialized agents collaborate through a unified interface to discover literature, synthesize knowledge via graph-routed retrieval, generate hypotheses, implement baselines from papers, and run experiments autonomously. In this chalk talk, we dissect the compositional architecture, the graph-routed retrieval system achieving <200ms with structural signals flat search cannot capture, and Co-Scientist Bench—our agent-agnostic evaluation framework. Bring hard questions about reliability, memory, and human oversight.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Analytics, Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion, Full", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441495676001GXEB", "sources": ["customer_story"], "ko_desc": "AtoZ AI가 만든 멀티 에이전트 연구 플랫폼 — 문헌 조사·지식 합성·가설 생성·실험을 에이전트들이 협력해 자율적으로 수행한다.", "company": "AtoZ AI", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "SNR305", "title": "A leader's guide to escaping proof-of-concept purgatory", "abstract": "Drawing on 1,000+ customer conversations about building competitive advantage with data and AI, Rahul Pathak, VP of AWS Data & AI GTM, shares what separates organizations getting real value from agentic AI from those stuck in pilots. When everyone has the same models, your data is the only differentiator. Rahul covers how to set goals worth deploying against, why working backwards from outcomes matters, why cross-functional teams outperform centralized AI functions, what governance must exist before agents reach production, not after, and how to create urgency without a mandate. Field notes from 1,000+ rooms, and a playbook for Monday morning. ", "type": "Mainstage", "level": "300 – Advanced", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442221229001crtG", "sources": ["business_agents"], "ko_desc": "에이전틱 AI에서 실제 가치를 얻는 기업과 PoC에 갇힌 기업의 차이 — 1,000건 이상 고객 대화를 바탕으로 AWS VP가 공유하는 AI 실전 적용 인사이트.", "company": "AWS (Rahul Pathak VP)", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "SNR309", "title": "A leader's guide to why agentic AI just made your data problem urgent ", "abstract": "The data problem you tolerated for years just became an emergency. Agents do not politely work around missing metadata. They guess confidently, and you find out three weeks later. Enterprises assumed they could solve AI first and data second. They can't. You get the framework that separates compounding value from programs that never finish. AWS Marketing built an agentic system over thousands of warehouse tables. It worked. Its first output: an inventory of every undocumented decision in the warehouse. That exposure was worth more than the answers. You leave knowing what to fix first, and why analytical demand climbs. ", "type": "Mainstage", "level": "300 – Advanced", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1783654976429001d7YA", "sources": ["business_agents"], "ko_desc": "에이전트는 데이터 문제를 정중히 우회하지 않고 자신 있게 오답을 낸다 — 수년간 미뤄온 데이터 기반 문제가 에이전틱 AI 시대에 긴급 과제가 된 이유.", "company": "AWS", "thu_am": true, "start_time": "09:00", "length": 60}, {"code": "BIZ104-S", "title": "From On-Premises to Agentic AI: Bayer's Amazon Connect Transformation Journey (sponsored by Capgemini)", "abstract": "Capgemini transformed 414 contact center hotlines across more than 68 countries by replacing Cisco UCCE with Amazon Connect and introducing AgentX, an AWS-native agentic AI platform deployed across the Bayer enterprise. Built on Amazon Bedrock, Amazon Connect, Amazon Lex, AWS Lambda, and other AWS services, AgentX delivers real-time agent assistance, automated call summarization, governance controls, predictive analytics, and autonomous workflow execution. Learn how Bayer established a \"build once, deploy globally\" operating model that enables consistent AI innovation across business units while reducing operational complexity, improving agent productivity, and delivering significant cost savings. This presentation is brought to you by Capgemini, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780441484193001GaES", "sources": ["business_agents"], "ko_desc": "Bayer의 414개 콜센터 핫라인(68개국)을 Cisco UCCE에서 Amazon Connect로 전환 — AgentX 에이전틱 AI 플랫폼 배포 사례 (Capgemini 스폰서).", "company": "Bayer (Capgemini)", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AIM3325-S", "title": "How In-Context Learning Delivers Interpretable AI at 90% Lower Cost (sponsored by Sphinx AI)", "abstract": "Enterprises have spent years building institutional knowledge, but AI agents still struggle to apply that expertise to complex business tasks. This session explores how scaling in-context learning (ICL) enables organizations to train AI on their existing work, allowing agents to reason and make decisions with the judgment of an organization's experts. We’ll examine how this approach makes institutional knowledge portable across models, achieves 95%+ accuracy and performance while reducing inference costs by 90%+ with the ability to swap to smaller models. Through real-world examples, we’ll demonstrate how organizations can customize AI for their business without costly fine-tuning while maintaining full interpretability into what agents learn, how that knowledge influences their outputs, and how errors can be corrected. This presentation is brought to you by Sphinx AI, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442269117001cYyA", "sources": ["business_agents"], "ko_desc": "In-Context Learning(ICL) 확장으로 기존 비용 대비 90% 절감하면서 해석 가능한 AI 구현 — 복잡한 비즈니스 태스크에 전문 지식을 적용하는 방법 (Sphinx AI 스폰서).", "company": "Sphinx AI", "thu_am": null, "start_time": null, "length": 20}, {"code": "AIM239-S", "title": "Scaling Pharma Transformation Through Data-Driven Agentic AI (sponsored by Tech Mahindra)", "abstract": "Hear from a leading U.S. pharmaceutical company on its journey to transforming enterprise AI from isolated experiments into a scalable business capability. Discover how Tech Mahindra helped establish trusted data foundations, harness Agentic AI to enrich product and customer master data, unlock semantic intelligence, and create governed data products that power enterprise-wide insights, including drug demand forecasting. This session will explore the architectural principles, governance strategies, and leadership decisions required to scale compliant, trusted, and value-driven AI. Join Tech Mahindra and a pharma industry leader to learn how data-driven Agentic AI is reshaping the future of the intelligent pharma enterprise. This presentation is brought to you by Tech Mahindra, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442270056001ca7F", "sources": ["business_agents"], "ko_desc": "미국 주요 제약사의 기업 AI를 고립된 실험에서 확장 가능한 역량으로 전환한 여정 — Tech Mahindra와 신뢰할 수 있는 데이터 기반 구축 사례 (스폰서).", "company": "Tech Mahindra", "thu_am": null, "start_time": null, "length": 20}, {"code": "BIZ202-S", "title": "Trust at Scale: Unlocking Enterprise Agentic AI (sponsored by Qlik)", "abstract": "Agentic AI dies at scale. It is easy to get one agent working on one dataset for one team. The challenge is trusting its answers across hundreds of thousands of users, regions, languages, regulators, and constantly changing data. AWS provides global infrastructure, security, data residency, and compliance controls to scale AI. Qlik provides trusted governed data, business context, and intelligence that agents can rely on. See how Amazon Bedrock and the Qlik MCP Server bring trusted Qlik intelligence to production agents and any LLM including Amazon Quick. Learn how enterprises can scale agentic AI without sacrificing trust governance or choice. This presentation is brought to you by Qlik, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Analytics, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442272436001csWn", "sources": ["business_agents"], "ko_desc": "에이전틱 AI는 한 팀·한 데이터셋에서 한 에이전트를 작동시키기는 쉽다 — 수십만 사용자·여러 지역·언어·규제 환경에서 신뢰를 유지하며 확장하는 방법 (Qlik 스폰서).", "company": "Qlik", "thu_am": null, "start_time": "13:00", "length": 20}, {"code": "INV521-R1", "title": "Teaching Telemetry to Think: From Raw Signals to Root Cause", "abstract": "An AI agent investigating an incident starts cold: no sense of normal, no topology, no causal history. It rebuilds context from raw documents every time. What if the telemetry understood itself first? We'll examine an intelligence layer for agentic observability, where streaming detectors and a live service graph distill billions of signals into incident observations, then fine-tuned reasoning models, built on open-weight LLMs, correlate them into ranked root causes. Whiteboard with us on the hard parts: what to teach a model versus retrieve at inference, how domain fine-tuning beats frontier scale, and where reasoning models still fail. ", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Analytics, Artificial Intelligence, Cloud Operations", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1780441496214001GQ2s", "sources": ["customer_story"], "ko_desc": "AI 에이전트가 매번 처음부터 컨텍스트를 재구성하는 문제를 해결 — 텔레메트리 자체가 사고를 인식하는 인텔리전스 레이어로 장애 원인을 자동 추적한다.", "company": "AWS", "thu_am": false, "start_time": null, "length": 60}, {"code": "SUP205", "title": "How Clay turns CRM + first-party data into a context graph for AI agents", "abstract": "Clay, a Forbes AI 50 2026-listed market leader in go-to-market intelligence, helps sales teams identify promising accounts and decide how to engage them. Solange Levy, Head of AI, demonstrates how Clay combines CRM and first-party data into a context graph that guides AI agents through account research and prioritization. A product demo connects customer data to recommended sales actions, with examples from AI-native companies such as Cursor. The session examines how the emerging GTM Engineer role changes sales work and supports outbound campaigns. Founders and sales operations leaders can assess how this approach could shorten sales cycles and improve targeting of new accounts.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Analytics, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1791492159262001Uwh1", "sources": ["business_agents"], "ko_desc": "Clay(GTM 인텔리전스 기업)가 CRM과 자사 데이터를 결합해 AI 에이전트를 위한 컨텍스트 그래프를 구축하는 방법 — 영업팀 AI 활용 사례.", "company": "AWS", "thu_am": null, "start_time": null, "length": 20}, {"code": "AIM251-S", "title": "How YipitData Builds AI-Native Analytics with AWS, Databricks, and OpenAI (sponsored by Databricks)", "abstract": "YipitData gives customers a self-service way to answer analytical questions using agents grounded in its data, completing custom requests in 30 minutes compared with the two weeks previously needed. This session walks through the production architecture behind that experience, combining Databricks for data governance and observability, OpenAI for reasoning and intelligence, and AWS for application resiliency and hosting.\n\nLearn how a custom agent harness connects OpenAI frontier models to Databricks SQL Warehouses, with Amazon ECS and ElastiCache supporting the application and asynchronous agent execution. We cover Unity Catalog access boundaries, dedicated agent identities, durable session state in Lakebase, and evaluations that check SQL, tool use, and answer consistency. This presentation is brought to you by Databricks, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Analytics, Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780441484865001GbTa", "sources": ["business_agents"], "ko_desc": "YipitData가 AWS·Databricks·OpenAI로 AI 네이티브 분석 플랫폼 구축 — 고객 맞춤형 분석 요청을 기존 2주에서 30분으로 단축한 에이전트 사례 (Databricks 스폰서).", "company": "Databricks", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "API315-R1", "title": "Coding high-throughput data pipelines with AWS Lambda durable functions", "abstract": "Processing large datasets usually means hand-wiring queues, coordinators, and state tracking. In this code talk, we live-build a high-throughput data pipeline with Lambda durable functions instead. You'll see the fan-out/fan-in pattern in code: split a large dataset across parallel durable executions, isolate and retry the branches that fail without reprocessing the ones that succeeded, and offload checkpoints to S3 so a job too big for a single invocation survives restarts. We'll tune concurrency to protect a downstream database from overload, then compare the durable-functions approach with other design patterns on both developer velocity and cost. Leave with patterns you can apply to your own data workloads immediately.", "type": "Code talk", "level": "300 – Advanced", "topic": "Application Integration", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358234186001iHCZ", "sources": ["customer_story"], "ko_desc": "Lambda 듀러블 함수로 대용량 데이터 파이프라인을 직접 구현 — 큐·코디네이터 없이 fan-out/fan-in 패턴, 실패 분기 재시도를 라이브 코딩으로 시연.", "company": "AWS", "thu_am": true, "start_time": "08:00", "length": 60}, {"code": "AIM112-S", "title": "Give agents governed access to your APIs over MCP with a domain model (sponsored by Apollo GraphQL)", "abstract": "Enterprises have spent years building APIs for applications and developers. They now need to make those systems available to AI agents, and connecting them through MCP is only the beginning. How do agents discover how to use APIs accurately, retrieve only the fields they need without runaway token costs, and access only what they're authorized to see? This session demonstrates an architecture that answers all three questions. A domain model built with GraphQL describes what each API means and how the data connects. Each agent gets its own identity, policy is set on individual fields, and every call is logged. This presentation is brought to you by Apollo GraphQL, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Application Integration, Architecture, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442267034001cC3t", "sources": ["business_agents"], "ko_desc": "기업이 수년간 쌓은 API를 AI 에이전트에게 연결하는 것은 MCP만으로는 부족 — 에이전트가 올바른 API를 발견하고 활용하도록 도메인 모델로 거버넌스 적용 (Apollo GraphQL 스폰서).", "company": "Apollo GraphQL", "thu_am": null, "start_time": "13:00", "length": 20}, {"code": "SNR318", "title": "A leader's guide to reimagining complex business processes with agents", "abstract": "Most enterprises use AI as an assistant, automating individual tasks for incremental 20% gains. The leaders unlocking profound productivity gains are doing something different: reimagining entire business processes from the outcome backward, so every step hands forward context, confidence, and decision authority, not just data. This session shows what it takes to transform your most strategic operations with agentic AI and scale them, then Thomson Reuters walks through the lessons of rebuilding its M&A process end-to-end. You leave knowing which processes to reimagine and how to move them into production, where value compounds. ", "type": "Mainstage", "level": "300 – Advanced", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1783654976655001dJjp", "sources": ["business_agents"], "ko_desc": "개별 태스크 자동화로 20% 생산성 향상에 그치는 기업 vs 전체 비즈니스 프로세스를 재설계해 압도적 성과를 내는 기업의 차이 — 리더 가이드.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "AIM130-S", "title": "How Cox Achieved 7x ROI with Agentic AI on AWS (sponsored by Accenture)", "abstract": "Cox Communications partnered with Accenture and Anthropic's Claude on AWS to transform B2B marketing and sales, generating a 7x return on its first-year AI investment. By deploying AI-powered marketing and sales agents across 120 micro-industries and eight customer segments, Cox replaced one-size-fits-all campaigns with personalized engagement at scale. The initiative delivered 55% faster speed to market, a 2-point increase in B2B conversion, 40% higher campaign efficiency, and an 86% reduction in lead management costs while improving data accuracy from 18% to 97%. Today, Cox is operating an end-to-end agentic go-to-market system with human oversight. This presentation is brought to you by Accenture, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780441482877001GC3Z", "sources": ["business_agents"], "ko_desc": "Cox Communications가 Accenture·Claude를 활용해 B2B 마케팅·영업에 AI 에이전트 배포, 첫해 투자 대비 7배 수익 창출한 사례 (Accenture 스폰서).", "company": "Cox Communications (Accenture)", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM2209-S", "title": "How Philips accelerated sales quoting with Agentic AI (sponsored by EPAM)", "abstract": "Philips, a global health technology company, identified an opportunity to accelerate customer quoting for complex solutions combining equipment, software and services. Working with EPAM, Philips built the solution on AWS using an AI-native approach. A team of fewer than 20 used Amazon Kiro across the software development lifecycle, with Amazon Bedrock and the Strands Agents SDK powering an agentic architecture. The result is Sensei, an AI-powered sales experience. This session shares practical lessons for applying agentic AI, accelerating development and business operations, embedding governance, and moving from prototype to enterprise production at scale. This presentation is brought to you by EPAM, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441489009001G3sy", "sources": ["business_agents"], "ko_desc": "Philips가 복잡한 의료 장비·소프트웨어·서비스 견적 프로세스를 에이전틱 AI로 가속화 — EPAM과 협력해 AWS에서 솔루션 구축한 사례 (스폰서).", "company": "EPAM", "thu_am": null, "start_time": null, "length": 60}, {"code": "AIM131-S", "title": "How SoCalGas Is Using Agentic AI for SAP Migration Hypercare on AWS with Accenture (sponsored by Accenture)", "abstract": "SoCalGas is migrating its decades-old Customer Information System to SAP IS-U, where hypercare is a critical phase for customer and regulatory impacts. Traditional command centers require teams to manually correlate signals across ServiceNow, Azure DevOps, dashboards, logs, and staffing systems, which may slow response times. SoCalGas worked with Accenture on a multi-agent AI command center using Amazon Bedrock. A Commander agent is designed to orchestrate Platform Health, Business KPI, Knowledge, and Situational Awareness agents, while every recommendation is intended to be citation-grounded and human-supervised. Learn about SoCalGas’s project experience using agentic AI to unify operational intelligence in a mission-critical utility environment. References are for informational purposes only and do not constitute endorsement, recommendation, warranty, certification or representation. This presentation is brought to you by Accenture, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441486396001G9cG", "sources": ["business_agents"], "ko_desc": "SoCalGas의 SAP IS-U 마이그레이션 Hypercare 단계에 에이전틱 AI 적용 — Accenture와 협력해 신호 간 상관관계를 자동으로 파악하는 지휘 센터 구축 (스폰서).", "company": "SoCalGas (Accenture)", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "AMZ303-R1", "title": "Prime Video Financial Systems on the Road to 10x Velocity with Kiro", "abstract": "This chalk talk will deep-dive into Prime Video Financial Systems' journey toward 10x engineering velocity with Kiro. Starting at 3x through AI-assisted sprints, the team evolved to autonomous agent-driven delivery, where agents pick up tasks, implement code, raise code requests, address feedback, and merge 24/7 without human intervention. Each step compounds, enabling parallel execution, zero idle time, and freeing engineers to focus on design and review. This is an honest, in-progress story that demonstrates the concrete methodology, structured specs, persistent Kiro sessions, and architectural decisions required to move from acceleration toward order-of-magnitude transformation.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "Financial Services, Media & Entertainment", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358220564001iYMP", "sources": ["customer_story", "business_agents"], "ko_desc": "Prime Video 재무 시스템팀이 Kiro로 엔지니어링 속도 10배 달성 — 에이전트가 태스크 선택·코드 구현·코드 리뷰·머지를 24/7 자율 처리한 실제 여정.", "company": "Amazon (Prime Video)", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "AMZ303-R", "title": "Prime Video Financial Systems on the Road to 10x Velocity with Kiro", "abstract": "This chalk talk will deep-dive into Prime Video Financial Systems' journey toward 10x engineering velocity with Kiro. Starting at 3x through AI-assisted sprints, the team evolved to autonomous agent-driven delivery, where agents pick up tasks, implement code, raise code requests, address feedback, and merge 24/7 without human intervention. Each step compounds, enabling parallel execution, zero idle time, and freeing engineers to focus on design and review. This is an honest, in-progress story that demonstrates the concrete methodology, structured specs, persistent Kiro sessions, and architectural decisions required to move from acceleration toward order-of-magnitude transformation.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "Financial Services, Media & Entertainment", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780441501114001GNOW", "sources": ["business_agents"], "ko_desc": "Prime Video 재무 시스템팀의 Kiro 기반 10배 속도 향상 여정 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "AIM281-S", "title": "Pushing AI Boundaries: Transform Marketing with Adobe CX Enterprise Coworker and AWS (sponsored by Adobe)", "abstract": "As generative AI matures into autonomous ecosystems, enterprise marketing demands a new era of collaboration. In this session, discover how Adobe and Amazon co-innovate to deliver next-generation AI capabilities for marketers, business practitioners, and developers. At the center of this revolution is Adobe CX Enterprise Coworker, an advanced AI teammate powered by Adobe Harness. We will showcase how Coworker and its flexible, headless capabilities seamlessly unite Adobe’s deep customer experience expertise with the power of AWS. Attendees will discover how this combined innovation enables teams to transition from manual execution to goal-based, automated workflows with built-in governance. Join us to learn how this partnership helps enterprise organizations take a massive leap forward in operational effectiveness and unlock entirely new business outcomes. This presentation is brought to you by Adobe, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Application Integration, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442267792001cgYN", "sources": ["business_agents"], "ko_desc": "Adobe와 Amazon이 공동 개발하는 엔터프라이즈 마케팅용 차세대 AI — CX Enterprise Coworker로 자율적 마케팅 생태계를 구현하는 방법 (Adobe 스폰서).", "company": "Adobe", "thu_am": null, "start_time": "13:00", "length": 20}, {"code": "AMZ302-R1", "title": "Zero-Trust by Design: How Bee Protects Personal Data Even from Itself on AWS ", "abstract": "Personal agentic AI represents a new frontier; devices that understand you deeply enough to act on your behalf. Bee is Amazon's AI wearable that helps users capture and act on insights from their daily lives. But deep personalization demands deep trust and privacy. In this session, learn how the Bee team architected a zero-trust pipeline using AWS Nitro Enclaves and confidential computing to keep sensitive data cryptographically isolated at every stage. We'll share the attestation models, data minimization tradeoffs, and design principles you can apply to build AI-powered experiences your users trust from day one.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Application Integration, Artificial Intelligence, Security & Identity", "area_of_interest": "", "industry": "Media & Entertainment", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358242746001izef", "sources": ["customer_story"], "ko_desc": "Amazon 웨어러블 Bee의 개인 데이터 보호 아키텍처 — Nitro Enclaves와 컨피덴셜 컴퓨팅으로 딥 퍼스널라이제이션과 프라이버시를 동시에 실현한 제로-트러스트 설계.", "company": "Amazon (Bee)", "thu_am": null, "start_time": null, "length": 60}, {"code": "SEC379-S", "title": "From containers to containment: trust the boundary, not the agent (sponsored by Docker)", "abstract": "For a decade, teams have trusted containers to run the same way everywhere. Coding agents raise the stakes: the thing inside now installs packages, accesses credentials, and acts on its own. In this session, see how the idea that made containers the standard becomes containment for agents: a Docker sandbox that limits what an agent can reach, hardened images beneath what it builds, and a record of what it was allowed to do and what was stopped, under policies set once for every developer. The agent gets room to work; the boundary gets the trust. That is what running on trust means. This presentation is brought to you by Docker, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Application Integration, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442272072001cHdC", "sources": ["business_agents"], "ko_desc": "컨테이너가 어디서나 동일하게 실행되도록 신뢰해온 것처럼 AI 에이전트도 안전하게 격리 — Docker로 에이전트의 패키지 설치·크리덴셜 접근을 통제하는 방법 (Docker 스폰서).", "company": "Docker", "thu_am": null, "start_time": null, "length": 20}, {"code": "HMC203-S", "title": "Optimizing SAP RISE for Cost and Scale with Intel (sponsored by Intel)", "abstract": "Discover how Intel's custom SAP-certified Intel® Xeon® 6 processor, exclusively available on AWS, transforms and accelerates your SAP RISE journey. Engineered to deliver the highest performance and fastest memory bandwidth among comparable Intel cloud processors, this powerful solution unlocks up to 50% higher SAPS performance. Whether migrating, consolidating, or scaling SAP workloads, Intel Xeon 6 on AWS empowers organizations to optimize costs, enhance efficiency, and maximize their SAP RISE investment — driving faster, smarter, and more cost-effective outcomes for modern enterprise demands. This presentation is brought to you by Intel, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Application Integration, Business Agents, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441489761001GYdw", "sources": ["business_agents"], "ko_desc": "AWS 전용 Intel Xeon 6 프로세서로 SAP RISE 전환 성능 및 메모리 대역폭 향상 (Intel 스폰서).", "company": "Intel", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AMZ304", "title": "Instant Play Demos on Twitch – Increasing Player Engagement ", "abstract": "From game builds to live campaigns, take a deep dive into the best practices and constraints around launching Instant Play Demos on Twitch, powered by Amazon GameLift Streams. This innovative approach to game marketing enables developers to reach potential players and let them try your game before they buy it. No downloads or installs required, just a WebRTC enabled browser and an internet connection. Learn what kind of content makes for a great demo, engine-specific best practices, and the benefits of launching a campaign and how they perform compared to traditional marketing channels.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Application Integration, Networking & Content Delivery, Industry Solutions", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780442246672001cohx", "sources": ["retail"], "ko_desc": "Amazon GameLift Streams 기반 Twitch 인스턴트 플레이 데모 — 게임 마케팅의 새로운 접근, 플레이어 참여 향상 베스트 프랙티스.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "IND3340", "title": "AI-driven customer experience with Amaze, Byte by Yum! & Amorepacific", "abstract": "Customer experience in retail and consumer goods used to depend on how much staff you could put on the floor, the screen, or the line. Agentic AI changes the math: agents guide shoppers, support team members, and adapt to what a customer needs in real time. Hear how three brands put agents to work. Amaze, CP Group's super app, built an AI shopping assistant for shoppers across the group's brands, including 7-Eleven Thailand; Byte by Yum! powers personalized ordering and team member tools at Taco Bell; and Amorepacific built an AI beauty concierge delivering precision skin diagnoses across 10 countries.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Lecture-style, Walk up only", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780441475885001GBCT", "sources": ["retail"], "ko_desc": "Amaze, Byte by Yum!, Amorepacific의 리테일·소비재 AI 고객 경험 혁신 — 매장·화면·전화에서 에이전틱 AI로 쇼핑 가이드·팀 지원·실시간 적응.", "company": "Amaze, Byte by Yum!, Amorepacific", "thu_am": null, "start_time": "13:00", "ko_full": "리테일·소비재의 고객 경험은 현장, 화면, 줄에 얼마나 많은 인력을 투입할 수 있느냐에 좌우되곤 했습니다. 에이전틱 AI는 이 셈법을 바꿉니다. 에이전트가 쇼퍼를 안내하고, 팀원을 지원하며, 고객이 필요로 하는 것에 실시간으로 맞춰 적응합니다.\n세 브랜드가 에이전트를 어떻게 일에 투입했는지 들어봅니다. CP Group의 슈퍼앱 Amaze는 7-Eleven Thailand를 포함한 그룹 내 여러 브랜드의 쇼퍼를 위한 AI 쇼핑 어시스턴트를 만들었습니다. Byte by Yum!은 Taco Bell의 개인화 주문과 팀원용 도구를 구동합니다. 아모레퍼시픽은 10개국에서 정밀한 피부 진단을 제공하는 AI 뷰티 컨시어지를 만들었습니다.", "length": 60}, {"code": "IND3331", "title": "How Nordstrom, Coca-Cola Andina & Mondelez use agentic supply chains", "abstract": "Supply chain leaders are moving from dashboards that report problems to agents that resolve them, sensing disruption, optimizing routing, and acting in real time. Hear how three retail and CPG leaders deployed agentic AI on AWS at scale. Nordstrom built a multi-agent framework on Amazon Bedrock AgentCore, starting with an agent that cut audit investigations from five weeks to thirty seconds. Coca-Cola Andina developed Miruta, a multi-agent routing solution optimizing supply chain operations across its bottling network. And Mondelez is modernizing production and distribution across 150+ countries. Each shares their architecture, what changed for their teams, and measurable results.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1780441476105001GSE2", "sources": ["retail"], "ko_desc": "Nordstrom·코카콜라 안디나·Mondelez의 에이전틱 공급망 사례 — 문제를 보고하는 대시보드에서 실시간으로 해결하는 에이전트로 전환한 세 기업의 이야기.", "company": "Nordstrom, Coca-Cola Andina, Mondelez", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "CMP327-R1", "title": "Optimize AI inference costs: Compare token economics on AWS silicon", "abstract": "Most enterprises run their entire AI pipeline on GPU and can overpay. AWS's silicon portfolio (Trainium & Graviton) along with NVIDIA GPU, Intel, and AMD all offer radically different cost-per-token economics for different workloads. This session delivers a decision framework for matching silicon to workload: training and inference on Trainium, RAG pipelines on Graviton, real-time agents on GPU, batch on Intel/AMD. Includes Bedrock vs. self-host crossover analysis, volume thresholds, and the architecture patterns to put the savings into practice.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358256378001i8Ap", "sources": ["customer_story"], "ko_desc": "AI 전 파이프라인을 GPU로만 돌리면 과비용 — 워크로드별 최적 실리콘(Trainium/Graviton/GPU) 선택 프레임워크와 실제 토큰당 비용 비교.", "company": "AWS", "thu_am": false, "start_time": null, "length": 60}, {"code": "COM317-R1", "title": "Ship Reliable AI Agents with Strands Evaluation and AgentCore Evaluations", "abstract": "Your AI agent works in demos, but can you trust it enough for production? How do you test behavior that can vary on every run, and catch regressions when prompts, models, tools, or workflows change? In this 300-level Code Talk, we'll turn real-world agent failure modes into representative test cases, evaluate both answers and actions, and add risk-based quality gates into CI/CD. Using Strands Evaluation and Amazon Bedrock AgentCore Evaluations, you'll leave this session able to design and implement an evaluation pipeline tailored to your own agents, backed by a public reference implementation you can adapt.", "type": "Code talk", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion, Full", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358242296001ilAr", "sources": ["customer_story"], "ko_desc": "프로덕션 AI 에이전트 신뢰성 확보법 — 매번 결과가 달라지는 에이전트를 테스트하고 CI/CD에 품질 게이트를 추가하는 실전 평가 방법론.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60, "ko_full": "AI 에이전트가 데모에서는 잘 동작하지만, 프로덕션에 쓸 만큼 신뢰할 수 있을까요? 실행할 때마다 달라질 수 있는 동작을 어떻게 테스트하고, 프롬프트, 모델, 툴, 워크플로우가 바뀔 때 회귀(regression)를 어떻게 잡아낼까요?\n이 300레벨 코드 토크에서는 실제 에이전트 실패 유형을 대표 테스트 케이스로 바꾸고, 답변과 행동(action)을 모두 평가하며, 위험 기반 품질 게이트를 CI/CD에 추가합니다.\nStrands Evaluation과 Amazon Bedrock AgentCore Evaluations를 사용해, 여러분의 에이전트에 맞춘 평가 파이프라인을 설계하고 구현할 수 있게 되어 돌아가실 수 있으며, 가져다 응용할 수 있는 공개 레퍼런스 구현이 뒷받침됩니다."}, {"code": "IND3332", "title": "Tapestry, Grupo Boticario & Nestle Purina on agentic commerce", "abstract": "AI agents are changing how consumers discover and buy, splitting into two investments: retailers building conversational shopping on their own properties, and consumer goods companies optimizing how their products surface when agents shop on a consumer's behalf. In this session, hear how Tapestry built the Kate Spade AI Gift Concierge that turns luxury gifting into a guided conversation; Grupo Boticario launched an agentic Virtual Assistant orchestrating product discovery and checkout for millions of users; and Nestle Purina implemented an Answer Engine Optimization strategy, using their native chatbot Allie to pressure-test how external AI engines surface proprietary brand data before releasing it into circulation.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Lecture-style, Walk up only", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1780441476159001Gdq3", "sources": ["retail"], "ko_desc": "Tapestry·Grupo Boticario·Nestle Purina의 에이전틱 커머스 전략 — 소비자가 AI를 통해 발견·구매하는 시대, 브랜드는 자사 채널 강화 vs 노출 최적화 중 무엇을 선택해야 하나.", "company": "Tapestry, Grupo Boticario, Nestle Purina", "thu_am": null, "start_time": "10:30", "length": 60, "ko_full": "AI 에이전트가 소비자가 제품을 발견하고 구매하는 방식을 바꾸고 있으며, 이에 따라 투자도 두 갈래로 나뉩니다. 하나는 소매업체가 자사 채널에서 대화형 쇼핑을 구축하는 것이고, 다른 하나는 소비재 기업이 에이전트가 소비자를 대신해 쇼핑할 때 자사 제품이 어떻게 노출되는지를 최적화하는 것입니다.\n이 세션에서는 세 사례를 듣습니다. Tapestry는 럭셔리 선물하기를 안내형 대화로 바꾼 Kate Spade AI Gift Concierge를 만들었습니다. Grupo Boticário는 수백만 사용자를 위한 제품 탐색과 결제를 조율하는 에이전틱 가상 어시스턴트를 출시했습니다. Nestlé Purina는 Answer Engine Optimization(AEO) 전략을 도입해, 외부 AI 엔진이 자사의 고유 브랜드 데이터를 어떻게 노출하는지를 자체 챗봇 Allie로 압박 테스트(pressure-test)한 뒤에 유통에 내놓았습니다.", "room": "Level 1 | Forum 120 | Content Hub | Blue Theater"}, {"code": "COM325-R1", "title": "The agent orchestration spectrum: Agents, Step Functions, or Lambda?", "abstract": "\"Orchestration mode matters more for end user experience than just model choice. In this live-coding session, I build the same GenAI workload three ways: Amazon Bedrock AgentCore, AWS Step Functions, and AWS Lambda durable functions - and show what each costs in latency, dollars, and debuggability on a production content platform. Leave with a reusable decision framework to match orchestration to your workload.\"", "type": "Code talk", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358249514001ibSN", "sources": ["customer_story"], "ko_desc": "동일한 GenAI 워크로드를 Bedrock AgentCore·Step Functions·Lambda로 각각 구현 비교 — 지연시간·비용·디버깅 관점에서 오케스트레이션 선택 기준을 제시.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "IND406-R1", "title": "The agentic restaurant: AI agents that run your kitchen", "abstract": "The restaurant industry is transforming as AI agents move from pilots to production. Leading QSR and casual dining brands are deploying a \"virtual general manager,\" multiple specialized agents orchestrated together to optimize drive-thru ordering, kitchen workflows, labor scheduling, and guest experience in real time. In this chalk talk, we whiteboard a multi-agent architecture using Amazon Bedrock AgentCore and Strands Agents SDK, with Amazon Nova Sonic powering voice ordering at sub-2-second latency. We design a supervisor agent coordinating specialists across drive-thru, kitchen prep, inventory, and labor scheduling. Explore how agents share context, resolve conflicts, validate decisions against synthetic personas before deployment, and maintain human-in-the-loop oversight. Bring your architecture challenges.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1790358240803001iD7i", "sources": ["retail"], "ko_desc": "레스토랑 산업의 에이전틱 AI 전환 — QSR·캐주얼 다이닝 브랜드가 '가상 총지배인' 역할을 하는 복수의 특화 에이전트를 오케스트레이션하는 방법.", "company": "QSR 브랜드들", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "IND406-R", "title": "The agentic restaurant: AI agents that run your kitchen", "abstract": "The restaurant industry is transforming as AI agents move from pilots to production. Leading QSR and casual dining brands are deploying a \"virtual general manager,\" multiple specialized agents orchestrated together to optimize drive-thru ordering, kitchen workflows, labor scheduling, and guest experience in real time. In this chalk talk, we whiteboard a multi-agent architecture using Amazon Bedrock AgentCore and Strands Agents SDK, with Amazon Nova Sonic powering voice ordering at sub-2-second latency. We design a supervisor agent coordinating specialists across drive-thru, kitchen prep, inventory, and labor scheduling. Explore how agents share context, resolve conflicts, validate decisions against synthetic personas before deployment, and maintain human-in-the-loop oversight. Bring your architecture challenges.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Architecture, Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1780442244891001cgCd", "sources": ["retail"], "ko_desc": "레스토랑 산업의 에이전틱 AI 전환 (반복 세션).", "company": "QSR 브랜드들", "thu_am": false, "start_time": null, "length": 60}, {"code": "AIM247-S", "title": "AI at Lennar: Driving 80,000 Home Deliveries with Bedrock & Coralogix (sponsored by Coralogix)", "abstract": "Lennar is bringing AI into the everyday work behind more than 80,000 home deliveries a year, from land research and acquisition to construction, customer engagement, and sales. Join Ralph Gootee, CTO of Lennar, and Ariel Assaraf, CEO of Coralogix, for a practical look at moving AI from experimentation into production. They’ll share how Lennar is building and scaling AI agents on Amazon Bedrock, using AWS inference services and open-source models, and how Coralogix helps teams understand adoption, performance, cost, and business impact. This presentation is brought to you by Coralogix, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780441484074001GGYa", "sources": ["business_agents"], "ko_desc": "Lennar이 Bedrock과 Coralogix로 연간 8만 채 주택 배달 전 과정(토지 조사→건설→고객 응대→영업)에 AI 적용한 사례 — CTO 직접 발표 (Coralogix 스폰서).", "company": "Lennar (Coralogix)", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "AIM2217-S", "title": "Accelerating the Journey to Autonomous Operations with AI on AWS (sponsored by Genpact)", "abstract": "GE Vernova is moving from traditional infrastructure and application operations toward autonomous, AI-enabled operations on AWS. The company is modernizing its operating model across data centers, storage, compute, cloud, middleware, and application management.\nThis session will explore how AI can increase the speed, productivity, and effectiveness of large-scale modernization programs. This presentation is brought to you by Genpact, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1789071877957001YViL", "sources": ["business_agents"], "ko_desc": "GE Vernova가 AWS에서 기존 데이터센터·스토리지·클라우드 운영을 자율·AI 기반 운영 모델로 전환하는 여정 (Genpact 스폰서).", "company": "GE Vernova (Genpact)", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM259-S", "title": "Agents demand context. Build them a Streamhouse. (sponsored by Confluent)", "abstract": "Your agents can't act on yesterday's data. In this session, see how to connect streaming events, governed data, and agent orchestration into one production-ready streamhouse architecture on AWS. Learn how to build a complete, performant, and open streamhouse that delivers real-time context, elastic scale, and mission-critical reliability across every cloud and private environment without data silos. You'll leave with practical patterns for moving from brittle data pipelines to AI built on data streams, designed for speed, trust, and scale. This presentation is brought to you by Confluent, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441487523001GnAq", "sources": ["business_agents"], "ko_desc": "에이전트는 어제 데이터로는 행동할 수 없다 — 스트리밍 이벤트·거버넌스 데이터·에이전트 오케스트레이션을 하나의 Streamhouse 아키텍처로 연결하는 방법 (Confluent 스폰서).", "company": "AWS (Confluent)", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "BIZ328-S", "title": "Build It, Govern It, Ship It: CI/CD for AI Agents with the NVIDIA Agent Toolkit (sponsored by NVIDIA)", "abstract": "Shipping an AI agent once is easy. Shipping it again, cheaper, better, and still within policy, is the hard part. In this session we treat an agent like any other software, using the NVIDIA Agent Toolkit on AWS: every part it’s built from, its skills, tools, models, and policies, goes through a pipeline before an agent can use it. We pull a skill from a public registry, test whether it actually helps with NVIDIA SkillEvaluator, and publish it to a private registry alongside AWS Agent Registry, pinned by version and digest. Then we route each call to the right model across NVIDIA NIM and Amazon Bedrock with NeMo Switchyard, and turn what the run’s checks caught into the next policy rule. Leave knowing how to make each release of your agent cheaper, better, and safer than the last. This presentation is brought to you by NVIDIA, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442273194001czQm", "sources": ["business_agents"], "ko_desc": "AI 에이전트를 소프트웨어처럼 취급 — NVIDIA Agent Toolkit으로 CI/CD 파이프라인에 에이전트를 통합, 정책 내에서 반복 배포하는 방법 (NVIDIA 스폰서).", "company": "NVIDIA", "thu_am": null, "start_time": "11:00", "length": 20}, {"code": "AIM295-S", "title": "Build an Agentic Enterprise to Enable Autonomous Action (sponsored by Snowflake)", "abstract": "Building an agentic enterprise empowers organizations to automate complex work and drive measurable business outcomes. True transformation happens when autonomous AI operates across systems using trusted data, flexible models, connected applications, and a unified, agentic control plane. By bringing knowledge workers and technical builders into a shared agentic environment, teams move faster without sacrificing governance. Learn how the Snowflake AI Data Cloud unifies enterprise context, model choice, and app connections into a single architecture. Discover how to turn enterprise data into reliable, autonomous action and long-term competitive advantage in your AWS cloud environment. This presentation is brought to you by Snowflake, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441487008001GLt7", "sources": ["business_agents"], "ko_desc": "에이전틱 엔터프라이즈 구현 — Snowflake 신뢰 데이터와 유연한 에이전트 프레임워크로 복잡한 작업을 자동화하고 실질적인 비즈니스 성과를 내는 방법 (Snowflake 스폰서).", "company": "Snowflake", "thu_am": null, "start_time": null, "length": 60}, {"code": "MAM338-S", "title": "Building for Always-On: Resilient Trading to Agentic AI on Modern Data Foundation (sponsored by Cognizant)", "abstract": "Learn how LPL Financial built an always-on trading platform on AWS that supports 32,000+ financial advisors with resilient, multi-region architecture for mission-critical, latency-sensitive workloads. Discover how a unified data foundation across trading, brokerage, and custodial systems creates a trusted layer for innovation, and learn the realities of deploying agentic AI in a regulated broker-dealer environment. Gain practical insights into architecture patterns, governance, real-time data access, key tradeoffs, and lessons learned that can help accelerate your own modernization and AI initiatives. This presentation is brought to you by Cognizant, an AWS Partner.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441484625001Gp70", "sources": ["business_agents"], "ko_desc": "LPL Financial이 3.2만+ 재무 어드바이저를 지원하는 상시 운영 트레이딩 플랫폼을 AWS 멀티 리전 아키텍처로 구축한 사례 (Cognizant 스폰서).", "company": "LPL Financial (Cognizant)", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ212-S", "title": "Engineering AI Agents You Can Trust in Production (sponsored by Workato)", "abstract": "Your agent nails the demo, then breaks in production. More often than not, the model isn't what failed, it's everything around it. We'll walk through a methodology for making agent actions reliable, recoverable, and observable in production. You'll leave with patterns you can build yourself, drawn from lessons learned over 100+ enterprise MCP deployments. This presentation is brought to you by Workato, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442266865001cvNl", "sources": ["business_agents"], "ko_desc": "데모에서는 작동하지만 프로덕션에서 깨지는 에이전트의 문제 — 모델이 아닌 주변 환경 실패를 해결하는 에이전트 신뢰성 방법론 (Workato 스폰서).", "company": "Workato", "thu_am": false, "start_time": "12:00", "length": 20}, {"code": "BIZ205-S", "title": "MCP is Just An MVP. Context Layers Are The Sequel. (sponsored by Atolio)", "abstract": "MCP lets agents connect to systems. It's a minimum viable product, not a complete way to run that connection at scale. Raw database access hit the same wall decades ago, before warehouses and data lakes brought structure and governance at scale. Point-to-point agent connections hit it again: costs climb with every added tool call, latency stacks with every cross-system hop, and permissions rarely travel with retrieved data, making synthesized knowledge a sharper security risk than raw SQL ever posed. This session traces that history, breaks down each failure mode, and maps what a sovereign context layer built for agents solves. This presentation is brought to you by Atolio, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442270797001crf1", "sources": ["business_agents"], "ko_desc": "MCP는 최소 기능 제품일 뿐 — 데이터베이스에 SQL로 직접 접근하던 시대처럼 에이전트 연결도 구조화된 컨텍스트 레이어가 필요한 이유 (Atolio 스폰서).", "company": "Atolio", "thu_am": null, "start_time": "14:00", "length": 20}, {"code": "AIM262-S", "title": "One Control Plane for Every Agent: Architecture Patterns for Cost, Risk, and ROI (sponsored by Boomi)", "abstract": "Every agent call carries cost, permission, and blast radius, and as agents multiply across tools, frameworks, and SaaS, the gaps compound: uncapped spend, unapproved permissions, no shared record. This session breaks down an AI infrastructure layer, running on AWS, that governs every model, agent, and system. A design-time layer publishes an approved catalog of agents, tools, and MCP servers; a runtime layer routes, meters, and enforces policy on every call before it executes. See how spend caps, in-tenant SLMs, and governed APIs turn cost into a controlled input, while one trace gives finance, security, and engineering a shared, audit-ready record. This presentation is brought to you by Boomi, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441488321001GLwW", "sources": ["business_agents"], "ko_desc": "에이전트가 증가할수록 도구·프레임워크·SaaS 간 비용·권한·리스크 격차가 복합화 — 모든 에이전트를 위한 단일 컨트롤 플레인 아키텍처 패턴 (Boomi 스폰서).", "company": "Boomi", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "AIM268-S", "title": "Setting up the Right AI Architecture: Bringing Together Agents, Teams, and Context (sponsored by Notion)", "abstract": "Every organization is building their AI architecture in real-time: deciding which agents to use, which data sources to connect them to, and figuring how to get teams to collaborate across it all. These different layers have been arranged over many years of procuring tools, but can sometimes feel like a jumbled mess in the AI era. This session offers a practical way to reexamine your tech architecture. We'll cover four patterns that recur across organizations as they try to structure their business for the AI era, plus pitfalls to avoid to ensure your tech stack is optimized for AI. This presentation is brought to you by Notion, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442268303001cUZA", "sources": ["business_agents"], "ko_desc": "실시간으로 AI 아키텍처를 구축하는 조직의 과제 — 어떤 에이전트를 사용할지, 어떤 데이터 소스를 연결할지, 팀이 어떻게 협업할지 결정하는 방법 (Notion 스폰서).", "company": "Notion", "thu_am": false, "start_time": null, "length": 20}, {"code": "INV522", "title": "The Evaluator Is the Algorithm: Evolving SOTA for $15", "abstract": "We discovered a phase transition in LLM-guided code evolution: when the evaluation function provides smooth gradient signal, SOTA emerges automatically regardless of model choice; when it doesn't, no compute compensates. This \"evaluator-dominance principle\" emerged from stress-testing evolutionary search across 403 problems in 27 domains on Amazon Bedrock — 20× the scale of Google's original AlphaEvolve — achieving 96% SOTA-matching at $15/problem median cost. We'll present the Bedrock-native architecture (MAP-Elites, staged evaluation cascade, Opus/Haiku phase routing), a production vehicle routing deployment saving 1.28% on 100,000-customer routes at $530 total spend, and the evaluator design methodology that determines success or failure.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Architecture, Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1780441494589001GmFd", "sources": ["business_agents"], "ko_desc": "LLM 기반 코드 진화에서 평가 함수가 부드러운 그래디언트를 제공할 때 SOTA가 자동으로 나타나는 위상 전환 현상 발견 — $15로 최신 성능 달성.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "COM341", "title": "The AgentCore Governance Loop: Policy, Guardrails, Observability", "abstract": "Building an agent takes an afternoon. Operating it safely across a team takes architecture. In this session learn how to build a multi-agent reference platform on Amazon Bedrock AgentCore and walk the full governance loop including cataloging agents for discovery, enforcing what they can do with Cedar policy at the gateway, filtering what they can say with Guardrails, and tracing behavior through observability. You will learn where the pieces integrate cleanly and where the seams break. You leave with a governance reference architecture you can adapt to any agentic workload, plus the lessons the documentation leaves out.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Architecture, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780442262536001cmiG", "sources": ["business_agents"], "ko_desc": "에이전트 구축은 오후 한나절, 안전하게 팀 운영하기는 아키텍처 필요 — Bedrock AgentCore로 멀티 에이전트 레퍼런스 플랫폼 구축과 전체 거버넌스 루프 시연.", "company": "AWS", "thu_am": null, "start_time": "17:00", "length": 20}, {"code": "SEC229-S", "title": "From Signals to Action for Sempra: AI-Powered Cybersecurity on AWS (sponsored by Accenture)", "abstract": "AI is reshaping cybersecurity, but security teams must act faster without adding complexity. Sempra Energy, AWS, and Accenture deployed Accenture Cyber.AI on AWS to create a unified view of cyber risk and identify the highest-priority actions across the enterprise. Learn how the team integrated existing security investments, addressed governance and architecture requirements, and operationalized AI-driven risk management. Speakers will share key design decisions, implementation lessons, and practical guidance for using AI to improve cyber resilience, strengthen security operations, and maintain control of data and infrastructure in cloud environments. This presentation is brought to you by Accenture, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Architecture, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1780442390285001Nizk", "sources": ["business_agents"], "ko_desc": "Sempra Energy가 AWS와 Accenture의 Cyber.AI로 사이버 위험의 통합 뷰를 확보하고 위협을 신속히 식별한 사례 (Accenture 스폰서).", "company": "Sempra Energy (Accenture)", "thu_am": true, "start_time": "11:00", "length": 20}, {"code": "ARC320-R1", "title": "Cell-based architecture: Designing blast-radius boundaries", "abstract": "Cell-based architecture limits the blast radius of failures by partitioning systems into independent, isolated units. But deciding cell boundaries — by customer, geography, or workload — involves trade-offs between operational complexity and fault isolation. This session reveals the decision framework for cell sizing, routing, and cross-cell coordination. You'll learn when cells outperform active-active patterns, how to implement cell-aware deployments, and the true operational cost of cell management. Walk away with a reusable pattern for systems, where failures stay contained, impact reduced, and availability increased.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Architecture, Cloud Operations", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358242205001iNE9", "sources": ["customer_story"], "ko_desc": "셀 기반 아키텍처로 장애 영향 범위를 제한 — 셀 경계를 고객·지역·워크로드 중 무엇으로 나눌지 트레이드오프와 의사결정 프레임워크.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "NET216-R1", "title": "Understand your network: practical network observability on AWS", "abstract": "You're collecting Amazon VPC Flow Logs and Amazon CloudWatch metrics, but still can't answer \"why can't this instance reach the internet?\" In this chalk talk, explore practical approaches to network observability on AWS, no deep expertise required. Cover the key logs and metrics that actually matter, how to read them, and how to set up simple dashboards and alerts that tell you something is wrong before your users do. Bring your monitoring questions, and we'll discuss real scenarios to help you build observability that works for your team.", "type": "Chalk talk", "level": "200 – Intermediate", "topic": "Architecture, Cloud Operations", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1790358222517001iUyP", "sources": ["customer_story"], "ko_desc": "VPC Flow Logs·CloudWatch가 있어도 '왜 인터넷에 안 되지?'에 답 못하는 팀을 위한 실용적 네트워크 옵저버빌리티 가이드.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "CMP348-R1", "title": "Building better quantum computers with digital twins", "abstract": "Quantum computers could revolutionize fields like pharmacy and logistics, but today's hardware is too error-prone for practical use. To design better error-correction strategies, simulating how real quantum hardware operates is essential, yet computationally intractable. In this talk, we demonstrate quantum processor digital twins developed by Quantum Elements and powered by AWS HPC infrastructure - that faithfully mimic real hardware at experimental scale. Attendees will leave understanding why error correction matters and how classical compute accelerates the path to useful quantum computing.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Architecture, Compute", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Wynn/Encore", "sessionID": "1790358216277001iq8q", "sources": ["customer_story"], "ko_desc": "Quantum Elements가 AWS HPC로 양자 프로세서 디지털 트윈을 구축 — 실제 하드웨어를 시뮬레이션해 오류 보정 전략을 설계하는 방법.", "company": "Quantum Elements", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "HMC409-R1", "title": "Deployment strategies for highly available edge applications", "abstract": "Organizations need to be able to deploy critical applications that are highly available and fault-tolerant at the edge. These workloads are often some of the most demanding in terms of durability and availability requirements. Deploying workloads on AWS hybrid cloud and edge computing services like AWS Local Zones and AWS Outposts requires planning for networking, compute, storage, and other failure modes. In this chalk talk, dig into each of these services, review use cases, and examine reference architectures. Learn design considerations and deployment patterns for high availability and disaster recovery.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Architecture, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1790358246918001is3u", "sources": ["customer_story"], "ko_desc": "엣지 환경(Local Zones·Outposts)에서 고가용성 애플리케이션 배포 전략 — 네트워크·컴퓨팅·스토리지 계획과 장애 대응 패턴.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AMZ401-R1", "title": "How Amazon Ads Built a Service Mesh Without a Control Plane Service", "abstract": "Most service meshes require dedicated infrastructure just to manage the mesh itself. Amazon Ads took a different approach: a fully serverless xDS control plane built with AWS Lambda and S3 that manages hundreds of Envoy proxies serving 100K+ requests per second at 2ms p99 overhead with no long-running control plane servers. In this session, we walk through the architecture end to end: Envoy sidecars on Amazon ECS for service-to-service communication, an edge proxy for external ingress, and the serverless control plane that ties it together.", "type": "Code talk", "level": "400 – Expert", "topic": "Architecture, Migration & Modernization, Serverless", "area_of_interest": "", "industry": "Advertising & Marketing, Media & Entertainment", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358246003001iotM", "sources": ["customer_story"], "ko_desc": "Amazon Ads가 장기 실행 컨트롤 플레인 서버 없이 Lambda+S3로 완전 서버리스 xDS 컨트롤 플레인 구축 — 초당 100K+ 요청, p99 2ms 달성 사례.", "company": "Amazon Ads", "thu_am": null, "start_time": null, "length": 60}, {"code": "NET101", "title": "What's new in eero networking ", "abstract": "Join us to learn about the latest innovations in eero networking. This session covers new capabilities in AI-powered network analytics, simplified connectivity, centralized security, and multi-WAN resilience - all built cloud-native and designed to scale.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Architecture, Networking & Content Delivery", "area_of_interest": "", "industry": "", "features": "Customer story, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1780441472395001Gj5P", "sources": ["customer_story"], "ko_desc": "eero 네트워킹의 최신 기능 소개 — AI 기반 네트워크 분석·간소화된 연결·중앙화 보안·멀티-WAN 복원력.", "company": "Amazon (eero)", "thu_am": null, "start_time": null, "length": 60}, {"code": "COM328-R1", "title": "Autonomous Remediation with OpenTelemetry and DevOps Agent", "abstract": "You instrumented everything. You have metrics, logs, and traces. And when production breaks a human still has to piece it together, tab by tab, signal by signal, under pressure. That is not an observability problem, it’s an automation problem. We'll show you an architecture on AWS that closes it. OpenTelemetry captures signals across EKS, ECS, and Lambda. AWS DevOps Agent runs the investigation, finds the root cause, and prepares the fix. By the time a human looks at it, the pull request is ready. Come learn the triggers, investigation loop, and guardrails you need before letting an agent touch production.", "type": "Code talk", "level": "300 – Advanced", "topic": "Architecture, Open Source", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1790358241012001io9D", "sources": ["customer_story"], "ko_desc": "OpenTelemetry + AWS DevOps Agent로 프로덕션 장애를 자율 복구 — 사람이 탭을 넘나들며 신호를 조각 맞추는 대신 에이전트가 조사·수정·검증.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "PEX311-R1", "title": "Agentic AI Governance for Regulated Industries", "abstract": "As agentic AI expands into regulated industries, autonomous decisions must meet compliance before production. This session gives partners a governance framework spanning technical and non-technical requirements — not just architecture. We demo a working multi-agent system and share the code.", "type": "Code talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358224155001iBqU", "sources": ["customer_story"], "ko_desc": "규제 산업 에이전틱 AI 거버넌스 프레임워크 — 기술적·비기술적 컴플라이언스 요건을 모두 충족하는 멀티 에이전트 시스템 데모.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "INV503-R1", "title": "Beyond Benchmarks: Evaluating AI Safety with Formal Guarantees", "abstract": "As AI systems become increasingly capable and autonomous, safety evaluation is emerging as a critical challenge. While current evaluations largely rely on benchmark performance and empirical red-teaming, these approaches provide limited guarantees about real-world risk. This talk will explore an emerging direction in AI safety: evaluating model behavior with formal statistical guarantees. We will discuss how ideas from reliability engineering, robustness certification, and risk assessment can be applied to quantify catastrophic failure probabilities, the assumptions behind such guarantees, and their implications for deploying and governing frontier AI systems. This topic is highly relevant to the future of trustworthy and accountable AI.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Wynn/Encore", "sessionID": "1780441495791001G9Dz", "sources": ["customer_story"], "ko_desc": "AI 시스템이 점점 자율화됨에 따라 안전성 평가도 진화 필요 — 벤치마크·레드팀을 넘어 통계적 형식 보장으로 실제 위험을 측정하는 새로운 접근법.", "company": "AWS", "thu_am": null, "start_time": "08:00", "length": 60}, {"code": "IND367-R", "title": "Building the semantic intelligence layer for enterprise AI agents", "abstract": "Every AI agent in the enterprise reasons better when it shares a common semantic understanding of the business. In this chalk talk, we show you how to build an Agentic Intelligence Layer that resolves meaning across every system and makes it innately consumable by any agent. We break down how to combine semantic embeddings, knowledge graph relationships, and natural-language memories into a single, governed layer that every agent reads from and writes back to. We take product and customer intelligence as the first domains and show how the same architecture extends to supply chain, operations, finance, and workforce. The result is a semantic intelligence layer that compounds learning across the business and transforms everything from demand forecasting to conversational commerce to enterprise decision-making.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion, Full", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780442246426001cqWi", "sources": ["retail"], "ko_desc": "엔터프라이즈 AI 에이전트가 더 잘 추론하려면 공통 시맨틱 이해가 필요 — 기업 전반의 의미를 해석하는 에이전틱 인텔리전스 레이어 구축법.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "IND367-R1", "title": "Building the semantic intelligence layer for enterprise AI agents", "abstract": "Every AI agent in the enterprise reasons better when it shares a common semantic understanding of the business. In this chalk talk, we show you how to build an Agentic Intelligence Layer that resolves meaning across every system and makes it innately consumable by any agent. We break down how to combine semantic embeddings, knowledge graph relationships, and natural-language memories into a single, governed layer that every agent reads from and writes back to. We take product and customer intelligence as the first domains and show how the same architecture extends to supply chain, operations, finance, and workforce. The result is a semantic intelligence layer that compounds learning across the business and transforms everything from demand forecasting to conversational commerce to enterprise decision-making.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion, Full", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1790358216181001iC2j", "sources": ["retail"], "ko_desc": "엔터프라이즈 AI 에이전트가 더 잘 추론하려면 공통 시맨틱 이해가 필요 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "IND3334", "title": "How Jack in the Box delivers personalized store reporting at scale ", "abstract": "Franchise operators run restaurants, not BI tools. In this session, learn how Jack in the Box delivered store-specific performance reports and actionable insights straight to every operator's inbox across 2,100+ locations. We'll cover throttle-aware parallel orchestration, failure isolation patterns, and how this approach turns business intelligence into a scalable, zero-friction communication channel that drives operator engagement and revenue. Walk away with a reusable blueprint for high-volume, per-location reporting in any multi-unit retail or restaurant business", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Lecture-style, Walk up only", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780442264068001crxb", "sources": ["retail"], "ko_desc": "Jack in the Box가 AI로 2,100개 이상 프랜차이즈 점주 각각에게 맞춤형 매장 성과 보고서를 자동 배달 — 운영자가 BI 도구 없이도 실행 가능한 인사이트를 받는 방법.", "company": "Jack in the Box", "thu_am": null, "start_time": "16:30", "length": 20, "room": "Level 2 | Hall B | Expo | Industry Theater"}, {"code": "INV508-R1", "title": "How neurosymbolic AI formalizes natural language into verifiable logic", "abstract": "Organizations want to automate enforcement of critical rules—financial, legal, regulatory—yet those rules live in ambiguous natural-language documents. Bridging this gap is error-prone and expensive. In this session, we show how neurosymbolic AI enables subject-matter experts to formalize natural-language rules into mathematical logic—capturing the original intent in an unambiguous, executable, and verifiable form. We cover the mathematical foundations and demonstrate through practical examples how formalized rules can serve as agent guardrails, compliance checks, and trusted knowledge sources. Attendees will leave with a deep understanding of how neurosymbolic techniques can help them formalize and operationalize their own domain rules.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Wynn/Encore", "sessionID": "1780441495902001Gsnk", "sources": ["customer_story"], "ko_desc": "금융·법률·규제 문서 같은 자연어 규칙을 뉴로심볼릭 AI로 수학적 논리로 변환 — 전문가가 의도를 정확히 인코딩하고 자동 집행 가능하게 만드는 방법.", "company": "AWS", "thu_am": null, "start_time": "09:00", "length": 60}, {"code": "AIM355-R1", "title": "Strengthen identity verification with Amazon Rekognition", "abstract": "Learn how to use Amazon Rekognition Face Liveness to help confirm a real person is present during digital onboarding. This session explores how to integrate liveness checks into your application, detect spoofing attempts, and support identity verification workflows.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358217311001ieZk", "sources": ["customer_story"], "ko_desc": "Amazon Rekognition Face Liveness로 디지털 온보딩 중 실제 사람 존재 확인 — 스푸핑 탐지와 신원 검증 워크플로우 통합 방법.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "INV531", "title": "Visual reasoning will be bigger than language reasoning", "abstract": "Today’s vision-language models can describe images fluently, yet still struggle with the spatial and perceptual reasoning required for robotics. This talk argues that visual reasoning—reasoning through points, sketches, trajectories, depth maps, and other grounded representations—will become more important than language reasoning for physical agents. It traces progress from benchmarks exposing fundamental perception failures to methods that teach models to reason directly in visual space. These ideas culminate in robotics foundation models that convert visual plans into robot actions. The resulting systems are interpretable, steerable, deployable zero-shot on affordable hardware, and competitive with proprietary models trained on substantially more data. We showcase how these ideas are advancing the goal of accessible, general-purpose robotics to the broader research community.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Discussion, Full", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780441495114001GRLB", "sources": ["robotics"], "ko_desc": "시각적 추론이 언어 추론보다 더 중요해질 것 — 로보틱스의 공간·지각 추론을 위한 비전 언어 모델의 근본적 한계와 돌파구.", "company": "AWS", "thu_am": null, "start_time": "16:30", "ko_full": "오늘날의 비전-언어 모델은 이미지를 유창하게 묘사하지만, 로보틱스에 필요한 공간·지각 추론에는 여전히 어려움을 겪습니다. 이 발표는 점, 스케치, 궤적, 깊이 맵 같은 grounded 표현을 통한 시각 추론이 물리 에이전트에게는 언어 추론보다 더 중요해질 것이라고 주장합니다.\n근본적인 지각 실패를 드러낸 벤치마크에서 출발해, 모델이 시각 공간에서 직접 추론하도록 가르치는 방법까지의 진전을 짚습니다. 이 아이디어는 시각적 계획을 로봇 동작으로 변환하는 로보틱스 파운데이션 모델로 귀결됩니다. 그 결과 시스템은 해석 가능하고 조향(steer)할 수 있으며, 저렴한 하드웨어에 제로샷으로 배포할 수 있고, 훨씬 많은 데이터로 학습한 독점 모델과 견줄 만합니다. 접근 가능한 범용 로보틱스라는 목표를 이 아이디어들이 어떻게 앞당기고 있는지를 더 넓은 연구 커뮤니티에 보여드립니다.", "length": 60, "room": "Level 1 | Forum 114"}, {"code": "INV527", "title": "World models for indoor robots: what breaks and why", "abstract": "World models promise to give robots predictive understanding of their environment, yet applying them to indoor robotics exposes fundamental gaps in how transformers reason about geometry. In this session, we present findings from building a trajectory-conditioned lidar world model for Diligent Robotics' hospital fleet on AWS. We examine why standard loss metrics fail for generative spatial predictions, why rotation breaks factored attention even with explicit conditioning, and the minimal set of inductive biases needed to restore geometric coherence. Attendees leave with a diagnostic framework for spatial reasoning failures in transformer-based world models.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1780441494886001G2fr", "sources": ["robotics"], "ko_desc": "실내 로봇을 위한 월드 모델 적용 시 드러나는 한계 — 트랜스포머가 기하학적 추론에서 실패하는 근본 원인과 해결 방향.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "IND366", "title": "Zero-Shot Demand Forecasting with Chronos 2, SMUS, and Quick Suite", "abstract": "Stockouts and overstocks quietly erode margin for retail and CPG brands, driving lost sales, markdowns, and working capital tied up in the wrong inventory. Traditional forecasting models take months to train and tune, and struggle with the cold-start problem for new products and locations. In this chalk talk, we whiteboard how to architect zero-shot demand forecasting pipelines using Amazon SageMaker Unified Studio with the Chronos 2 time-series foundation model, developed by the Amazon Science team and proven on Amazon's own retail and CPG demand at scale, requiring no historical model training. We walk through the end-to-end design: SMUS notebooks for rapid experimentation, Chronos 2 for multi-variate time series prediction, and Amazon Quick Suite for conversational analytics that let planners explore forecasts in natural language..", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780442246369001c58q", "sources": ["retail"], "ko_desc": "Chronos 2와 SMUS로 리테일·CPG 브랜드의 제로샷 수요 예측 — 수개월 걸리던 예측 모델 학습 없이 실시간 재고 최적화.", "company": "AWS", "thu_am": null, "start_time": "09:00", "ko_full": "결품과 과잉 재고는 리테일·CPG 브랜드의 마진을 조용히 갉아먹습니다. 판매 기회를 잃고, 가격 인하(마크다운)가 발생하고, 운전자본이 엉뚱한 재고에 묶이게 됩니다. 기존 수요예측 모델은 학습과 튜닝에 수개월이 걸리고, 신제품과 신규 지점에 대한 콜드스타트 문제에도 취약합니다.\n이 칠크 토크에서는 Amazon SageMaker Unified Studio(SMUS)와 Chronos 2 시계열 파운데이션 모델을 사용해 제로샷 수요예측 파이프라인을 설계하는 방법을 화이트보드로 풀어갑니다. Chronos 2는 Amazon Science 팀이 개발했고 Amazon 자체의 리테일·CPG 수요 데이터에서 대규모로 검증되었으며, 과거 데이터로 모델을 학습시킬 필요가 없습니다.\n엔드투엔드 설계를 차례로 살펴봅니다. 빠른 실험을 위한 SMUS 노트북, 다변량 시계열 예측을 위한 Chronos 2, 그리고 기획자가 자연어로 예측 결과를 탐색할 수 있게 해주는 대화형 분석용 Amazon Quick Suite입니다.", "length": 60}, {"code": "IND3307", "title": " Unified Commerce Intelligence for Amazon Brands on Amazon Quick", "abstract": "Brands selling on Amazon generate rich signals across commerce and advertising — order trends, catalog performance, competitive pricing, campaign metrics, and customer engagement. The opportunity lies in connecting these signals into a unified view that drives faster, smarter decisions. In this chalk talk, we design an architecture that composes two Model Context Protocol (MCP) servers — the SP-API MCP Server for Selling Partner operations and the Amazon Ads MCP Server for campaigns and reporting — behind Amazon Quick as a conversational layer. We'll whiteboard how brands can build cross-domain queries, like correlating ad spend with order velocity or surfacing catalog insights that inform campaign strategy. Leave with production-grade patterns for building agentic commerce workflows tailored to your brand's data", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1780442245351001cSyN", "sources": ["retail"], "ko_desc": "Amazon에서 판매하는 브랜드를 위한 통합 커머스 인텔리전스 — 주문 트렌드·카탈로그·경쟁 가격·광고 지표·고객 참여 신호를 Amazon Quick으로 연결.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "SNR303", "title": "A leader's guide to advanced teams models in an agentic world", "abstract": "Agents made execution cheap. The work did not disappear. It moved into deciding what should exist, checking what agents produce, and owning it when something breaks. Most team designs were not built for that. This session gives you four questions to ask of any piece of work: what is it for, what does it touch, how will we check it, and whose name is on it. Then we walk through the team models leaders reach for, what each gets wrong, and where the pager and the name should sit. You leave knowing who does what now.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780442221125001cULv", "sources": ["business_agents"], "ko_desc": "에이전트가 실행을 저렴하게 만든 세상에서 팀 설계의 변화 — 무엇을 만들지 결정하고, 에이전트 산출물을 검토하고, 문제 발생 시 책임지는 새로운 역할 모델.", "company": "AWS", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "SNR316", "title": "A leader's guide to moving from AI investment gridlock to acceleration", "abstract": "Fund the platform or the use case? Demand proof before investing, or invest to generate the proof? These decisions determine whether AI compounds or stalls, and can't wait for the annual budget cycle. To move at the pace of AI, the CIO and CFO must be in lockstep. Two former operators share how the best pairs manage AI like a venture portfolio: bets in the face of uncertainty, recycling of wins into the next ones, and governance that scales across the portfolio rather than project by project — plus the key questions every pair should answer before their next AI investment.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1783654976546001dEAE", "sources": ["business_agents"], "ko_desc": "플랫폼 투자 vs 사용 사례 투자? 증거 요구 vs 증거 생성을 위한 투자? AI 투자 교착 상태를 타개하는 리더 가이드.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "SNR301", "title": "A leader's guide to predicting and proving AI value", "abstract": "Every organization faces the same AI questions: How do we predict and manage costs? How do we prove value when outcomes are hard to measure? How do we move fast without losing control? Two finance leaders, one advising enterprise executives and one managing AI economics at scale inside Amazon, share what is working, what is not, and where teams go wrong. Learn how to measure AI cost and value in terms finance and technology leaders agree on, which guardrails to set as investment grows, and how to make the case for AI value to your board.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780442221009001cooY", "sources": ["business_agents"], "ko_desc": "AI 비용을 예측·관리하고 가치를 증명하는 방법 — 두 명의 재무 리더가 공유하는 통제력을 잃지 않으면서 빠르게 움직이는 프레임워크.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "SNR320", "title": "A leader's guide to what separates AI leaders from the rest", "abstract": "In early 2026, the Reimagine research program interviewed senior technology leaders under conditions of candor: off-the-record, non-attributable, no marketing follow-up. What they said contradicts the prevailing conference narrative. Nobody is running agents autonomously, not one. The most advanced organizations are carrying the most technical debt. The AI generating real value looks nothing like the demos. This session synthesizes the patterns that emerged when executives stopped performing confidence and started sharing reality. ", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1783654976796001dH2c", "sources": ["business_agents"], "ko_desc": "2026년 초 비공개 인터뷰에서 시니어 기술 리더들이 솔직하게 밝힌 내용 — 일반적인 콘퍼런스 내러티브와 다른 AI 리더와 후발주자의 실제 차이.", "company": "AWS (Reimagine 리서치)", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "SNR306", "title": "A leader’s guide to governing AI, on behalf of humans", "abstract": "AI deployments can reason, problem-solve, and act with increasing agency. Leaving governance models built for deterministic software no longer sufficient.\nAWS Executive in Residence Ryan Seaman and Dr. Bernadette Han, organizational psychologist at the American Psychological Association (APA), bring technology and human behavior into one governance conversation. As AI interacts with people, influences decisions, and takes actions, governance must address not only what AI can do, but how it behaves with people and what happens as a result.\nBernadette introduces the EEI-AI Behavioral Architecture™, translating psychological science into behavioral requirements organizations can design for, test, observe, and govern responsibly.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442221285001cwfU", "sources": ["business_agents"], "ko_desc": "결정론적 소프트웨어용으로 만들어진 거버넌스 모델은 자율적 AI에 더 이상 충분하지 않다 — 인간을 대신해 AI를 통치하는 새로운 접근법.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM115-S", "title": "Agentic AI Control Plane on AWS: govern agents at enterprise scale (sponsored by Tata Consultancy Services)", "abstract": "Enterprises are moving from a handful of agents to hundreds. Without a shared layer for identity, policy, orchestration, and observability, that growth stalls. In this 20-minute launch session, we introduce the Agentic AI Control Plane on AWS: a governed foundation for building, deploying, and running agents across business and IT workflows. See how it handles agent onboarding, guardrails, cost and performance visibility, and human oversight, with a live look at the platform. Built for CIOs, data and AI leaders, and platform and risk teams who need agent fleets to scale safely, with the controls their auditors expect. This presentation is brought to you by Tata Consultancy Services, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442268608001cY23", "sources": ["business_agents"], "ko_desc": "수백 개의 에이전트가 운영될 때 공유 아이덴티티·정책·오케스트레이션·옵저버빌리티 레이어 없이는 성장이 멈춘다 — TCS가 소개하는 에이전틱 AI 컨트롤 플레인 (스폰서).", "company": "Tata Consultancy Services", "thu_am": null, "start_time": "14:00", "length": 20}, {"code": "BIZ207-S", "title": "Building AI Agents with Vercel and AWS (sponsored by Vercel)", "abstract": "This session explores how Vercel and AWS work together to support the development and deployment of AI agents. You’ll learn about first party connectivity to AWS databases and services through the Vercel Marketplace, along with the backend capabilities agents need, including APIs, durable workflows, queues, cron jobs, and MCP servers. You’ll see how these building blocks, together with the EVE framework, can simplify agent development, followed by a live demo showing how to build an agent using Vercel and AWS. This presentation is brought to you by Vercel, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441484017001GOuD", "sources": ["business_agents"], "ko_desc": "Vercel과 AWS가 AI 에이전트 개발·배포를 지원하는 방법 — Vercel Marketplace를 통한 AWS 데이터베이스·서비스 연결 (Vercel 스폰서).", "company": "Vercel", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AIM2211", "title": "From Cost to Compliance: Scaling Scalable GenAI with Amazon Nova", "abstract": "Enterprises putting generative AI into production face three converging pressures: controlling inference cost at scale, meeting compliance and data-residency requirements, and migrating off incumbent models without losing accuracy  or quality. Amazon Nova is purpose-built for this reality. In this session, learn how organizations across regulated  and cost-sensitive industries are standardizing on Amazon Nova to run high-volume GenAI workloads at a fraction of the  cost while meeting strict compliance requirements.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442260561001ceXP", "sources": ["business_agents"], "ko_desc": "프로덕션 생성형 AI의 세 가지 과제 — 추론 비용 통제, 컴플라이언스·데이터 레지던시 충족, 기존 모델에서 Amazon Nova로 마이그레이션.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 20}, {"code": "IND418-R1", "title": "From documents to decisions: Agentic AI for federal operations", "abstract": "Accelerate mission-critical federal operations with agentic AI—from public-information analysis to sensitive document workflows. This expert chalk talk explores patterns for document review, supply chain optimization and classified medical health records backed by real-world implementations. Whiteboard multi-agent orchestration with Amazon Bedrock, including least-privilege tool access, human approval, auditability, and failure recovery. Compare Amazon Bedrock AgentCore for eligible workloads such as regulatory review, grants, and benefits processing with FEDRAMP (Class C and D). Further explore container-based agent architectures for IL4/IL5 environments using authorized AWS services and models. ", "type": "Chalk talk", "level": "400 – Expert", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "Government", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Wynn/Encore", "sessionID": "1790358250283001iYiG", "sources": ["business_agents"], "ko_desc": "연방 기관의 미션 크리티컬 운영을 에이전틱 AI로 가속화 — 공개 정보 분석부터 민감 문서 워크플로우까지, 문서 검토·공급망 최적화 패턴.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "IND418-R", "title": "From documents to decisions: Agentic AI for federal operations", "abstract": "Accelerate mission-critical federal operations with agentic AI—from public-information analysis to sensitive document workflows. This expert chalk talk explores patterns for document review, supply chain optimization and classified medical health records backed by real-world implementations. Whiteboard multi-agent orchestration with Amazon Bedrock, including least-privilege tool access, human approval, auditability, and failure recovery. Compare Amazon Bedrock AgentCore for eligible workloads such as regulatory review, grants, and benefits processing with FEDRAMP (Class C and D). Further explore container-based agent architectures for IL4/IL5 environments using authorized AWS services and models. ", "type": "Chalk talk", "level": "400 – Expert", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "Government", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1780442245724001crrE", "sources": ["business_agents"], "ko_desc": "연방 기관의 미션 크리티컬 운영을 에이전틱 AI로 가속화 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "AIM457-S", "title": "From reactive operations to autonomous resilience: How Agentic AI is redefining SRE (sponsored by HCLTech)", "abstract": "Traditional SRE was built to restore systems quickly, but today’s complex, distributed environments demand more than reactive operations. This lightning session explores how agentic AI is redefining SRE by enabling autonomous detection, decision-making, remediation, and continuous learning. It examines how observability can extend beyond infrastructure metrics to connect system health with customer experience and business outcomes. Attendees will learn how AI, observability, and operations are converging to create resilient, self-optimizing environments, why autonomous resilience is becoming a competitive advantage, and the practical steps organizations can take to progress toward Level 5 autonomous operations while retaining appropriate human oversight and governance This presentation is brought to you by HCLTech, an AWS Partner.", "type": "Lightning talk", "level": "400 – Expert", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442269174001cP7n", "sources": ["business_agents"], "ko_desc": "복잡한 분산 환경에서 SRE를 에이전틱 AI로 재정의 — 반응적 복구에서 자율적 복원력으로, 사전 예방적 문제 해결 (HCLTech 스폰서).", "company": "HCLTech", "thu_am": false, "start_time": "13:00", "length": 20}, {"code": "AIM116-S", "title": "Fuel Intelligent AI Agents with Trusted Enterprise Data (sponsored by Informatica)", "abstract": "To unlock transformative business outcomes, AI agents require a foundation of trusted data with rich enterprise context. Delivering success means bridging the knowledge, trust, and action gaps across a highly complex data landscape. In this session, learn how Informatica Intelligent Data Management Cloud (IDMC) provides the comprehensive AI-ready data needed to power reliable agentic workflows. Explore how headless IDMC architecture via integrations with Amazon Bedrock AgentCore, Agent Registry and Amazon Quick fuels agents with trusted enterprise context and end-to-end governance, driving impactful results and long-term project success. This presentation is brought to you by Informatica, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442269822001ckp6", "sources": ["business_agents"], "ko_desc": "AI 에이전트가 신뢰할 수 있는 엔터프라이즈 데이터 기반을 필요로 하는 이유 — 지식·신뢰·행동 격차를 해소하는 데이터 기반 구축 방법 (Informatica 스폰서).", "company": "Informatica", "thu_am": null, "start_time": "13:00", "length": 20}, {"code": "PEX303-R1", "title": "Govern, Bill, and Attribute: The Unit Economics of Production Agents", "abstract": "Your agent demo costs $0.02 a call; in production it's $4. Can you still price it profitably, and can you capture the full AWS consumption it drives downstream? This chalk talk walks the complete unit economics of a production agent: right-sizing cost with prompt caching, model routing, and tool-call minimization; pricing through consumption versus outcome-based billing; and attributing the full impact through AWS Marketplace metering and PRM, so it converts into AWS investment back to you. Real examples like bid optimization, content moderation, and shopping advisors ground each step.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358232666001iFKx", "sources": ["business_agents"], "ko_desc": "데모에서 $0.02이던 에이전트 호출이 프로덕션에서 $4가 되는 이유 — 생산 에이전트의 단위 경제와 수익성 있는 가격 책정, AWS 소비량 추적 방법.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "PEX303-R", "title": "Govern, Bill, and Attribute: The Unit Economics of Production Agents", "abstract": "Your agent demo costs $0.02 a call; in production it's $4. Can you still price it profitably, and can you capture the full AWS consumption it drives downstream? This chalk talk walks the complete unit economics of a production agent: right-sizing cost with prompt caching, model routing, and tool-call minimization; pricing through consumption versus outcome-based billing; and attributing the full impact through AWS Marketplace metering and PRM, so it converts into AWS investment back to you. Real examples like bid optimization, content moderation, and shopping advisors ground each step.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442248751001c237", "sources": ["business_agents"], "ko_desc": "데모에서 $0.02이던 에이전트 호출이 프로덕션에서 $4가 되는 이유 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "09:00", "length": 60}, {"code": "IND328", "title": "How Blue Origin built a centralized enterprise knowledge graph on AWS", "abstract": "Building enterprise AI applications shouldn't require every team to reinvent the wheel — standing up data pipelines, managing security, and keeping knowledge bases current. Blue Origin faced this at scale: dozens of teams, hundreds of data sources, and growing demand for AI apps that could reason across all of it. The answer was RAGNet — a centralized enterprise knowledge graph platform built on Amazon Neptune and Amazon Bedrock that aggregates structured and unstructured data into a secure, always-current graph any developer or AI agent can query in plain natural language.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "Government", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1780441475601001GnFO", "sources": ["business_agents"], "ko_desc": "Blue Origin이 AWS에서 중앙화된 엔터프라이즈 지식 그래프 구축 — 수십 개 팀이 데이터 파이프라인을 재발명하지 않아도 되는 공유 AI 애플리케이션 기반.", "company": "Blue Origin", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "COM318", "title": "KYC in 90 Seconds: Real-Time Onboarding with AgentCore", "abstract": "Opening a bank account should take seconds, not days. This session shows how AI agents can speed up KYC while keeping the final decision under control, specialized agents that run on Agentcore Harness investigate identity, documents, fraud signals, and screening results, with checks running in parallel. AgentCore Gateway routes tool requests through Cedar policies before tools run, while deterministic rules decide whether a case moves forward or needs human review. The session follows a clean case, an ambiguous case, and a new risk event after onboarding. Attendees leave with a pattern for regulated agentic systems.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Community-led, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1780441467513001GarO", "sources": ["business_agents"], "ko_desc": "은행 계좌 개설을 90초 내에 — AI 에이전트가 KYC를 빠르게 처리하면서 최종 결정은 사람이 통제하는 AgentCore 기반 실시간 온보딩 아키텍처.", "company": "AWS", "thu_am": false, "start_time": "13:00", "length": 60}, {"code": "AWS013-R1", "title": "Partner Advantage Zone in Expo", "abstract": "AWS Partner Network, Marketplace, Specialized Solutions, New to AWS, and Partners LIVE — all here.", "type": "Expo", "level": "No Level", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1787852034416001jKVN", "sources": ["business_agents"], "ko_desc": "AWS Partner Network 엑스포 존 — AWS 파트너 네트워크, 마켓플레이스, 전문화 솔루션 소개.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "AWS113-R", "title": "Partner Advantage Zone in Expo", "abstract": "AWS Partner Network, Marketplace, Specialized Solutions, New to AWS, and Partners LIVE — all here.", "type": "Expo", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1787852032358001jug5", "sources": ["business_agents"], "ko_desc": "AWS Partner Network 엑스포 존 (반복).", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 180}, {"code": "AWS013-R2", "title": "Partner Advantage Zone in Expo", "abstract": "AWS Partner Network, Marketplace, Specialized Solutions, New to AWS, and Partners LIVE — all here.", "type": "Expo", "level": "No Level", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1787852034532001jG0R", "sources": ["business_agents"], "ko_desc": "AWS Partner Network 엑스포 존 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "IND3308-S", "title": "Rise of Autonomous Clinical Data Management: AI Agents Accelerating Drug Development (sponsored by Cognizant)", "abstract": "Explore how autonomous AI agents are transforming clinical data management from a collection of manual processes into an intelligent, continuously learning system that improves quality, accelerates study execution, and shortens the path from protocol to patient impact.\nClinical trials generate unprecedented volumes of complex data, yet many Clinical Data Management (CDM) processes remain highly manual, resource-intensive, and constrained by siloed workflows. Critical activities such as protocol interpretation, clinical trial data systems build and configuration, edit check generation, data review, data quality management, reconciliation, and database lock often reside on the critical path to study completion. This presentation is brought to you by Cognizant, an AWS Partner.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441489581001Glv9", "sources": ["business_agents"], "ko_desc": "자율 AI 에이전트가 임상 데이터 관리를 수동 프로세스 모음에서 지속적으로 학습하는 지능형 시스템으로 전환 — 신약 개발 가속화 (Cognizant 스폰서).", "company": "Cognizant", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AIM277-S", "title": "Running Vercel in Your Own AWS Account (sponsored by Vercel)", "abstract": "This session explores how Vercel Enterprise customers can run workloads in their own AWS account while continuing to use the Vercel developer experience. You’ll learn about the separation between the Vercel control plane and customer runtime, and why this model can help organizations meet data privacy, security, and compliance requirements. You’ll see how the setup works through a live walkthrough and demo, and how this architecture can support broader access to tools like v0, Amazon Q, and other coding agents. This presentation is brought to you by Vercel, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441485733001GnnH", "sources": ["business_agents"], "ko_desc": "Vercel 엔터프라이즈 고객이 자체 AWS 계정에서 워크로드를 실행하면서 Vercel 개발자 경험을 유지하는 방법 (Vercel 스폰서).", "company": "Vercel", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "PEX217", "title": "Sell to AI agents through AWS Marketplace", "abstract": "Today, buyers are using autonomous AI agents for discovery and digital purchases on their behalf. AWS Marketplace enables buyers' agents to discover partner solutions, transact securely, and meet their enterprise governance controls. As a seller in AWS Marketplace, learn how to sell products that support agentic discovery and procurement to position your offerings for this new frontier.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Venetian", "sessionID": "1780441472624001GW9v", "sources": ["business_agents"], "ko_desc": "AI 에이전트가 구매자를 대신해 솔루션을 발견·구매하는 시대 — AWS Marketplace가 에이전트 기반 구매를 안전하게 지원하는 방법.", "company": "AWS", "thu_am": null, "start_time": "09:00", "length": 60}, {"code": "AIM124-S", "title": "ServiceNow: The Super Intelligence Control Tower for Business Reinvention (sponsored by ServiceNow)", "abstract": "AI without workflows is just expensive advice. The next generation of AI leaders are moving beyond disconnected copilots and isolated use cases to reinvent how work gets done. Join ServiceNow to learn how the Super Intelligence Control Tower for Business Reinvention helps organizations govern AI, connect enterprise data, and orchestrate work across every agent, model, and workflow. Discover how AI that thinks and workflows that act enable enterprises to deploy AI quickly while maintaining trust, security, and control. This presentation is brought to you by ServiceNow, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441486214001GkYl", "sources": ["business_agents"], "ko_desc": "AI 없는 워크플로우는 비싼 조언에 불과 — ServiceNow Super Intelligence Control Tower로 비즈니스 전반의 재발명을 이끄는 방법 (ServiceNow 스폰서).", "company": "ServiceNow", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "BIZ203-S", "title": "Stop building agents that stop short of enterprise execution (sponsored by IBM)", "abstract": "AI value doesn’t come from creating more agents. It comes from putting agents to work—securely, reliably, and across the systems where business gets done. In this session, see how IBM Bob helps developers build and modernize applications with agentic AI, while watsonx Orchestrate coordinates agents, tools, and workflows across the enterprise. Discover how IBM helps teams move from code and intent to governed action—with the visibility and control needed to scale.​ This presentation is brought to you by IBM, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442266498001ceks", "sources": ["business_agents"], "ko_desc": "에이전트를 더 많이 만드는 것이 아니라 실제 비즈니스 시스템에서 안전·안정적으로 작동하게 하는 것이 AI 가치 — IBM이 소개하는 엔터프라이즈 에이전트 구현 방법 (IBM 스폰서).", "company": "IBM", "thu_am": null, "start_time": "11:00", "length": 20}, {"code": "SUP102", "title": "When FDE pays off: A VC lens on enterprise AI deployments", "abstract": "The first 90 days after an enterprise contract can determine whether an AI deployment earns renewal or stalls. Forward Deployed Engineering places engineers inside customer teams to own production code and business outcomes. This session explains when startups need FDE and how it differs from solutions engineering and customer success. An interactive scenario follows one startup’s deployment into its second year. The room decides how to scope the work, handle a security review, respond to a one-off feature request, and hire the first FDE. We examine the consequences, including which customer-specific work becomes reusable product and when embedded engineering pays.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1791492157747001U5N1", "sources": ["business_agents"], "ko_desc": "엔터프라이즈 AI 계약 후 첫 90일이 갱신 여부를 결정 — Forward Deployed Engineering(FDE)이 프로덕션 코드를 직접 소유하고 비즈니스 성과를 책임지는 VC 관점.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "SUP105", "title": "Wonderful brings enterprise voice AI to 30+ countries", "abstract": "Wonderful builds enterprise voice agents for regulated markets where English-first platforms struggle with local speech patterns and compliance requirements. Its platform handles conversations in more than 30 countries, supported by locally embedded teams. CEO Bar Winkler explains the Forward Deployed Engineer model, with senior engineers working inside customer environments and owning delivery through deployment. He shares how Wonderful deployed for a major telecom provider in two weeks, compared with the months typically required. The session examines how local expertise shapes agent performance, how to staff engineering teams across regions, and what technical accountability requires when deploying voice AI in customer environments.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1791492159080001U9Id", "sources": ["business_agents"], "ko_desc": "Wonderful이 30개국 이상에서 영어 중심 플랫폼이 취약한 현지 음성 패턴과 컴플라이언스를 처리하는 엔터프라이즈 음성 AI 구현 방법.", "company": "Wonderful", "thu_am": null, "start_time": null, "length": 20}, {"code": "AIM140-S", "title": "Beyond AI Productivity, What It Takes to Deliver Real Business Value (sponsored by JetBrains)", "abstract": "AI is making it easier than ever to write code. But more code doesn't necessarily mean better software or better business results.\nAs companies invest in AI tools and agents, the bigger question is whether they're getting real value from them. How do they measure what's working, maintain quality, and keep costs under control? This presentation is brought to you by JetBrains, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442271577001c6Tl", "sources": ["business_agents"], "ko_desc": "코드 작성이 쉬워졌다고 더 나은 소프트웨어·비즈니스 결과를 의미하지는 않는다 — AI 생산성을 넘어 실제 비즈니스 가치를 창출하는 조건 (JetBrains 스폰서).", "company": "JetBrains", "thu_am": null, "start_time": "17:00", "length": 20}, {"code": "AWS115-R2", "title": "Global Impact Zone in Expo", "abstract": "Explore how builders drive social impact through technology\n\nBody:  Engage regional experts, explore nonprofit initiatives, and learn how AWS tackles global challenges.", "type": "Expo", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1787852033828001j4da", "sources": ["business_agents"], "ko_desc": "AWS Global Impact Zone 엑스포 — 기술로 사회적 임팩트를 만드는 빌더들의 공간.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "AWS115-R", "title": "Global Impact Zone in Expo", "abstract": "Engage regional experts, explore nonprofit initiatives, and learn how AWS tackles global challenges.", "type": "Expo", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1787852032549001jMSe", "sources": ["business_agents"], "ko_desc": "AWS Global Impact Zone 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 180}, {"code": "AWS115-R1", "title": "Global Impact Zone in Expo", "abstract": "Explore how builders drive social impact through technology\n\nBody:  Engage regional experts, explore nonprofit initiatives, and learn how AWS tackles global challenges.", "type": "Expo", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1787852033701001jSzn", "sources": ["business_agents"], "ko_desc": "AWS Global Impact Zone 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "CMP204-S", "title": "Agentic AI on AWS with Intel® Xeon® 6 (sponsored by Intel)", "abstract": "Intel and Databricks are collaborating to optimize price-performance for workloads running on AWS. This session covers optimizations for ISVs running Photon/Spark on Databricks leveraging custom Amazon EC2 instances powered by Intel Xeon processors, delivering advanced AI capabilities and high core density. This presentation is brought to you by Intel, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Compute", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1780441487581001G8Xq", "sources": ["business_agents"], "ko_desc": "Intel과 Databricks가 AWS 맞춤형 EC2 인스턴스에서 Photon/Spark 워크로드 가격 대비 성능 최적화 — Intel Xeon 6 기반 에이전틱 AI (Intel 스폰서).", "company": "Intel", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ110-S", "title": "Uncover the Opportunity. Build the AI Agent. Scale It Live. (sponsored by NiCE)", "abstract": "Your CX data already knows where automation will pay off. See Agentic Analytics pinpoint the opportunity, then watch that recommendation become a working AI agent — built, tested, and scaled live. ​ This presentation is brought to you by NiCE, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Compute", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442271289001cxJq", "sources": ["business_agents"], "ko_desc": "CX 데이터에서 자동화 기회를 찾아 즉석에서 AI 에이전트로 구축·테스트·확장하는 과정을 라이브로 시연 (NiCE 스폰서).", "company": "NiCE", "thu_am": true, "start_time": "11:00", "length": 20}, {"code": "SNR308", "title": "A leader's guide to how Amazon built its data foundation for agents", "abstract": "Organizations racing to put AI agents on top of their data keep hitting the same walls: security, privacy, scale, and data they can't trust. In this session, Anas Fattahi (VP, Amazon Business Data Technologies) and G2 Krishnamoorthy (VP, AWS Databases) share how years of foundational investment positioned Amazon to move quickly when the agentic AI moment arrived, and where the hard problems still live. You'll hear which bets paid off, what's working now, what they're still building, and how to inspect your own setup against what they've learned. ", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Databases", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780442221509001cfDw", "sources": ["business_agents"], "ko_desc": "Amazon이 에이전트를 위한 데이터 기반 구축 시 마주한 보안·프라이버시·신뢰 문제 해결 방법 — 조직이 반복적으로 부딪히는 벽을 피하는 교훈.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "AIM264-S", "title": "Benchmarking Bedrock knowledge bases for agents in production (sponsored by Braintrust)", "abstract": "In this talk, we’ll walk through an independent eval of Amazon Bedrock Knowledge Bases, which manages the ingestion, parsing, and retrieval steps in a RAG application. In the first half, we’ll cover our methodology, including how we developed a dataset that queries documents such as tickets, wiki pages, and product docs, and what we decided to score: latency, cost, relevance, and citation support. We’ll also cover how we analyzed the results with research rigor, including p50 and p95 latency and confidence intervals around our metrics. In the second half, we’ll expand this into a conceptual understanding of evals and observability: why they’re important, how other companies are implementing them in production, and the terminology you need to know. This presentation is brought to you by Braintrust, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Databases", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442266147001cwyu", "sources": ["business_agents"], "ko_desc": "Amazon Bedrock Knowledge Bases의 독립적 평가 — RAG 애플리케이션에서 수집·파싱·검색 단계를 측정하는 방법론과 결과 (Braintrust 스폰서).", "company": "Braintrust", "thu_am": null, "start_time": "12:00", "length": 20}, {"code": "INV535", "title": "Data Environments for Agents", "abstract": "AI agents increasingly query databases, modify files, and operate applications. Their effectiveness depends on the environments in which they act: what information they can discover, which alternatives they can explore, and what happens when they make mistakes. This session examines how data environments can help agents accomplish more while bounding the consequences of failure. Drawing on research from Columbia’s Data, Agents, and Processes Lab, we explore branching and recovery across databases and live execution state, data flow controls that enforce policies and guide agent behavior, and evaluations that reveal bottlenecks in finding and using information. Participants will leave with a framework for reasoning about the responsibilities of models, execution systems, and human interfaces when building agentic applications.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence, Business Agents, Databases", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441495346001GjR2", "sources": ["business_agents"], "ko_desc": "AI 에이전트가 데이터베이스를 쿼리하고 파일을 수정하고 앱을 조작하는 환경 — 에이전트 효과는 어떤 정보를 발견할 수 있고 어떤 대안을 탐색할 수 있는지에 달려있다.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "SNR317", "title": "A leader's guide to scaling AI adoption without losing control", "abstract": "I gave the organization AI tools — why did adoption stall? Most enterprises equip teams with AI and expect transformation to follow. It doesn't. Amazon scaled agentic AI to thousands of production deployments not by mandate, but by investing in what surrounds the model: governance that guards what truly matters — customer trust, privacy, security, and cost — while loosening its grip everywhere else, a culture where experimentation and oversight coexist, and upskilling that turns casual prompters into confident builders. This session names the structural bets that move adoption, the debts you're quietly acquiring, and why losing control isn't the failure — over-constraining is.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1783654976605001dN80", "sources": ["business_agents"], "ko_desc": "AI 도구를 제공했는데 왜 채택이 정체됐나? — Amazon이 수천 개의 프로덕션 에이전트로 확장한 방법은 도구 배포가 아닌 시스템적 접근이었다.", "company": "Amazon", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "AIM104-S", "title": "Autonomous AI Ops with AWS DevOps Agent and New Relic Autopilot (sponsored by New Relic)", "abstract": "Incident investigation still consumes 1-2 hours of engineering time per event. See how New Relic's Intelligent Observability Platform integrates with AWS DevOps Agent to: Autonomously triage incidents, pinpoint root cause, and deliver actionable remediation with no custom tooling required. Investigate incidents agentically correlating telemetry, code, and deployments across AWS, multi cloud, and on-prem environments. Demonstrate how this innovation proactively prevents future incidents by analyzing patterns and recommending improvements. Learn how customers are cutting MTTR by 75% and shifting from firefighting to prevention, and walk away ready to get started. This presentation is brought to you by New Relic, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441487297001GOLY", "sources": ["business_agents"], "ko_desc": "장애 조사에 엔지니어 1~2시간이 소요되는 문제 해결 — New Relic과 AWS DevOps Agent로 자율적 사고 분류·근본 원인 분석·해결 (New Relic 스폰서).", "company": "New Relic", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "BIZ206-S", "title": "Beyond Evals: Setting up your agents and your enterprise for success (sponsored by LangChain)", "abstract": "We are witnessing models and agents continually becoming more capable,  all while the process of meaningfully evaluating them continues to be a challenge. In this session, we will dissect eval best practices observed both in the field and internally at LangChain. This session will go beyond just your technical evaluation toolkit and provide practical organizational and process takeaways and a better understanding of what future capabilities are unlocked downstream of good evaluation. This session will be especially relevant to teams deploying agents in cross-functional domains. This presentation is brought to you by LangChain, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442272248001cf4w", "sources": ["business_agents"], "ko_desc": "에이전트 평가(Evals) 너머의 엔터프라이즈 성공 조건 — LangChain이 다양한 사례에서 관찰한 에이전트 평가 베스트 프랙티스와 운영 방법 (LangChain 스폰서).", "company": "LangChain", "thu_am": null, "start_time": "10:00", "length": 20}, {"code": "AWS114-R", "title": "Builder Zone in the Expo ", "abstract": "Explore emerging tech, learn new skills, and connect with fellow builders. Your journey starts here.", "type": "Expo", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1787852032448001j0t4", "sources": ["business_agents"], "ko_desc": "AWS Builder Zone 엑스포 — 신기술 탐색, 기술 습득, 빌더 네트워킹.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 180}, {"code": "AWS014-R1", "title": "Builder Zone in the Expo ", "abstract": "Explore emerging tech, learn new skills, and connect with fellow builders. Your journey starts here.", "type": "Expo", "level": "No Level", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1787852034046001jO69", "sources": ["business_agents"], "ko_desc": "AWS Builder Zone 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "AWS014-R2", "title": "Builder Zone in the Expo ", "abstract": "Explore emerging tech, learn new skills, and connect with fellow builders. Your journey starts here.", "type": "Expo", "level": "No Level", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1787852034150001jjQs", "sources": ["business_agents"], "ko_desc": "AWS Builder Zone 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "DVT221-S", "title": "Controlling the AI Software Factory (sponsored by LaunchDarkly)", "abstract": "AI isn't just making software faster; it's changing how software is produced. Engineering teams now run agents that write code, review PRs, validate releases, and deploy around the clock. The promise is real, but so is a new problem: how do you stay in control of systems that never stop evolving? Edith Harbaugh, CEO of LaunchDarkly, argues the defining challenge of the AI era isn't generating code, it's controlling autonomous systems in production, where agents drift and the old detect-fix-redeploy playbook breaks down. She'll share what LaunchDarkly learned building its own AI software factory, and how engineers stay in charge. This presentation is brought to you by LaunchDarkly, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441486273001GfAM", "sources": ["business_agents"], "ko_desc": "AI가 소프트웨어 생산 방식 자체를 바꾸고 있다 — 에이전트가 코드 작성·PR 검토·배포를 24시간 실행하는 AI 소프트웨어 팩토리 통제 방법 (LaunchDarkly 스폰서).", "company": "LaunchDarkly", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "AIM282-S", "title": "Elasticsearch - the Search database for Context Engineering and AI (sponsored by Elastic)", "abstract": "Your agentic applications have an accuracy and cost problem, and it's not your model choice. Sound familiar? If you're a developer trying to get LLMs to work effectively with your business context, this session is for you. Come learn how we rearchitected Elasticsearch as the database of choice for the different data types your enterprise knowledge is buried in — docs, logs, metrics, tickets, sales call transcripts, and more. From foundational innovations like Columnar and VectorDB mode with no ETL, to best-in-class retrieval that combines vector search, Jina embedding models, and native inference, Elastic is the context database for your production needs. Join this session to learn the best practices, from optimizing data preparation to retrieval patterns, to make your agents a production reality. This presentation is brought to you by Elastic, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441487864001GgSt", "sources": ["business_agents"], "ko_desc": "에이전틱 앱의 정확도·비용 문제는 모델 선택이 아닌 컨텍스트 문제 — Elasticsearch를 Context Engineering과 AI를 위한 검색 데이터베이스로 활용하는 방법 (Elastic 스폰서).", "company": "Elastic", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "DVT222-S", "title": "Inside Real AI Software Factories: Lessons From the Teams Building Them (sponsored by LaunchDarkly)", "abstract": "Everyone's talking about AI software factories. Far fewer have actually built one. In this panel, engineering leaders, partners, and teams putting agents into production go past the hype to the real work: where agents accelerate delivery, where they break, and what it takes to keep humans in control as autonomy scales. Expect specifics, not theory—what worked, what didn't, and what they'd do differently. Whether you're experimenting with coding agents or scaling toward autonomous delivery, you'll leave with practical patterns for building a factory that's genuinely fast and safe. Join us for an honest conversation about engineering at agent speed. This presentation is brought to you by LaunchDarkly, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441488208001GuO1", "sources": ["business_agents"], "ko_desc": "실제로 AI 소프트웨어 팩토리를 구축한 엔지니어링 리더들의 솔직한 이야기 — 에이전트를 프로덕션에 투입한 팀들이 공유하는 현실적 교훈 (LaunchDarkly 스폰서).", "company": "LaunchDarkly", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM396-S", "title": "Kiro Writes the PR. Nobody Validates the App. (sponsored by TestMu)", "abstract": "Kiro can now build a whole feature on its own: write the spec, implement it, and open the PR without anyone sitting in the loop. That’s real progress. But nothing in that pipeline actually runs the app and checks it against what the spec promised. The checks that gate the PR look at the code, not the behavior. So the PR arrives looking done, and “done” is still just a guess someone has to trust. The good news is Kiro already produces the one thing a testing agent needs to close that gap: a clear, structured spec of what the feature is supposed to do. We’ll show Kane-CLI plugged in as a Kiro Power, reading that spec, actually running the app the way a user would, and reporting back proof, not just a checkmark, before the PR merges. This presentation is brought to you by TestMu, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442269406001cD8J", "sources": ["business_agents"], "ko_desc": "Kiro가 스펙 작성부터 구현·PR까지 완전 자율로 수행한다 — 그런데 앱을 실제로 실행하고 검증하는 과정이 없다면? 에이전트 생성 코드 테스트 자동화 방법 (TestMu 스폰서).", "company": "TestMu", "thu_am": false, "start_time": null, "length": 20}, {"code": "AIM134-S", "title": "When Software Builds and Improves Itself (sponsored by Factory)", "abstract": "Software is becoming more than something companies build. It is becoming the system through which they improve. The next generation of software factories will turn business signals into production software, measure the outcomes, and use those outcomes to improve each cycle of development. Engineers set the goals, architecture, policies, and approval gates, while the system handles execution and continuously improves itself. Factory cofounder Eno Reyes will share what this future looks like, what has to be true to build it, and why self-improving software will fundamentally change how every company operates. This presentation is brought to you by Factory, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442265981001crq3", "sources": ["business_agents"], "ko_desc": "비즈니스 신호를 프로덕션 소프트웨어로 전환하고 스스로 개선하는 소프트웨어 팩토리 — 자체 개선 능력이 있는 차세대 소프트웨어 시스템 (Factory 스폰서).", "company": "Factory", "thu_am": null, "start_time": "11:00", "length": 20}, {"code": "AIM263-S", "title": "Why Multi-Agent Systems Fail in Production (And How to Fix It) (sponsored by MongoDB)", "abstract": "Most AI agents don't fall apart in production because the model isn't smart enough. They fail because state is fragmented: one agent can't see what another already learned, and nobody can reconstruct what was retrieved, decided, or handed off. In a multi-tenant setting, that's a governance problem, not just a debugging one. This session shows an architecture that fixes it by giving every layer a clear job: Amazon Bedrock AgentCore manages session context and end-to-end tracing, MongoDB Atlas handles durable memory, tenant-aware vector search, and audit history, and the MongoDB MCP Server connects the two so access stays governed. You'll watch agents share state, retrieve tenant-scoped data, and leave a replayable decision trail. Leave with a reference architecture for multi-agent state sharing and a model for what audit-ready really looks like. A MongoDB & AWS technical session. This presentation is brought to you by MongoDB, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Developer Tools", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1780441489356001GA6l", "sources": ["business_agents"], "ko_desc": "멀티 에이전트 시스템이 프로덕션에서 실패하는 이유는 모델 지능이 아닌 상태 단편화 — 에이전트 간 컨텍스트 공유와 검색 재현을 위한 MongoDB 기반 상태 관리 (MongoDB 스폰서).", "company": "MongoDB", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "BIZ327-S", "title": "Engineering the Context that Makes Enterprise AI Work (sponsored by Impetus Technologies Inc)", "abstract": "Every enterprise has access to the same AI models. The real differentiator is context. Discover Impetus’ Context Engineering Delivery Lifecycle, a proven methodology  than ensures no AI agent reaches production without a signed-off context bundle, evaluation record, and explainability trace. Learn how to engineer enterprise data, domain knowledge, industry ontologies, business rules, and governance into a robust context layer agents need to deliver accurate, trusted outcomes. Get practical insights on building AI systems on AWS that are grounded, explainable, reliable, and ready to scale. This presentation is brought to you by Impetus Technologies Inc, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442272193001cQRh", "sources": ["business_agents"], "ko_desc": "동일한 AI 모델을 모두가 사용한다 — 진짜 차별화는 컨텍스트 품질 — Impetus의 Context Engineering Delivery Lifecycle로 에이전트가 컨텍스트 없이 프로덕션에 도달하지 않도록 보장 (스폰서).", "company": "Impetus Technologies Inc", "thu_am": null, "start_time": "11:00", "length": 20}, {"code": "AIM230-S", "title": "Own Your Harness: Control Cost & Risk in Enterprise-Wide AI Adoption (sponsored by Presidio)", "abstract": "The fastest way to lose control of AI is to let agents multiply without a harness. This talk walks through Presidio's journey from scattered pilots to enterprise-wide adoption, built on a custom orchestration layer that treats cost, identity, and policy as first-class concerns. Attendees will get an inside look at the architectural decisions, guardrails, and economic models that let us scale AI use predictably across the business. If you're weighing governance (cost and risk) against velocity, this is the playbook you want from day one. This presentation is brought to you by Presidio, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441482456001Gqjs", "sources": ["business_agents"], "ko_desc": "에이전트를 통제 없이 늘리면 가장 빠른 AI 통제 상실 방법 — Presidio가 분산 파일럿에서 엔터프라이즈 전체 도입으로 나아가며 구축한 커스텀 오케스트레이션 레이어 (Presidio 스폰서).", "company": "Presidio", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "AIM291-S", "title": "Architecting Intelligent Omni-Channel Communication Workflows with Twilio + AWS (sponsored by Twilio)", "abstract": "Orchestrating AI conversations across channels requires more than just connecting APIs. Learn how to build agents that understand context, respond instantly, and adapt to channel constraints. Explore Twilio Agent Connect and Amazon Bedrock integration patterns, plus the operational playbook for deploying engagement AI at scale. This presentation is brought to you by Twilio, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442271883001caZT", "sources": ["business_agents"], "ko_desc": "채널을 넘나드는 AI 대화 오케스트레이션 — Twilio Agent Connect를 사용해 컨텍스트를 이해하고 즉각 반응하며 채널 제약에 적응하는 에이전트 구축 (Twilio 스폰서).", "company": "Twilio", "thu_am": false, "start_time": "14:00", "length": 20}, {"code": "AIM258-S", "title": "Ask the News: Making Decades of Publisher Content Instantly Searchable (sponsored by MongoDB)", "abstract": "TPublishers sit on enormous archives: decades of articles, millions of photos, entire histories of coverage. Most of it is invisible the moment someone needs more than a keyword match. ArcXP built Ask the News to close that gap: a standalone, API-first product giving publishers natural-language access to their own content, powered by MongoDB Atlas Vector Search. The system combines lexical and vector search so results reflect what was meant, not what was said. One of the hardest parts was visual: a pipeline that generated descriptions and embeddings for roughly five million historical images, making decades of archives searchable by meaning for the first time. You'll leave understanding a working pattern for combining lexical and vector search, and a model for exposing natural-language search as an API-first product, not a bolt-on feature. Featuring ArcXP, presented by MongoDB. This presentation is brought to you by MongoDB, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780441487412001Gge7", "sources": ["business_agents"], "ko_desc": "수십 년치 기사·사진·보도 아카이브를 키워드 검색 너머로 — ArcXP가 Ask the News를 구축해 퍼블리셔 콘텐츠를 즉각 검색 가능하게 만든 방법 (MongoDB 스폰서).", "company": "ArcXP (MongoDB)", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "IND104-S", "title": "Building the Construction Cloud: How Procore AI &Amazon Bedrock Power the Built World (sponsored by Procore)", "abstract": "Construction generates massive volumes of structured and unstructured data, such as drawings, RFIs, and safety reports, that most AI infrastructure isn't built to handle. In this session, we'll break down how Amazon Bedrock's model access, guardrails, and enterprise controls power Procore AI, and why that combination is what makes construction-specific AI viable at enterprise scale. You'll leave with a clear picture of the architecture, and why we think this is the first real blueprint for AI in the built environment. This presentation is brought to you by Procore, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442267542001cH2e", "sources": ["business_agents"], "ko_desc": "건설 산업의 AI 인프라 문제 — 도면·RFI·안전 보고서 같은 비정형 데이터를 Amazon Bedrock으로 처리하는 Procore의 Construction Cloud 구축 방법 (Procore 스폰서).", "company": "Procore", "thu_am": false, "start_time": "12:00", "length": 20}, {"code": "IND3349", "title": "From Generic to Industry Expert: The Next Era of AI", "abstract": "AI assistants handle calendars and inboxes but fall short on domain-specific workflows. What if AI could understand your industry's systems, standards, and compliance requirements? In this session, we explore how pre-configured agents, skills, knowledge bases, and ISV connectors can address industry-specific use cases while giving customers the flexibility to extend and customize their enterprise workflows. Learn how AI assistants can go beyond a general-purpose productivity tool into a domain expert for your industry.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "Telecommunications", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1780441471747001Ga93", "sources": ["business_agents"], "ko_desc": "AI 어시스턴트가 일정·이메일은 처리하지만 도메인 특화 워크플로우에서는 부족 — 특정 산업의 시스템·표준·컴플라이언스를 이해하는 산업 전문가 AI 구현 방법.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "INV536", "title": "Recursive Self-Improvement on the Job ", "abstract": "This talk will discuss RSI (recursive self-improvement) agents that proactively and continuously learn on the job. Agents onboard a new knowledge job just like human employees. Through RSI, we show that agents can outperform human testers on the same job across accuracy, efficiency, and cost. The talk will end with a discussion on the future of human-AI collaboration.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441495410001Gx5M", "sources": ["business_agents"], "ko_desc": "입사 때처럼 새로운 지식 업무에 온보딩하면서 지속적으로 자체 개선하는 RSI(재귀적 자기 개선) 에이전트 — 에이전트가 사람 성과를 능가하는 방법 시연.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "IND109-S", "title": "Reimagining Patient Engagement with AI and Cloud (sponsored by Incedo Inc.)", "abstract": "Life sciences organizations are exploring how AI and cloud can transform engagement across the patient journey. This executive discussion will examine how connected data, generative AI and intelligent automation can enable more personalized, timely and responsive patient experiences.\n\nThe conversation will explore opportunities to reduce friction, improve engagement, drive adherence, and deliver more connected omnichannel experiences aligned with business priorities. It will also address the challenges of data fragmentation, governance, trust and adoption. Attendees will gain practical executive perspectives on moving beyond AI experimentation to scalable, responsible solutions that deliver meaningful value for patients and life sciences organizations. This presentation is brought to you by Incedo Inc., an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442272548001c81L", "sources": ["business_agents"], "ko_desc": "생명과학 기업이 환자 여정 전반에서 AI와 클라우드로 참여 방식을 혁신 — 연결된 데이터·생성형 AI·지능형 자동화로 개인화된 환자 경험 구현 (Incedo 스폰서).", "company": "Incedo Inc.", "thu_am": false, "start_time": "14:00", "length": 20}, {"code": "BIZ204-S", "title": "Self-Healing Enterprise-Wipro & AWS Moving from System of Record to System of Action (sponsored by Wipro)", "abstract": "For decades, enterprises have invested in technologies that digitize, automate and optimize work. Yet when disruptions occur, decisions still depend on emails, escalations, meetings and manual coordination across teams. The next phase of enterprise transformation is about creating enterprises that can sense change, assess impact, coordinate responses and drive outcomes at speed. Wipro and AWS demonstrate how intelligent agents, enterprise systems and human expertise come together to create a Self-Healing Enterprise, one that can proactively identify issues, orchestrate actions across functions and continuously adapt while keeping humans accountable for critical business decisions. Through a realistic business disruption scenario, see how organizations can evolve beyond visibility and automation towards systems of action that improve resilience, responsiveness and operational efficiency. This presentation is brought to you by Wipro, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442267098001cKr2", "sources": ["business_agents"], "ko_desc": "수십 년간 기록·자동화·최적화에 투자한 엔터프라이즈에서도 혼란이 발생하면 여전히 이메일·에스컬레이션·회의에 의존 — Wipro와 AWS의 System of Action으로 전환 (Wipro 스폰서).", "company": "Wipro", "thu_am": true, "start_time": "11:00", "length": 20}, {"code": "AMZ301", "title": "The Art of the Impossible: How Amazon Builds on AWS", "abstract": "Discover how two Amazon teams tackled seemingly impossible problems with agentic AI running on AWS. Prime Video enabled content discovery at a scale where personalized curation was never feasible, building an AI discovery assistant powered by agentic search on Amazon Bedrock and AgentCore, vector-powered retrieval, and frontier and custom LLMs on SageMaker. Launched to millions of customers, it replaced endless scrolling with conversation starters like \"hidden gems from the '80s\" and natural voice exploration. Amazon Pharmacy now autonomously resolves most of its hundreds of thousands of monthly customer contacts while staying HIPAA compliant. Specialized agents on Amazon Bedrock Agents and Amazon Connect handle billing, fulfillment, and pharmacist workflows, hand off to humans, increasing satisfaction. Learn to apply their approaches to your own seemingly impossible problems.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1780441477810001GE8k", "sources": ["business_agents"], "ko_desc": "Prime Video가 대규모에서 불가능했던 개인화 큐레이션을 AI 디스커버리 엔진으로 구현 — Amazon 팀들이 AWS에서 불가능한 문제를 에이전틱 AI로 해결한 두 가지 사례.", "company": "Amazon (Prime Video)", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "SNR315", "title": "A leader's guide to modernizing systems for AI, with AI", "abstract": "Every enterprise faces the same sequencing problem: \"Before we can deploy AI, we need to fix our legacy systems.\" This is technology's most expensive false binary. Organizations that made real progress rejected that sequence. They use AI to understand undocumented code, decompose monoliths, and rebuild the very systems blocking deployment. One airline uses AI to comprehend reservation logic only three people understand. Another enterprise uses agents to reverse-engineer decades of business rules into microservices. The recursive unlock: the technology you want to deploy removes what blocks it. This session covers the funding, sequencing, and organizational decisions that make it work.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1783654976747001dKAf", "sources": ["business_agents"], "ko_desc": "'AI 도입 전에 레거시 시스템부터 고쳐야 한다'는 거짓 이분법을 거부한 기업들 — AI로 레거시 시스템을 현대화하는 전략 리더 가이드.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM297-S", "title": "Build Agentic AI That Understands Your Business with SAP and AWS (sponsored by SAP)", "abstract": "Enterprise AI falls short when agents lack live  business context. See how SAP's Business AI Platform and AWS solve this: Joule Studio enables developers and business users to build and deploy custom AI agents grounded in SAP's process knowledge, while bidirectional, zero-copy integration between SAP Business Data Cloud and Amazon Athena gives AWS services secure access to trusted SAP data. Watch a live demo of building agents that reason with business context, collaborate across SAP and AWS, and act across enterprise processes with governance.​ This presentation is brought to you by SAP, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441487358001GNwh", "sources": ["business_agents"], "ko_desc": "에이전트가 실제 비즈니스 컨텍스트 없이는 부족하다 — SAP Business AI Platform과 AWS로 ERP 데이터에 기반한 맞춤형 AI 에이전트 구축 방법 (SAP 스폰서).", "company": "SAP", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "DVT214-S", "title": "Claude Keeps Building: How Coding Agents Change Software Development (sponsored by Anthropic)", "abstract": "Coding agents make sustained, autonomous progress on real software. The question is what happens to the rest of the software development lifecycle. Claude Code runs for hours unattended, works beyond the terminal, and takes on more of the work around the code. We'll show where it stands and how engineering changes when the whole lifecycle becomes automatable: what engineers do, how review and testing evolve, where quality comes from when code is cheap. Live demos on AWS and numbers from our engineering, where Claude writes most of our code. This presentation is brought to you by Anthropic, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441489526001GnQ1", "sources": ["business_agents"], "ko_desc": "코딩 에이전트가 수 시간 자율 작업하는 시대에 소프트웨어 개발 라이프사이클의 나머지는 어떻게 되는가 — Claude Code가 터미널 너머로 작업 범위를 확장하는 방법 (Anthropic 스폰서).", "company": "Anthropic", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "AIM459-S", "title": "From AI to Action: Powering Agentic Enterprises with AWS and Infosys (sponsored by Infosys)", "abstract": "As AI evolves from generating insights to driving action, leading organizations are adopting intelligent agents to transform how work gets done. Hear from enterprise leaders as they share their journeys to building agentic businesses with AWS and Infosys, accelerating decision making, improving productivity, and unlocking measurable business value at scale. This presentation is brought to you by Infosys, an AWS Partner.", "type": "Breakout session", "level": "400 – Expert", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Wynn/Encore", "sessionID": "1780441484751001GOSV", "sources": ["business_agents"], "ko_desc": "AI가 인사이트 생성에서 행동 실행으로 진화하는 시대의 엔터프라이즈 에이전트 구축 여정 — 기업 리더들이 공유하는 Infosys와 AWS 기반 에이전틱 전환 사례 (Infosys 스폰서).", "company": "Infosys", "thu_am": null, "start_time": "09:00", "length": 60}, {"code": "AIM133-S", "title": "From First Workload to the Autonomous Enterprise: Transform and Scale with SAP on AWS (sponsored by SAP)", "abstract": "Agentic AI is making ERP modernization more urgent than ever. To coordinate decisions across the organization enterprise, AI must be grounded in a modern cloud ERP foundation—one that connects data, processes, business rules, and controls. ERP is no longer just where work is recorded. It has become the operational foundation that enables enterprise agentic AI and ultimately the Autonomous Enterprise.​\n\nSAP and AWS are partnering to help clients accelerate their AI vision Autonomous Enterprise where people set direction, AI executes operational tasks, and organizations respond faster to change leveraging a single intelligent system with full business context. Join us to explore how SAP on AWS helps moves organizations of all sizes to move beyond isolated AI pilots to enterprise-wide outcomes delivered with reliability and confidence.​ This presentation is brought to you by SAP, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1780441489120001GbbU", "sources": ["business_agents"], "ko_desc": "에이전틱 AI가 ERP 현대화를 더 시급하게 만드는 이유 — 의사결정을 조율하는 AI를 위한 현대 클라우드 ERP 기반 구축 방법 (SAP 스폰서).", "company": "SAP", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "MAM213-S", "title": "No Data Left Behind: The AI-Ready Path Through AWS (sponsored by Qlik)", "abstract": "Your enterprise data is scattered across SAP, mainframes, databases, and cloud platforms that were never designed to talk to each other — and every AI initiative depends on enabling that communication. This session shows how Qlik and AWS modernize that data without downtime, rewrites, or re-platforming risk: zero-footprint CDC, Qlik Open Lakehouse with Apache Iceberg and Amazon Athena, Spark Structured Streaming on Amazon EMR, and governed data products built for AI. You'll also get a bonus preview of Qlik's Studio AI Assistant on Amazon Bedrock and what's next for agentic workflows. This presentation is brought to you by Qlik, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442268078001cXMj", "sources": ["business_agents"], "ko_desc": "SAP·메인프레임·데이터베이스·클라우드 플랫폼에 분산된 엔터프라이즈 데이터를 AI 이니셔티브를 위해 통합하는 방법 (Qlik 스폰서).", "company": "Qlik", "thu_am": null, "start_time": null, "length": 20}, {"code": "MAM103-S", "title": "Re-Engineer Enterprise Processes for Agentic AI on Amazon Bedrock AgentCore (sponsored by Camunda)", "abstract": "Enterprise AI is moving from experimentation to production, but legacy workflows designed without AI in mind keep agents disconnected from the processes, systems, and controls that determine successful business outcomes. Understand why reengineering now matters: organizations that preserve legacy workflows risk slowing AI adoption while others redesign operations for an AI first world. Discover how Camunda ProcessOS works with Amazon Bedrock and Amazon Bedrock AgentCore to discover, re-engineer, and improve end-to-end processes. See how Camunda’s agentic orchestration combines deterministic controls with dynamic AI agents, human approval, observability, and auditability. Learn why you need to re-engineer now, and stop adding agents to yesterday’s workflows. This presentation is brought to you by Camunda, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442270459001c20V", "sources": ["business_agents"], "ko_desc": "AI를 위해 설계되지 않은 레거시 워크플로우가 에이전트를 프로세스·시스템·컨트롤에서 단절 — Amazon Bedrock AgentCore에서 엔터프라이즈 프로세스 재설계 방법 (Camunda 스폰서).", "company": "Camunda", "thu_am": true, "start_time": "11:00", "length": 20}, {"code": "AIM126-S", "title": "How Iberdrola Increased Marketing Capacity 4x with Agentic AI (sponsored by Accenture)", "abstract": "Iberdrola, a Spanish multinational electric utility company, is transforming marketing with CreatIA, an agentic AI platform co-developed with Accenture and AWS. Facing rising demand for content, faster decisions and accelerated campaign delivery, Iberdrola adopted a new operating model powered by specialized AI agents across the marketing lifecycle. CreatIA unifies market intelligence, insights generation, content creation, validation and campaign activation in a single enterprise platform. The solution has reduced time spent analyzing and processing information by 80%, accelerated strategic decision making by 40%, increased creative production capacity by up to four times, and reduced content production costs by 60%. This presentation is brought to you by Accenture, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Networking & Content Delivery", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780441482169001Gec5", "sources": ["business_agents"], "ko_desc": "Iberdrola(스페인 전력 회사)가 Accenture·AWS와 CreatIA 에이전틱 AI 플랫폼으로 마케팅 생산 역량을 4배로 높인 사례 (Accenture 스폰서).", "company": "Iberdrola (Accenture)", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "INV534", "title": "The Cogs of a Well-oiled Software Factory", "abstract": "The \"Software Factory\" is a new buzzword for a fully autonomous agent driven software development process. Many organizations are trying to set up such a factory, but this is easier said than done. In this talk, from my experience setting up such factories for ourselves and other businesses, I will explain some of the elements of a software factory (issue triage, spec generation, implementation, review, and testing), and some of the pain points that we have experienced at each step. I will also cover how to evaluate the effectiveness of each of these steps and how to build a self-improvement pipeline so the factory gets better and better with feedback from its human supervisors.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence, Business Agents, Open Source", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1780441495290001GyRq", "sources": ["business_agents"], "ko_desc": "완전 자율 에이전트 기반 소프트웨어 개발 프로세스 '소프트웨어 팩토리' 구축 — 말은 쉽지만 실제로 구현하기 어려운 이유와 해결 방법.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "SNR321", "title": "A leader's guide to security at the speed of AI, powered by Mythos", "abstract": "As AI capabilities advance, so do the capabilities of those who attack software. The pace of modern development has outgrown point-in-time security reviews, leaving vulnerabilities exploitable longer than any leader should accept. Periodic snapshots cannot keep up when code changes constantly, so security has to become continuous, evaluating posture as the code itself evolves. Amazon used frontier-model capabilities, through Mythos, to make security continuous at its own scale, finding issues and guiding builders to fix them as they work. This session explores that shift. Senior leaders will learn how to secure their organizations at AI speed.", "type": "Mainstage", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1789411632892001iZOX", "sources": ["business_agents"], "ko_desc": "AI 역량이 발전하면 공격자 역량도 함께 발전 — 현대 개발 속도에 맞지 않는 정기적 보안 검토를 AI 기반 실시간 보안으로 대체하는 방법 (Mythos 스폰서).", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "AIM3300-S", "title": "Defending the Three Lanes: Preventing Toxic Agentic Combinations with Cyera and AWS (sponsored by Cyera)", "abstract": "Agentic AI is entering production faster than enterprise authorization models can keep up, and most access decisions are made without regard to the sensitivity of the data agents can reach, turning over-permissioned agents into high-value targets. This session introduces the three lanes: the data agents touch, the identity they act as, and the actions they take, as the framework for defending agentic AI on AWS. See how Cyera's Agent Guardian extends Amazon Bedrock AgentCore Identity with data-aware authorization to enforce least privilege, monitor agent-to-data activity, and prove it to auditors. This presentation is brought to you by Cyera, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1780442390221001Nwi2", "sources": ["business_agents"], "ko_desc": "에이전틱 AI가 기업 권한 모델보다 빠르게 프로덕션에 투입 — 데이터 민감도를 고려하지 않은 과잉 권한 에이전트 위험 방지 방법 (Cyera 스폰서).", "company": "Cyera", "thu_am": false, "start_time": null, "length": 20}, {"code": "SEC233-S", "title": "Ghost agents: Governing ephemeral AI & machine access in real-time (sponsored by SailPoint)", "abstract": "Ephemeral AI agents and cloud workloads spin up, access resources, and vanish in minutes, never landing in traditional identity registries. How do you govern what you can’t track? The answer lies in securing the non-human identities (NHIs) they leave behind. Join SailPoint for a live demo on governing ephemeral agent behavior. We’ll show you how to untangle NHI ownership, expose over-privileged access, and establish real-time governance over transient machine identities before they expose your cloud. Walk away with a blueprint to manage non-human access risk at cloud scale. This is clarity you can act on. This presentation is brought to you by SailPoint, an AWS Partner.", "type": "Lightning talk", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442273750001cKBj", "sources": ["business_agents"], "ko_desc": "수분 만에 스핀업·리소스 접근·소멸하는 임시 AI 에이전트 거버넌스 — 전통적 신원 레지스트리에 등록되지 않는 비인간 머신 신원 보안 방법 (SailPoint 스폰서).", "company": "SailPoint", "thu_am": false, "start_time": null, "length": 20}, {"code": "BIZ208-S", "title": "Keep sleeping at 3am: Elastic watches your Prometheus metrics so you don't have to (sponsored by Elastic)", "abstract": "When your kubernetes cluster fires at 3am, who's investigating? In this session we'll show Elastic Nightshift — our autonomous AI SRE — detecting a real Kubernetes incident and working it end to end: from alert to root cause to remediation, with its reasoning made transparent at every step. Nightshift draws on native Prometheus and PromQL metrics in Elastic. Kubernetes logs, out-of-the-box EKS dashboards and workflows, and ES|QL subqueries that correlate metrics with logs and traces in a single investigation. We'll also show how the 30x faster columnar metrics engine and full telemetry retention give Nightshift the complete context it needs to work like your best engineer This presentation is brought to you by Elastic, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441482581001GJV7", "sources": ["business_agents"], "ko_desc": "새벽 3시 Kubernetes 클러스터 경보 대응 — Elastic Nightshift 자율 SRE가 실제 Kubernetes 장애를 경보부터 해결까지 자율 처리하는 시연 (Elastic 스폰서).", "company": "Elastic", "thu_am": null, "start_time": null, "length": 60}, {"code": "AIM387-S", "title": "Rethinking Agentic Security: How Cyera Scaled AI Securely in Days (sponsored by Cyera)", "abstract": "As AI shifts from assistive systems to autonomous agents, data becomes the control surface. Agents need a goldilocks balance of data, identity, and process access: enough to be effective, too much and you end up on Twitter. Cyera solved this internally, reaching 88% weekly AI usage across engineering and non-engineering teams in 17 days. Adoption was not the hard part. The wiring was. How do you govern access and give builders a permit path so they ship instead of wait? Join us for what we learned, and what it means on AWS. This presentation is brought to you by Cyera, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442266263001cPPx", "sources": ["business_agents"], "ko_desc": "에이전틱 보안의 재정의 — AI가 자율 시스템으로 이동하면서 데이터가 컨트롤 표면이 됨, Cyera가 며칠 만에 AI를 안전하게 확장한 방법 (Cyera 스폰서).", "company": "Cyera", "thu_am": null, "start_time": "14:00", "length": 20}, {"code": "AIM113-S", "title": "AIOPs for cloud data infrastructure (sponsored by NetApp)", "abstract": "Cloud data infrastructure rarely stays optimal — workloads change, configurations drift, and data infrastructure expertise is scarce. AIOps applies AI-powered, agentic automation to cloud data storage operations: continuously assessing the environment, analyzing it against workload-specific best practices, recommending fixes, and applying them at the level of autonomy you choose. In this lightning talk, we’ll explore how NetApp Workload Factory does all this while providing customers with right-sized cost, on-target performance, stronger resilience and protection — without the need for deep data infrastructure expertise, and while always staying in control. This presentation is brought to you by NetApp, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Artificial Intelligence, Business Agents, Storage", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442267293001cyDH", "sources": ["business_agents"], "ko_desc": "클라우드 데이터 인프라는 최적 상태를 유지하기 어렵다 — AIOps가 에이전틱 자동화로 클라우드 데이터 스토리지 운영 전반에 적용되는 방법 (NetApp 스폰서).", "company": "NetApp", "thu_am": null, "start_time": "15:00", "length": 20}, {"code": "COM324-R1", "title": "Pit Crew AI: Building Multi-Agent Cloud Operations on AWS", "abstract": "AI can generate code at racing speed, but production workloads still require continuous attention to security, reliability, cost, and operational risks. In this Code Talk, we build a multi-agent architecture on AWS inspired by a Formula 1 pit crew. Using Amazon Bedrock AgentCore, Strands Agents, MCP, GitHub, Jira, and Infrastructure as Code, we evolve from a single agent to a team of specialized agents for security, cost optimization, reliability, and observability. Through a live demonstration, you’ll see how agents turn cloud findings into engineering tasks. Attendees will leave with reusable architectures, orchestration patterns, and examples for cloud operations on AWS.", "type": "Code talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Cloud Operations", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358253950001idbt", "sources": ["customer_story"], "ko_desc": "F1 피트 크루에서 영감받은 멀티 에이전트 클라우드 운영 아키텍처 구축 — Bedrock AgentCore, Strands, MCP로 단일 에이전트를 전문화된 팀으로 진화시키는 코드 토크.", "company": "AWS", "thu_am": true, "start_time": "11:00", "length": 60}, {"code": "AIM312-R1", "title": "Beyond fine-tuning: RL for reasoning agents with AWS Trainium", "abstract": "Supervised fine-tuning enables your model to follow instructions, but teaching it to reason requires reinforcement learning. RL workflows demand iterative loops that multiply compute costs, making the price performance of AWS Trainium, a chip built specifically for deep learning AI, critical. In this chalk talk, we explore what techniques like RLHF and GRPO bring to the table and how to run them on Trainium with the AWS Neuron software stack, Torchtitan, HuggingFace TRL, vLLM, and native PyTorch. We compare co-located and disaggregated RL architectures. You'll leave ready to implement cost-effective RL loops that train agents to reason.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Compute", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1790358245912001ii19", "sources": ["customer_story"], "ko_desc": "지시 따르기(SFT)를 넘어 추론 능력을 위한 강화학습(RL) — AWS Trainium에서 RLHF·GRPO 실행과 반복 루프의 컴퓨팅 비용 최적화 방법.", "company": "AWS", "thu_am": false, "start_time": "15:00", "length": 60}, {"code": "CMP324-R1", "title": "GenAI chip selection: From training to inference", "abstract": "Every GenAI workload hits the same question: GPU, Trainium, Graviton, or Inferentia—and when do you use each? In this chalk talk, we walk through a practical decision tree covering model training, real-time inference, and agentic AI workloads. We then go deep on inference cost optimization: right-sizing GPU instances, offloading pre/post-processing to Graviton, using Spot for batch inference, prompt caching, and moving production inference to Inferentia2. Expect opinionated guidance, real customer math from teams that cut inference costs without sacrificing latency, and a whiteboard framework you can take back to your team on Monday.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Compute", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1790358223348001ikwx", "sources": ["customer_story"], "ko_desc": "GPU vs Trainium vs Graviton vs Inferentia — 훈련·추론·에이전틱 AI 워크로드별 최적 칩 선택 의사결정 트리와 추론 비용 최적화 실전 가이드.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "AIM329-R1", "title": "Optimizing model performance with agentic loops on AWS Trainium", "abstract": "Extracting peak performance from AI accelerators requires optimization at every level, from framework configuration down to individual kernels, and the complexity grows with every new workload. Agentic loops replace this manual work with autonomous profiling, diagnosis, and code generation, iterating toward performance targets without human intervention. In this session, we demonstrate this workflow on AWS Trainium, purpose-built to deliver better price-performance for AI workloads. Explore how these loops identify bottlenecks, how persistent memory prevents repeated failures, and how long-running campaigns uncover optimizations for different inference shapes. You will leave able to run agentic optimization loops yourself on AWS Trainium.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Compute", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1790358255369001iABq", "sources": ["customer_story"], "ko_desc": "AI 가속기 최적화를 에이전틱 루프로 자동화 — 수동 프로파일링·진단·코드 생성 대신 에이전트가 자율적으로 성능 목표를 향해 반복 최적화.", "company": "AWS", "thu_am": false, "start_time": null, "length": 60}, {"code": "CMP407-R1", "title": "Orchestrating Physical AI workloads on AWS: Compute and pipeline patterns", "abstract": "Physical AI projects — robotics, autonomous systems, digital twins — require complex multi-stage pipelines spanning simulation, training, evaluation, and edge deployment. Each stage demands different compute and orchestration. In this chalk talk, we'll whiteboard architecture patterns combining AWS Batch for parallel simulation, Amazon EKS with Karpenter for heterogeneous GPU/Trainium training, and SageMaker Hyperpod showcasing managed resiliency. We'll compare when to use EKS vs. Batch vs. ParallelCluster, discuss cost optimization with Capacity Blocks and Spot, and solve attendee architectures live on the whiteboard.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Artificial Intelligence, Compute", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358222647001iOqu", "sources": ["robotics"], "ko_desc": "로보틱스·자율 시스템·디지털 트윈 같은 Physical AI 프로젝트는 시뮬레이션→훈련→평가→엣지 배포의 복잡한 파이프라인 필요 — AWS에서 단계별 컴퓨팅과 오케스트레이션 패턴.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "CMP407-R", "title": "Orchestrating Physical AI workloads on AWS: Compute and pipeline patterns", "abstract": "Physical AI projects — robotics, autonomous systems, digital twins — require complex multi-stage pipelines spanning simulation, training, evaluation, and edge deployment. Each stage demands different compute and orchestration. In this chalk talk, we'll whiteboard architecture patterns combining AWS Batch for parallel simulation, Amazon EKS with Karpenter for heterogeneous GPU/Trainium training, and SageMaker Hyperpod showcasing managed resiliency. We'll compare when to use EKS vs. Batch vs. ParallelCluster, discuss cost optimization with Capacity Blocks and Spot, and solve attendee architectures live on the whiteboard.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Artificial Intelligence, Compute", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1780441497791001GEec", "sources": ["robotics"], "ko_desc": "Physical AI 워크로드 오케스트레이션 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "IND377-R1", "title": "Agentic AI in Production: Natera Saves Lives, Cuts Costs, Grows Revenue", "abstract": "Natera, a global leader in cell-free DNA testing for oncology, women's health, and organ health, built reusable agentic infrastructure on Amazon Bedrock and Amazon Bedrock AgentCore to power multiple internal platforms from a single framework. Natera's VP of Engineering will share the technical decisions behind this infrastructure and provides a blueprint for building once and scaling across your organization. See a live demo of one platform built on this foundation for revenue cycle management, cutting prior-authorization denial rates 6x, reducing touchpoints by 5x, and enabling new use cases to go live in less than a week. ", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Databases", "area_of_interest": "", "industry": "Healthcare & Life Sciences", "features": "Customer story, Discussion, Full", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358248474001ibYK", "sources": ["customer_story"], "ko_desc": "Natera(온콜로지 DNA 검사 기업)가 Bedrock AgentCore로 재사용 가능한 에이전틱 인프라 구축 — 여러 내부 플랫폼을 단일 프레임워크로 운영한 VP Engineering 발표.", "company": "Natera", "thu_am": null, "start_time": "13:00", "length": 60, "ko_full": "세포유리 DNA 검사(종양학, 여성 건강, 장기 건강) 분야의 글로벌 리더인 Natera는 Amazon Bedrock과 Amazon Bedrock AgentCore 위에 재사용 가능한 에이전틱 인프라를 구축해, 하나의 프레임워크로 여러 내부 플랫폼을 구동하고 있습니다.\nNatera의 엔지니어링 VP가 이 인프라 뒤에 있는 기술적 결정들을 공유하고, 한 번 만들어 조직 전체로 확장하기 위한 청사진을 제시합니다.\n이 기반 위에 구축된 수익 주기 관리(revenue cycle management) 플랫폼 하나의 라이브 데모를 보여드립니다. 이 플랫폼은 사전승인(prior-authorization) 거절률을 6배 줄이고, 접점(touchpoints)을 5배 줄이며, 새로운 유스케이스를 일주일 이내에 가동할 수 있게 했습니다."}, {"code": "DVT226", "title": "Best practices for working with shared coding agents on your team", "abstract": "Software development happens through teamwork, but agent work is often trapped in individual sessions. The developer who starts the work becomes the coordinator who needs to relay feedback, reconstruct decisions, or keep agents moving. Working with agents as a team has many paper cuts, but there are best practices you can implement. Follow an issue from investigation through implementation, testing, and review, with requests, decisions, and approvals attributed along the way as work progresses. Learn how team-scoped knowledge, reusable practices, and clear permission boundaries let agents take on ongoing responsibilities while people keep control of what ships.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Artificial Intelligence, Developer Tools", "area_of_interest": "", "industry": "", "features": "Customer story, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1780441472163001Gf4O", "sources": ["customer_story"], "ko_desc": "팀 공유 코딩 에이전트 사용 베스트 프랙티스 — 개인 세션에 갇힌 에이전트 작업을 팀 전체로 확장하고 의사결정을 재현하는 방법.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "DVT332-R1", "title": "Under the hood of Kiro Crew: orchestration, memory, and safe autonomy", "abstract": "Handing real work to a crew of agents raises real questions: How does it coordinate parallel subagents without losing the thread? How does memory save across sessions so agents don't start cold? How do you give agents access to your code and CI while staying safe? In this chalk talk, we'll dig into how Kiro Crew works: observable multi-agent orchestration over Agent Client Protocol, self-evolving memory and skills you can inspect and edit, scheduled and webhook-triggered jobs, and defense-in-depth security with sandboxing, denied-by-default commands, and signed audit logs. Bring your architecture and security questions and we'll whiteboard through them.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Developer Tools", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1790358247471001iqyi", "sources": ["customer_story"], "ko_desc": "Kiro Crew 내부 동작 원리 심층 해부 — 병렬 서브에이전트 오케스트레이션, 세션 간 메모리 유지, 코드베이스 안전 접근 방법.", "company": "AWS (Kiro)", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "DVT332-R2", "title": "Under the hood of Kiro Crew: orchestration, memory, and safe autonomy", "abstract": "Handing real work to a crew of agents raises real questions: How does it coordinate parallel subagents without losing the thread? How does memory save across sessions so agents don't start cold? How do you give agents access to your code and CI while staying safe? In this chalk talk, we'll dig into how Kiro Crew works: observable multi-agent orchestration over Agent Client Protocol, self-evolving memory and skills you can inspect and edit, scheduled and webhook-triggered jobs, and defense-in-depth security with sandboxing, denied-by-default commands, and signed audit logs. Bring your architecture and security questions and we'll whiteboard through them.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Developer Tools", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1780442240909001czLs", "sources": ["customer_story"], "ko_desc": "Kiro Crew 내부 동작 원리 심층 해부 (반복 세션) — 병렬 서브에이전트 오케스트레이션, 세션 간 메모리 유지, 코드베이스 안전 접근 방법.", "company": "AWS (Kiro)", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "HMC310-R1", "title": "Gemini gets closer to traders with AWS Outposts and AWS Local Zones", "abstract": "Gemini, a NASDAQ-listed crypto exchange, serves traders with diverse latency needs. For the most latency-sensitive workloads, AWS Outposts at Gemini's NY5 facility runs adjacent to the matching engine with sub-millisecond connectivity via cross-connects. For cloud-native traders, AWS Local Zones in NYC deliver sub-2ms latency to the matching engine through Amazon VPC peering: bringing compute into New York Local Zone cuts round-trip latency by roughly 80%, with provisioning in minutes rather than months. For customers prioritizing simplicity, the AWS Region offers a fully managed API that also serves agentic trading systems via Model Context Protocol (MCP). Hear how Gemini's tiered model turns compute placement into a competitive lever for your location-sensitive workloads.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "Financial Services", "features": "Customer story, Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1790358252831001ibVP", "sources": ["customer_story"], "ko_desc": "암호화폐 거래소 Gemini가 AWS Outposts(NY5 시설)와 Local Zones으로 초저지연 트레이딩 구현 — 서브밀리초 연결과 클라우드 네이티브 트레이더 모두를 지원.", "company": "Gemini (암호화폐 거래소)", "thu_am": null, "start_time": "11:00", "ko_full": "나스닥 상장 암호화폐 거래소 Gemini는 지연시간 요구가 제각각인 트레이더들에게 서비스를 제공합니다. 지연에 가장 민감한 워크로드를 위해 Gemini의 NY5 시설에 AWS Outposts를 두었고, 이는 매칭 엔진과 인접해 동작하며 크로스 커넥트를 통해 1밀리초 미만의 연결을 제공합니다. 클라우드 네이티브 트레이더에게는 뉴욕의 AWS Local Zones가 Amazon VPC 피어링을 통해 매칭 엔진까지 2밀리초 미만의 지연을 제공합니다. 컴퓨트를 뉴욕 Local Zone으로 가져오면 왕복 지연이 약 80% 줄고, 프로비저닝은 수개월이 아니라 수분 만에 끝납니다.\n단순함을 우선하는 고객에게는 AWS 리전이 완전관리형 API를 제공하며, 이 API는 Model Context Protocol(MCP)을 통해 에이전틱 트레이딩 시스템도 지원합니다. Gemini의 계층형 모델이 컴퓨트 배치를 어떻게 경쟁 우위로 바꾸는지, 위치에 민감한 워크로드를 가진 분들이 들어봅니다.", "length": 60}, {"code": "IND3338", "title": "Accelerate Physical AI development with NVIDIA on AWS", "abstract": "Physical AI is reshaping manufacturing, robotics, and autonomous systems, but realizing that potential requires robust infrastructure and purpose-built tools. AWS and NVIDIA have partnered to simplify the entire Physical AI development lifecycle: from synthetic data generation and model training through sim-to-real validation and hardware-in-loop testing. In this session, discover how the Physical AI Toolchain from AWS provides access to AWS managed infrastructure and NVIDIA’s foundation models and training applications to accelerate every stage of development, reduce time-to-market, and optimize resource utilization across your pipeline.  ", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Automotive, Manufacturing & Industrial", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Wynn/Encore", "sessionID": "1780442245030001cNQ0", "sources": ["robotics"], "ko_desc": "AWS와 NVIDIA가 협력해 제조·로보틱스·자율 시스템의 Physical AI 개발 인프라와 도구 전체를 단순화하는 방법.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "IND102-S", "title": "Accelerating with NVIDIA Omniverse: VW’s Battery Manufacturing Digital Twin (sponsored by NVIDIA)", "abstract": "Deloitte helped Volkswagen Group Components design and deploy a cloud-native, AI-ready digital twin on AWS, powered by NVIDIA Omniverse and the OpenUSD standard, for the GS7 battery production environment. By consolidating fragmented factory data — CAD models, robot programs, camera configurations, and defect imagery — into a photorealistic, simulation-ready scene on AWS, the team enabled virtual commissioning, synthetic inspection data generation, and earlier production validation. The result is a reusable, scalable platform built on AWS infrastructure and NVIDIA's industrial metaverse stack that reduces physical trial effort, accelerates line ramp-up, and creates a foundation for AI-driven quality inspection at scale. This presentation is brought to you by NVIDIA, an AWS Partner.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780441483665001G1Wu", "sources": ["robotics"], "ko_desc": "Deloitte가 Volkswagen의 배터리 생산 환경에 NVIDIA Omniverse·OpenUSD 기반 클라우드 네이티브 디지털 트윈을 AWS에 구축한 사례 (NVIDIA 스폰서).", "company": "Volkswagen (NVIDIA/Deloitte)", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "IND362-R", "title": "Agentic commerce: shopping assistants to agent-ready infrastructure", "abstract": "AI agents are reshaping how consumers discover and purchase products, and retail and CPG brands have a massive opportunity to meet them where they are. This chalk talk covers both sides of the agentic commerce stack. First, we walk through how retailers can launch conversational shopping customized to their catalog and brand voice in weeks with the Agentic Shopping Assistant on AWS, powered by Amazon Bedrock AgentCore and inspired by Amazon's own AI shopping experience. Then we explore how to make your platform discoverable by external AI agents through structured product feeds, headless APIs, and payment orchestration for machine-initiated transactions.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1780442244829001cm9z", "sources": ["retail"], "ko_desc": "AI 에이전트가 소비자의 제품 발견·구매 방식을 바꾸고 있다 — 리테일·CPG 브랜드를 위한 에이전틱 커머스 스택 구축 방법(쇼핑 어시스턴트부터 에이전트 지원 인프라까지).", "company": "AWS", "thu_am": true, "start_time": "09:00", "length": 60}, {"code": "IND362-R1", "title": "Agentic commerce: shopping assistants to agent-ready infrastructure", "abstract": "AI agents are reshaping how consumers discover and purchase products, and retail and CPG brands have a massive opportunity to meet them where they are. This chalk talk covers both sides of the agentic commerce stack. First, we walk through how retailers can launch conversational shopping customized to their catalog and brand voice in weeks with the Agentic Shopping Assistant on AWS, powered by Amazon Bedrock AgentCore and inspired by Amazon's own AI shopping experience. Then we explore how to make your platform discoverable by external AI agents through structured product feeds, headless APIs, and payment orchestration for machine-initiated transactions.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1790358234675001ispU", "sources": ["retail"], "ko_desc": "에이전틱 커머스 스택 구축 방법 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "IND3355", "title": "Building Worlds for Machines: VAMS and 3DGS for Autonomy", "abstract": "Autonomous platforms are only as capable as the environments they train and validate in. In this Lightning Talk, see how AWS uses the Visual Asset Management System (VAMS) and 3D Gaussian Splatting (3DGS) to turn real field data collected during Project MAVERICK exercises into high-fidelity, simulation-ready environments. We walk the pipeline from sensor capture to reconstructed, simulation-ready worlds, and the content management that makes them reusable. These environments are not the autonomy; they are what builds, improves, and validates it. If you build or validate autonomous systems, you leave knowing how to turn field capture into reusable simulation-ready environments.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Government", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1791930073276001DUy9", "sources": ["robotics"], "ko_desc": "자율 플랫폼의 훈련·검증 환경 구축 — AWS VAMS와 3D Gaussian Splatting으로 실제 장면을 기계 학습 가능한 3D 환경으로 변환.", "company": "AWS", "thu_am": false, "start_time": "16:00", "length": 20}, {"code": "IND376-R1", "title": "How to Deploy Purpose-Built Clinical AI Agents to Production with Speed and Scale", "abstract": "Providers lose hours daily to documentation, manual coding, and admin work. Leading health IT builders are solving this with purpose-built AI on AWS. In this chalk talk, Innovaccer joins AWS to share how they trained task-specific clinical small language models that deliver consistent outputs where general-purpose LLMs produce unacceptable variance. We use their architecture as a jumping-off point to discuss the full spectrum of paths to production: custom model training on accelerated compute, multi-step agentic workflow orchestration, and embedding fully managed clinical AI capabilities into existing applications.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Healthcare & Life Sciences", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358224401001iCcd", "sources": ["customer_story"], "ko_desc": "Innovaccer가 임상 특화 소형 언어 모델(SLM)을 훈련해 의사 문서화·코딩 자동화 — 범용 LLM 대비 일관된 출력으로 헬스케어 실무에 적용한 사례.", "company": "Innovaccer", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "IND345", "title": "Human+AI Collaboration: How Amazon Deploys Autonomous Operations on AWS", "abstract": "Amazon deploys humanoids, autonomous mobile robots, and humans as a unified workforce operating side-by-side on the fulfillment floor. Learn how Amazon evolved an AI-powered verification pipeline, built with Amazon Nova on Bedrock to validate 200K+ items, into a fleet orchestration platform dispatching foundation-model inference across humanoids, quadrupeds, AMRs, and drones. We deep-dive into the architectural patterns enabling humans to work alongside robots at scale: a serverless Lambda backend that abstracts the robot form factor, multi-vendor humanoid integration, and edge deployment strategies. You'll leave with a framework for physical AI orchestration of heterogeneous fleets while optimizing throughput and cost.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Artificial Intelligence, Industry Solutions", "area_of_interest": "", "industry": "Automotive, Manufacturing & Industrial", "features": "Lecture-style", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Wynn/Encore", "sessionID": "1780441477699001GgxY", "sources": ["robotics"], "ko_desc": "Amazon이 인간형 로봇·자율 이동 로봇·사람을 통합된 인력으로 함께 운영 — Amazon Nova 기반 AI 검증 파이프라인으로 물류 창고 자동화 운영 사례.", "company": "Amazon Robotics", "thu_am": null, "start_time": "08:00", "length": 60}, {"code": "IND3304-R1", "title": "KNFSD File Cache: Extending Your NFS Storage into the Cloud", "abstract": "Need to cache and serve NFS data from on-premises filers, across Availability Zones and Regions, or from other cloud providers with full read and write-back support? In this chalk talk, dive into KNFSD File Cache, an open-source, kernel-based NFS caching proxy on Amazon EC2 that transparently extends existing NFS storage into AWS. A single Terraform module stands up a production-ready, autoscaling cluster with high throughput and at low cost. Discuss hybrid and burst-compute patterns across M&E, HPC, Financial Services, and Life Sciences industries—eliminating latency without migration, client changes, or vendor lock-in.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Migration & Modernization", "area_of_interest": "", "industry": "Media & Entertainment", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1790358240915001ipNX", "sources": ["customer_story"], "ko_desc": "KNFSD 파일 캐시로 온프레미스 NFS 스토리지를 클라우드로 투명하게 확장 — 단일 Terraform 모듈로 프로덕션 준비 완료 캐시 배포.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "INV515-R1", "title": "Modeling Human Preference: Pairwise Battles to Agentic Systems", "abstract": "Every time we rank an LLM, we're building a model of human preference — yet for most queries there's no ground truth, only a person's sense of which answer is better, shifting with expertise, culture, and expectations. This session examines how we model preference across two regimes: pairwise battles, arena-style voting ranked through Bradley-Terry, and agentic systems, where preference spans long-horizon, multi-step, tool-using tasks. Reward models and LLM-as-judge are themselves learned preference models; from our experience at Amazon, we examine when to trust them and how to separate progress from preference-overfitting. Attendees will learn what modeling preference at scale demands.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Artificial Intelligence, Open Source", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441496134001GM3i", "sources": ["customer_story"], "ko_desc": "인간 선호도 모델링의 두 체계 비교 — 페어와이즈 배틀(Bradley-Terry 방식) vs 에이전틱 시스템의 장기 상호작용 선호도 수치화 방법.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "COM311-R1", "title": "Your Users Aren't Waiting to Build AI Agents. Are You Ready?", "abstract": "The spreadsheet wizards and automation tinkerers in your organization are already reaching for low-code and visual builder tools to assemble AI agents on their own. Call it citizen agent building: either governance sprawl, or your fastest path to scale. This interactive chalk talk gives platform, security, and data leaders a reference pattern that puts low-code builders on top and Amazon Bedrock beneath, so the security, data residency, and governance enterprises need come from the foundation rather than from each agent. Amazon Bedrock makes governance possible; your architecture makes it the default.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Open Source", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion, Full", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1790358257850001iIIe", "sources": ["customer_story"], "ko_desc": "조직 내 시민 개발자들이 이미 로우코드 도구로 AI 에이전트를 만들고 있다 — 플랫폼·보안·데이터 리더를 위한 Bedrock 기반 거버넌스 레퍼런스 아키텍처.", "company": "Idea 11, Kablamo", "thu_am": null, "start_time": "11:30", "length": 60, "room": "Level 3 | Premier 311", "ko_full": "여러분 조직의 스프레드시트 고수와, 자동화 도구를 이것저것 만져 보는 사람들은 이미 로우코드·비주얼 빌더 도구로 AI 에이전트를 스스로 조립하고 있습니다. 이를 시민 에이전트 개발(citizen agent building)이라 부릅니다. 거버넌스 난립이 될 수도 있고, 확장으로 가는 가장 빠른 길이 될 수도 있습니다.\n이 인터랙티브 칠크 토크는 플랫폼, 보안, 데이터 리더에게 레퍼런스 패턴을 제공합니다. 위에는 로우코드 빌더를, 아래에는 Amazon Bedrock을 두어, 기업에 필요한 보안, 데이터 거주(data residency), 거버넌스가 에이전트 하나하나가 아니라 기반에서 나오게 하는 구조입니다.\nAmazon Bedrock은 거버넌스를 가능하게 하고, 여러분의 아키텍처는 그것을 기본값으로 만듭니다."}, {"code": "COM321-R1", "title": "The Agent Harness You Own on AWS for Regulated Industries", "abstract": "In regulated industries the model is easy; the governable, auditable, defensible agent is hard. AgentCore ships primitives, but the governance harness you own on top is the real work. We build the rails it does not give you: a fail-closed, blocklist-first permission gate where deny beats a broad allow; a hash-chained audit verifiable off-cloud; and a RACI gate binding every action to a named human. Each maps onto a managed AWS primitive — Identity, Guardrails, Evaluations, Lambda MicroVMs for isolation — naming where the primitive ends and your code begins. You leave with the rails.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1790358219993001iZ2c", "sources": ["customer_story"], "ko_desc": "규제 산업을 위한 자체 소유 에이전트 하네스 — AgentCore가 제공하지 않는 fail-closed 권한 게이트, 해시 체인 감사 로그, RACI 게이트를 직접 구현.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "COM316-R1", "title": "Think Beyond DevOps: SRE, SOC, and Compliance in One AWS DevOps Agent", "abstract": "As AI speeds up releases, continuous security control assurance and detecting threats in millions of telemetry signals get harder. We transformed AWS DevOps Agent into one agent for SRE, SOC and compliance, effectively addressing AI-era cloud security challenges in production. With AWS Config Conformance Packs for compliance-as-code and security MCP for finding triage, it produces point-in-time compliance and well-architected assessments, and drives alarm-triggered agentic SOC investigations within a controlled agent space, automating responses and keeping human-in-the-loop on high-risk mitigations only. You'll learn the methodology to design an agentic compliance and SOC solution that ports seamlessly into your own environment. ", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358245087001iXUn", "sources": ["customer_story"], "ko_desc": "AWS DevOps Agent를 SRE·SOC·컴플라이언스 통합 에이전트로 확장 — AI 가속 릴리즈 시대에 클라우드 보안 제어를 실시간으로 보장하는 방법.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "COM312-R1", "title": "Giving Your AI Agent a Wallet: The Architecture of Spend Control", "abstract": "AI agents can now hold a wallet and pay for APIs, data, and even other agents. The demo takes a few hours; making it safe to ship takes much longer. At the whiteboard, using Amazon Bedrock AgentCore Payments, x402 micropayments, and Cedar policy, we design an agent that spends under a hard budget, then break it together. We work through where guardrails belong, why session limits aren't enough, custodial versus non-custodial tradeoffs, and human-in-the-loop without human-in-the-way. Bring your edge cases. You leave with a reference architecture and a checklist for bounded agent autonomy.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Artificial Intelligence, Serverless, Containers", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358236580001i0Om", "sources": ["customer_story"], "ko_desc": "AI 에이전트에 지갑 기능 부여 아키텍처 — Bedrock AgentCore Payments와 Cedar 정책으로 에이전트 지출에 하드 예산 상한을 설정하고 안전하게 제어.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "AIM256-S", "title": "1 Customer, 1 Context, From all the Channels: (sponsored by Redis)", "abstract": "Join Toshish Jawale, Head of AI Engineering at Invoca, to learn how his team is putting context at the center of the business’ customer journeys. Hear how Invoca and Redis are delivering real-time, mutli-source context for Invoca’s agents, how they’re helping customers interact with their brand in exciting ways, and how they’re delivering complete pictures of user brand experiences. This presentation is brought to you by Redis, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1780441486844001GgnL", "sources": ["business_agents"], "ko_desc": "Invoca가 Redis로 옴니채널 고객 여정의 중심에 컨텍스트를 배치 — 실시간 멀티소스 컨텍스트로 AI 기반 고객 참여를 강화하는 방법 (Redis 스폰서).", "company": "Redis", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ216", "title": "AI Assistant for Public Sector: Governance Without Compromise with Amazon Quick", "abstract": "Public sector organizations serve diverse populations with strict boundaries: students and administrators, citizens and case workers, patients and providers. They need AI that works across these groups without compromising data isolation, compliance, or governance. Multi-tenant environments demand security frameworks most AI assistants were not built to meet.\n\nHear from a higher education customer who faced these constraints and displaced their incumbent tool in favor of Amazon Quick's governance-first architecture: tenant-level data isolation, role-based access controls across distinct user populations, and compliance frameworks built for regulated environments. Learn why existing solutions fell short, how Quick's native governance model met their requirements without custom engineering, and what the transition looked like from decision to deployment.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780441465879001GC5t", "sources": ["business_agents"], "ko_desc": "공공 부문의 다양한 사용자 그룹(학생·공무원·시민·환자)을 위한 AI 어시스턴트 — Amazon Quick으로 경계를 침범하지 않으면서 AI 지원 구현.", "company": "AWS (공공)", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ213", "title": "Accelerating AI adoption and realized value with Amazon Quick", "abstract": "Most AI investments stall because leaders hand off adoption instead of leading it. 3M did the opposite. It put Amazon Quick in the hands of its top 75 executives first, so the people who set strategy saw the value before they asked their teams to adopt it. With governed access to enterprise data, senior leaders now use Quick to make decisions faster, bring their teams onto shared workflows and turn AI from a personal tool into a team-wide advantage. Learn what executive sponsorship changed, what leaders gained in speed and focus and how to build the same momentum in your organization.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780441465993001GIUO", "sources": ["business_agents"], "ko_desc": "3M이 최고 경영진 75명에게 먼저 Amazon Quick을 도입한 이유 — 전략을 수립하는 사람들이 가치를 먼저 경험하게 하는 AI 채택 가속 방법.", "company": "3M", "thu_am": false, "start_time": "13:00", "length": 60}, {"code": "BIZ201-R", "title": "Agentic Integration: How AI Agents Replace Static CRM Connectors", "abstract": "Every enterprise has dozens of integrations connecting their CRM, ticketing, and backend systems to their customer experience platform, and every one of them is static, brittle, and expensive to maintain. In this chalk talk, we explore how Amazon Connect Customer, powered by Model Context Protocol (MCP), shifts integration from point-to-point connectors to intelligent, agentic orchestration. The AI agent reasons across multiple systems in real time, assembling unified customer context that no single system holds alone. We whiteboard the architecture: how MCP connections work, how each new system compounds the intelligence available to every interaction, and how to evaluate which integrations to migrate first. Bring your integration pain (Salesforce, ServiceNow, homegrown systems) and we'll design the agentic alternative on the whiteboard.", "type": "Chalk talk", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236476001cvRS", "sources": ["business_agents"], "ko_desc": "모든 기업은 CRM·티켓팅·백엔드 시스템을 연결하는 수십 개의 정적이고 취약한 통합을 운영 — 이를 AI 에이전트 기반 동적 통합으로 교체하는 방법.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ201-R1", "title": "Agentic Integration: How AI Agents Replace Static CRM Connectors", "abstract": "Every enterprise has dozens of integrations connecting their CRM, ticketing, and backend systems to their customer experience platform, and every one of them is static, brittle, and expensive to maintain. In this chalk talk, we explore how Amazon Connect Customer, powered by Model Context Protocol (MCP), shifts integration from point-to-point connectors to intelligent, agentic orchestration. The AI agent reasons across multiple systems in real time, assembling unified customer context that no single system holds alone. We whiteboard the architecture: how MCP connections work, how each new system compounds the intelligence available to every interaction, and how to evaluate which integrations to migrate first. Bring your integration pain (Salesforce, ServiceNow, homegrown systems) and we'll design the agentic alternative on the whiteboard.", "type": "Chalk talk", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358257572001ihev", "sources": ["business_agents"], "ko_desc": "모든 기업은 CRM·티켓팅·백엔드 시스템을 연결하는 정적 통합을 운영 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "BIZ403-R1", "title": "Agentic Memory: Build AI Agents That Learn from Every Interaction", "abstract": "Today's AI agents forget everything after each conversation ends. A customer calls back about the same issue for the third time, and the agent starts from zero. In this chalk talk, we explore how to architect persistent memory systems for Amazon Connect Customer AI agents, enabling them to remember customer preferences, recall prior issue context, and adapt resolution strategies over time. We walk through three memory patterns: episodic (past interactions), semantic (customer knowledge graphs), and procedural (learned resolution paths). We whiteboard real architectures using Customer Profiles, Bedrock knowledge bases, and DynamoDB to build agents that reduce repeat contacts and deliver personalized experiences, without retraining models. Bring your memory challenge and we'll design the persistence layer on the whiteboard.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358214919001i73a", "sources": ["business_agents"], "ko_desc": "AI 에이전트가 대화가 끝나면 모든 것을 잊는 문제 — 같은 문제로 세 번째 전화하는 고객에게 처음부터 다시 시작하지 않는 지속적 에이전트 메모리 아키텍처.", "company": "AWS", "thu_am": false, "start_time": "13:00", "length": 60}, {"code": "BIZ403-R", "title": "Agentic Memory: Build AI Agents That Learn from Every Interaction", "abstract": "Today's AI agents forget everything after each conversation ends. A customer calls back about the same issue for the third time, and the agent starts from zero. In this chalk talk, we explore how to architect persistent memory systems for Amazon Connect Customer AI agents, enabling them to remember customer preferences, recall prior issue context, and adapt resolution strategies over time. We walk through three memory patterns: episodic (past interactions), semantic (customer knowledge graphs), and procedural (learned resolution paths). We whiteboard real architectures using Customer Profiles, Bedrock knowledge bases, and DynamoDB to build agents that reduce repeat contacts and deliver personalized experiences, without retraining models. Bring your memory challenge and we'll design the persistence layer on the whiteboard.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236537001cY3e", "sources": ["business_agents"], "ko_desc": "AI 에이전트 지속 메모리 아키텍처 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "08:00", "length": 60}, {"code": "BIZ307", "title": "Architect AI-powered analytics with Amazon Quick across your data platforms", "abstract": "As organizations adopt AI-powered analytics, they need architectures that connect BI and conversational AI experiences to their existing data platforms. In this session we'll diagram architectural patterns for connecting Amazon Quick to structured data sources and integrating with third-party catalogs and semantic layers. We'll compare the available connectivity approaches, including data sources and MCP-based action connectors, and discuss when to use each. Considerations will span production use cases like BI dashboards, embedded analytics, text-to-SQL Q&A, and agentic workflows. Together we'll tackle real-world integration challenges including authentication, performance optimization, and governance. This session is ideal for architects and technical leaders looking to build AI-powered analytics across their data platforms.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236341001c13t", "sources": ["business_agents"], "ko_desc": "Amazon Quick 기반 AI 분석을 기존 BI·데이터 플랫폼에 연결하는 아키텍처 패턴 — 기업의 데이터 플랫폼 위에 대화형 AI 경험을 구축하는 방법.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "BIZ316-R1", "title": "Beyond English: Architecture Patterns for Multilingual AI Voice Agents", "abstract": "Deploying AI voice agents beyond English introduces unique challenges: accent handling, language detection, code-switching between languages mid-conversation, and cultural nuances in conversation flow. In this chalk talk, we share architecture patterns for building multilingual voice agents using Amazon Connect Agentic Voice. We cover real-world scenarios from deployments like Spanish and English coexistence, German with regional dialects, and Italian conversational AI. We discuss when speech-to-speech models work natively, when to fall back to TTS pipelines, how to handle polyglot but non-native accent scenarios, and practical approaches to knowledge base localization. Bring your language challenge and we'll design your multilingual architecture on the whiteboard.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358226185001iTK7", "sources": ["business_agents"], "ko_desc": "영어 이외 언어 AI 음성 에이전트 배포 과제 — 억양 처리·언어 감지·중간 언어 전환·문화적 대화 흐름 처리 아키텍처 패턴.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "BIZ316-R", "title": "Beyond English: Architecture Patterns for Multilingual AI Voice Agents", "abstract": "Deploying AI voice agents beyond English introduces unique challenges: accent handling, language detection, code-switching between languages mid-conversation, and cultural nuances in conversation flow. In this chalk talk, we share architecture patterns for building multilingual voice agents using Amazon Connect Agentic Voice. We cover real-world scenarios from deployments like Spanish and English coexistence, German with regional dialects, and Italian conversational AI. We discuss when speech-to-speech models work natively, when to fall back to TTS pipelines, how to handle polyglot but non-native accent scenarios, and practical approaches to knowledge base localization. Bring your language challenge and we'll design your multilingual architecture on the whiteboard.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236415001cBZK", "sources": ["business_agents"], "ko_desc": "다국어 AI 음성 에이전트 아키텍처 패턴 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "BIZ306", "title": "Bring Your Own Ontology: Ground Amazon Quick in Enterprise Knowledge with AWS Context", "abstract": "Enterprise questions rarely have answers in a single document. Your business runs on connections — customers to products, teams to processes, risks to regulations — but vector search doesn't see any of that. In this chalk talk, we show how to ground Amazon Quick in your enterprise context by integrating it with a knowledge graph built from your domain knowledge. We'll walk through how we built this pattern using GraphRAG for real customers and the results they achieved. Then we'll open the whiteboard — bring your toughest use case and we'll sketch your ontology live, showing how Quick would traverse it to deliver dramatically better answers.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion, Full", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236283001csyO", "sources": ["business_agents"], "ko_desc": "기업의 질문은 단일 문서에 답이 없다 — 고객-제품-팀-프로세스 연결 관계를 이해하는 온톨로지로 Amazon Quick을 기업 지식에 기반시키는 방법.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60, "ko_full": "기업의 질문은 답이 문서 한 곳에 있는 경우가 드뭅니다. 비즈니스는 고객과 제품, 팀과 프로세스, 리스크와 규제처럼 서로 연결되어 돌아가는데, 벡터 검색은 이런 연결을 전혀 보지 못합니다.\n이 칠크 토크에서는 도메인 지식으로 구축한 지식 그래프를 Amazon Quick과 통합해, Quick이 기업의 맥락에 근거하도록(grounding) 만드는 방법을 보여드립니다. 실제 고객을 위해 GraphRAG로 이 패턴을 어떻게 구축했는지, 그리고 고객이 거둔 결과를 살펴봅니다.\n이어서 화이트보드를 엽니다. 가장 어려운 유스케이스를 가져오시면 그 자리에서 온톨로지를 스케치하고, Quick이 이 온톨로지를 어떻게 탐색(traverse)해 훨씬 나은 답을 내놓는지 보여드립니다."}, {"code": "BIZ317-R", "title": "Build It or Bring It: Getting AI Agents into CX Faster", "abstract": "Getting agentic AI from prototype to production in your customer experience application is slow, and the gap is widening. In this chalk talk we give you two levers to close it on Amazon Connect Customer. Build new AI agents on the agentic CX designer canvas, describing what you want in natural language and applying enterprise guardrails to reach production-grade quickly. Or bring the agents your business has already built, anywhere, and orchestrate them through Connect Customer using the Agent-to-Agent (A2A) protocol. We demonstrate both, then whiteboard how they fit together architecturally. Come ready to challenge the design and share where you would use each.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236593001c9jb", "sources": ["business_agents"], "ko_desc": "에이전틱 AI를 CX 앱 프로토타입에서 프로덕션으로 가져가는 두 가지 레버 — Amazon Connect에서 새 AI 에이전트 구축과 기존 에이전트 가져오기.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "BIZ317-R1", "title": "Build It or Bring It: Getting AI Agents into CX Faster", "abstract": "Getting agentic AI from prototype to production in your customer experience application is slow, and the gap is widening. In this chalk talk we give you two levers to close it on Amazon Connect Customer. Build new AI agents on the agentic CX designer canvas, describing what you want in natural language and applying enterprise guardrails to reach production-grade quickly. Or bring the agents your business has already built, anywhere, and orchestrate them through Connect Customer using the Agent-to-Agent (A2A) protocol. We demonstrate both, then whiteboard how they fit together architecturally. Come ready to challenge the design and share where you would use each.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358255919001isXm", "sources": ["business_agents"], "ko_desc": "에이전틱 AI를 CX 앱 프로토타입에서 프로덕션으로 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ111-S", "title": "Build the Agentic Workplace: What's New on the Slack Developer Platform (sponsored by Salesforce)", "abstract": "Slack is becoming a multiplayer work operating system, where humans and AI agents build together, not just chat. This session shows AWS developers how to ship on the modern Slack Platform: Code Channels, a new space where agents like Claude Code, Devin, and Cursor collaborate with teams in real time; the Slack Agent Kit for building first-class agents; deep bidirectional MCP support, including the Slackbot MCP Client; Real-Time Search (RTS) for grounding agents in live workspace context; and Block Kit for rich, interactive UI. Leave with a clear path to build your first agentic app on Slack. This presentation is brought to you by Salesforce, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780442273524001cazM", "sources": ["business_agents"], "ko_desc": "Slack이 인간과 AI 에이전트가 함께 구축하는 멀티플레이어 작업 운영 시스템으로 진화 — Code Channels로 Slack에서 AWS 서비스를 직접 개발·배포 (Salesforce 스폰서).", "company": "Salesforce", "thu_am": null, "start_time": "11:00", "length": 20}, {"code": "BIZ304", "title": "Building & Governing Apps on Quick", "abstract": "Anyone can generate apps from a sentence - the hard part is governing them and getting them in front of the right users. This chalk talk whiteboards the full lifecycle of Amazon Quick Apps: building them from natural language with no separate hosting, wiring in data and actions through MCP, and the three sharing paths - private, public URLs, and enterprise sharing gated behind admin approval workflows. ", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780442236172001cIVj", "sources": ["business_agents"], "ko_desc": "자연어 한 문장으로 앱 생성은 쉽다 — Amazon Quick Apps의 전체 라이프사이클: 거버넌스·배포·올바른 사용자에게 전달하는 방법.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ326-R", "title": "Building a Knowledge & Context Engineering Foundation for AI Agents ", "abstract": "Every enterprise building agentic AI hits the same wall: AI agents can't deliver trusted guidance without governed knowledge behind them. In this session, learn how AWS solved this internally with an agentic specialist teammate for Amazon Connect powered by a structured knowledge governance framework. We'll show how specialist reasoning is captured, validated, and scaled across 92 domains to 30K+ field members, and demonstrate the live workflow from governed knowledge delivery to human escalation. Walk away with a repeatable reference architecture for making your own AI agents production-ready and trustworthy.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion, Full", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236949001c3sW", "sources": ["business_agents"], "ko_desc": "모든 에이전틱 AI 구축 기업은 같은 벽에 부딪힌다 — 통치된 지식 없이 에이전트는 신뢰할 수 있는 가이드를 제공할 수 없다. AWS가 내부적으로 이를 해결한 방법.", "company": "AWS", "thu_am": null, "start_time": "09:00", "length": 60, "ko_full": "에이전틱 AI를 구축하는 모든 기업이 같은 벽에 부딪힙니다. AI 에이전트는 거버넌스가 적용된 지식이 뒷받침되지 않으면 신뢰할 수 있는 안내를 제공할 수 없습니다.\n이 세션에서는 AWS가 이 문제를 내부적으로 어떻게 해결했는지를 소개합니다. 구조화된 지식 거버넌스 프레임워크로 구동되는, Amazon Connect용 에이전틱 '전문가 팀원'입니다. 전문가의 추론이 92개 도메인에 걸쳐 어떻게 수집되고, 검증되고, 확장되어 3만 명 이상의 현장(field) 구성원에게 전달되는지를 보여드리고, 거버넌스된 지식 전달에서 사람에게 에스컬레이션하기까지의 라이브 워크플로우를 시연합니다.\n자사의 AI 에이전트를 프로덕션 수준으로 신뢰할 수 있게 만들기 위한, 반복 가능한 레퍼런스 아키텍처를 가져가실 수 있습니다."}, {"code": "BIZ326-R1", "title": "Building a Knowledge & Context Engineering Foundation for AI Agents ", "abstract": "Every enterprise building agentic AI hits the same wall: AI agents can't deliver trusted guidance without governed knowledge behind them. In this session, learn how AWS solved this internally with an agentic specialist teammate for Amazon Connect powered by a structured knowledge governance framework. We'll show how specialist reasoning is captured, validated, and scaled across 92 domains to 30K+ field members, and demonstrate the live workflow from governed knowledge delivery to human escalation. Walk away with a repeatable reference architecture for making your own AI agents production-ready and trustworthy.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion, Full", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358249996001iHXS", "sources": ["business_agents"], "ko_desc": "에이전틱 AI를 위한 지식·컨텍스트 엔지니어링 기반 (반복 세션).", "company": "AWS", "thu_am": true, "start_time": "08:00", "length": 60}, {"code": "BIZ109", "title": "Citizens Bank: Building AI-Native CX from Vision to Production", "abstract": "Financial services customers expect fast, personalized service, but compliance, security, and regulatory requirements make automation a high-stakes challenge. Discover how Amazon Connect Customer enables financial institutions to design agentic customer experiences, where AI self-service blends autonomous reasoning with deterministic guardrails for identity verification, fraud checks, and regulatory disclosures. Learn how business teams, not only engineers, build and refine these experiences, automating complex interactions like account servicing, disputes, and payments while maintaining full compliance and governance. See how Citizens Bank lifted containment by 30 points, elevated CSAT, and transformed their contact center without compromising trust.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780441465771001GPVt", "sources": ["business_agents"], "ko_desc": "Citizens Bank가 Amazon Connect로 금융 서비스 AI 네이티브 CX를 비전에서 프로덕션까지 구현 — 컴플라이언스·보안·규제 요건을 충족하면서 자동화 적용.", "company": "Citizens Bank", "thu_am": null, "start_time": "08:00", "length": 60}, {"code": "BIZ108", "title": "Customer Care Reimagined: How a leading bank connects AI end to end", "abstract": "Discover how a leading bank is reimagining Customer Care by connecting AI across the end-to-end journey. Instead of isolated pilots, they built joined-up capabilities on Amazon Connect Customer and Amazon Bedrock, delivered as incremental releases with governance from day one. Hear how four AI capabilities, from real-time colleague assistance to automated coaching across 100% of interactions, are already live and making a measurable difference for colleagues and customers. We will share the reusable architecture, lessons learned, and what comes next as these capabilities reach customer-facing journeys.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1780441465715001GHij", "sources": ["business_agents"], "ko_desc": "선도적 은행이 Amazon Connect와 Bedrock으로 AI를 고객 여정 전반에 연결한 방법 — 고립된 파일럿 대신 통합된 AI 역량 구축.", "company": "선도 은행 (익명)", "thu_am": true, "start_time": "10:00", "length": 60}, {"code": "BIZ323-R1", "title": "Decision Frameworks, Evaluation, and Cost Management with Amazon Quick", "abstract": "Moving from one agent to enterprise-wide automation means choosing the right path — Flows, Automate, Custom Agents, persistent agents — and the right trigger model. In this chalk talk, we whiteboard a decision framework that bakes in evaluation and cost management from the start, not as afterthoughts. We'll connect orchestration across 25+ connectors, skills, and workstreams to measurable outcomes and dollars. Bring your automation backlog — you'll leave with a decision matrix, eval harness, and ROI story.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358238440001iWJK", "sources": ["business_agents"], "ko_desc": "Flows vs Automate vs Custom Agents vs 지속적 에이전트 중 무엇을 선택할 것인가 — Amazon Quick 자동화 의사결정 프레임워크와 비용 관리.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "BIZ323-R", "title": "Decision Frameworks, Evaluation, and Cost Management with Amazon Quick", "abstract": "Moving from one agent to enterprise-wide automation means choosing the right path — Flows, Automate, Custom Agents, persistent agents — and the right trigger model. In this chalk talk, we whiteboard a decision framework that bakes in evaluation and cost management from the start, not as afterthoughts. We'll connect orchestration across 25+ connectors, skills, and workstreams to measurable outcomes and dollars. Bring your automation backlog — you'll leave with a decision matrix, eval harness, and ROI story.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236647001cJvn", "sources": ["business_agents"], "ko_desc": "Amazon Quick 자동화 의사결정 프레임워크 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ210", "title": "Deploy AI planning teammates without changing how your team works", "abstract": "Most planning tools force your team to change how they work. See the opposite approach. Watch AI teammates plug into the workflows your planners already follow, connect to the systems you already run, and improve as they learn your business. You will see a live product walkthrough, learn where AI takes work off your team's plate, and leave with a clear picture of how to add planning capacity without retraining people or rebuilding your stack.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780441466208001GVlO", "sources": ["business_agents"], "ko_desc": "기존 계획 워크플로우를 바꾸지 않고 AI 플래닝 팀원 배치 — 플래너가 이미 따르는 워크플로우에 AI 팀원이 연결되어 기존 시스템에서 개선.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "BIZ214", "title": "Empowering 155,000 people without compromising trust: Amazon Quick", "abstract": "Allianz needed to empower 155,000 employees with AI without sacrificing trust. With operations across dozens of regulated markets, the security, privacy, and works council requirements were non-negotiable. Every stakeholder asked the same question: how do you move fast and still earn the trust of those guarding your company's security? Hear how Allianz partnered with AWS to deploy the capabilities that make Amazon Quick enterprise-ready: protection of confidential information, structured approval workflows for agentic actions, custom branding per business unit, and multi-language support. Learn how Allianz navigated the full approval process and moved from \"not yet\" to \"go\" in six weeks.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1780441466315001GqmS", "sources": ["business_agents"], "ko_desc": "Allianz가 15만 5천 명 직원에게 신뢰를 손상시키지 않고 Amazon Quick 배포 — 수십 개 규제 시장에서 보안·개인정보·근로위원회 요건 충족.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ330-R1", "title": "Evaluate, Disclose, Safeguard: A Production-Readiness Framework for AI Agents", "abstract": "Every organization is building AI agents, but few have made it to production. You can't prove it works, you can't prove it's responsible, and compliance won't sign off. In this chalk talk, we walk through a production-readiness framework for AI agents on Amazon Connect. First, evaluation: measuring resolution with the Connect Simulation API to score AI agents on the same bar as human agents. Second, responsible AI: disclosure patterns that build trust, escalation triggers for sensitive journeys, and harm avoidance for regulated industries. Third, safeguards: defense-in-depth governance for agents that process refunds and access sensitive data, including asymmetric PII, MCP tool authorization for human confirmation, and automated escalation when confidence drops. Leave with a checklist: what to measure, what to disclose, what to block, and when to ship.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1790358246288001iBQV", "sources": ["business_agents"], "ko_desc": "AI 에이전트를 프로덕션까지 가져가지 못하는 팀을 위한 프로덕션 준비도 프레임워크 — 작동 증명·책임 AI 증명·컴플라이언스 승인 획득 방법.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ330-R", "title": "Evaluate, Disclose, Safeguard: A Production-Readiness Framework for AI Agents", "abstract": "Every organization is building AI agents, but few have made it to production. You can't prove it works, you can't prove it's responsible, and compliance won't sign off. In this chalk talk, we walk through a production-readiness framework for AI agents on Amazon Connect. First, evaluation: measuring resolution with the Connect Simulation API to score AI agents on the same bar as human agents. Second, responsible AI: disclosure patterns that build trust, escalation triggers for sensitive journeys, and harm avoidance for regulated industries. Third, safeguards: defense-in-depth governance for agents that process refunds and access sensitive data, including asymmetric PII, MCP tool authorization for human confirmation, and automated escalation when confidence drops. Leave with a checklist: what to measure, what to disclose, what to block, and when to ship.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236708001cZlJ", "sources": ["business_agents"], "ko_desc": "AI 에이전트 프로덕션 준비도 프레임워크 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ325", "title": "Fix Data Gaps Fast: Agentic Onboarding with Amazon Connect Decisions", "abstract": "81% of enterprises report AI initiatives delayed or abandoned due to data and governance gaps — and 80–90% of new enterprise data is unstructured. The bottleneck isn't the model; it's the data. In this session, see how Amazon Connect Decisions uses agentic AI teammates to eliminate that gap. Watch a supply chain planner go from zero to a running demand forecast — connecting raw CSVs with no pre-cleaning, letting AI intelligently map and type-convert data, catching and fixing quality issues conversationally, and encoding tribal knowledge from a Word doc into live decision rules. No ETL code, no JIRA tickets, no months-long implementation. Onboarding in weeks, not months.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236897001cqDM", "sources": ["business_agents"], "ko_desc": "81%의 기업이 데이터·거버넌스 격차로 AI 이니셔티브 지연·포기 — Amazon Connect Decisions로 온보딩 과정에서 데이터 격차를 빠르게 메우는 방법.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ218", "title": "From AI Tasks to Autonomous Multi-Agent Workflows with Amazon Quick", "abstract": "The workflows that matter most in financial services span multiple systems, require multiple types of expertise, and today rely on people as the coordination layer. One person pulls data, another reviews it for compliance, a third routes it for approval. That coordination tax is where your team's time disappears. Amazon Quick changes that equation. Instead of one AI assistant doing one task, specialized agents each handle their piece and hand off to the next automatically. The human stays in the loop for judgment calls, not for data gathering and routing. Hear from a customer who moved from standalone AI use cases to compound, multi-agent workflows with Amazon Quick. Learn how they identified which workflows to orchestrate first, how they designed agent handoffs that satisfy compliance, and what it means now that the coordination layer runs autonomously.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780441466101001GT93", "sources": ["business_agents"], "ko_desc": "금융 서비스에서 가장 중요한 워크플로우는 여러 시스템·전문성이 필요하고 사람이 조율 레이어 역할 — Amazon Quick로 멀티 에이전트 자율 워크플로우 구현.", "company": "AWS (금융)", "thu_am": false, "start_time": "16:00", "length": 60}, {"code": "BIZ215", "title": "From Pilot to Enterprise Scale with Amazon Quick", "abstract": "EchoStar evaluated 11 AI assistants before selecting Amazon Quick, which was then deployed to 8,000 employees with training and pre-populated skills. Next in EchoStar’s plans are integrating Quick with a third party gateways for observability and governance. Come and hear how this was done, uptake and innovations improving the efficiency of employees and teams. Discover some of the challenges integrating into existing enterprise systems, the continued activities needed to keep advancing high value usage and what are the appropriate metrics to track. Walk away with a repeatable framework for taking Amazon Quick from pilot to production and enterprise efficiency.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Wynn/Encore", "sessionID": "1780441466368001Gh3y", "sources": ["business_agents"], "ko_desc": "EchoStar가 11개 AI 어시스턴트 평가 후 Amazon Quick 선택 — 8,000명 직원 배포와 서드파티 게이트웨이 통합 계획.", "company": "EchoStar", "thu_am": false, "start_time": "16:00", "length": 60}, {"code": "BIZ112", "title": "From Zero to 20,000 Desktops: Getting Started with Amazon Quick", "abstract": "Your team is drowning in context-switching: toggling between email, documents, data tools, and chat just to complete a single task. Productivity tools promise to help, but most add complexity instead of removing it. In this fireside chat, hear from customers who faced that exact challenge and deployed an AI work companion across 20,000+ users in under 90 days. Learn what convinced their leadership to invest, how they integrated AI into daily workflows without disrupting existing tools, and what the first 90 days of adoption actually looked like. Walk away with a practical roadmap for bringing Amazon Quick AI assistant to your workforce at scale.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441465934001G6hh", "sources": ["business_agents"], "ko_desc": "Amazon Quick으로 팀의 컨텍스트 전환을 줄이는 실용적 시작 방법 — 이메일·문서·데이터·챗을 하나로 연결.", "company": "AWS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "BIZ113", "title": "Getting Started with Amazon Quick: How a Customer Went from Curious to Deployed", "abstract": "Your team spends hours on work that should take minutes: summarizing meetings, drafting documents, finding answers buried across systems, pulling data from multiple platforms. You know AI should help, but you need to see it work in a real environment before you commit. In this session, see how a customer put Amazon Quick into daily workflows across their organization and watch live as it composes documents, analyzes data, summarizes conversations, and connects to enterprise systems. Hear what problems they were solving, what changed for their teams after deployment, and what surprised them about adoption. Leave with a clear picture of the problems Quick solves and how to evaluate whether it fits your organization.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780441466155001GvQ6", "sources": ["business_agents"], "ko_desc": "고객이 호기심에서 배포까지 도달하는 여정 — Amazon Quick로 회의 요약·문서 작성·멀티 플랫폼 데이터 조회를 처음 경험하는 방법.", "company": "AWS", "thu_am": false, "start_time": "12:00", "length": 60}, {"code": "BIZ103", "title": "How A Customer Met Surge Hiring in Hours, Not Weeks", "abstract": "You expanded fast, but your hiring didn't keep up. What started as seasonal growth has become a scramble of manual screening, scheduling delays, and fragile workarounds that can't keep pace with your brand — forcing the impossible choice between speed and quality. Hear how a customer replaced weeks-long hiring with Amazon Connect Talent, putting AI teammates to work running science-backed candidate assessments and AI-led interviews that take candidates from application to same-day offer — evaluated on the substance of their answers. Built on AWS and informed by Amazon's hiring science, Amazon Connect Talent ensures recruiters stay in control of every decision. ", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1780441465490001GH5n", "sources": ["business_agents"], "ko_desc": "급격한 확장에 따른 채용 급증 시 수동 심사·일정 조율·비효율 없이 처리 — Amazon Connect로 서지 채용을 몇 주 대신 몇 시간 만에 처리한 사례.", "company": "AWS (채용)", "thu_am": false, "start_time": null, "length": 60}, {"code": "BIZ107", "title": "How EchoStar Turned CX and IT Into One Team to Ship AI Experiences", "abstract": "Most companies treat conversational AI as a technology rollout. EchoStar, the company behind DISH, treated it as a chance to reset how CX and IT work together. Instead of handing specs back and forth, the two teams now build side by side in Amazon Connect Customer, shaping and testing each experience before it goes live. CX owns the customer experience. IT owns data, security, and standards. Changes that took six to eight weeks now ship in about one week - roughly 6× faster. Hear from Echostar's CX and IT leaders on how they transformed their operating model, and leave with a framework to start the same shift.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1780441465661001Gaxd", "sources": ["business_agents"], "ko_desc": "EchoStar(DISH 모회사)가 CX와 IT를 하나의 팀으로 재편해 AI 경험 출시 — 기술 전달이 아닌 팀 협업 방식 재설계.", "company": "EchoStar (DISH)", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "BIZ106", "title": "How Flybuys Cut Costs by 24% and Scaled AI Agents Across 10M Members", "abstract": "10 million members. Limited visibility into support interactions. High costs. Flybuys needed a new path. In 7 months, they migrated to Amazon Connect Customer, bringing operations in-house, and deploying AI agents that now handle 100% of member interactions. The result of the migration has been a 24% cost reduction while improving customer satisfaction. Join this session to hear how Flybuys took control of their member experience, unlocked deep visibility across every interaction, and are now moving quickly to scale agentic AI across voice and digital channels.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1780441465606001GlIi", "sources": ["business_agents"], "ko_desc": "Flybuys가 1,000만 회원을 위한 AI 에이전트 배포로 비용 24% 절감 — 7개월 만에 Amazon Connect로 마이그레이션하고 운영을 인하우스로 전환.", "company": "Flybuys", "thu_am": false, "start_time": null, "length": 60}, {"code": "BIZ101", "title": "How Southwest Airlines migrated 4,500 agents in just 2.5 weeks", "abstract": "In just 2.5 weeks from decision to go-live, Southwest migrated 4,500 agents across 17 business units to Amazon Connect Customer without losing a single call. Join this session to hear their key lessons learned from the migration, and how the move unlocked more comprehensive analytics capabilities, giving leadership real-time visibility into previously hidden metrics. Discover what’s next for Southwest, including how they’re implementing agentic AI throughout the customer experience.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780441465382001G9uE", "sources": ["business_agents"], "ko_desc": "Southwest Airlines가 단 2.5주 만에 17개 사업부에 걸쳐 4,500명 에이전트를 Amazon Connect로 마이그레이션한 사례 — 한 통의 전화도 놓치지 않음.", "company": "Southwest Airlines", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ219", "title": "How a Brand Turned AI Governance Into a Strategic Advantage with Amazon Quick", "abstract": "AI adoption rarely waits for governance. When employees adopt AI faster than policy keeps pace, scale becomes a liability. Cox Automotive, the world’s largest automotive services and technology provider and home to brands including Autotrader, Kelley Blue Book, Manheim, vAuto and Dealertrack, defined a governance strategy to empower adoption. Hear how Cox Auto alongside AWS is building an agentic control plane spanning agent identity, ownership, security, cost accountability and more – and why Amazon Quick fit the everyday AI needs of its 29,000 person workforce. Leave with a practical seven pillar framework that simplifies safe and smart adoption in the enterprise.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780441466262001GSAX", "sources": ["business_agents"], "ko_desc": "AI 채택이 정책보다 빠를 때 확장성이 책임이 된다 — Cox Automotive가 Amazon Quick 거버넌스를 전략적 우위로 전환한 방법.", "company": "Cox Automotive", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "BIZ217", "title": "One AI Assistant, Every Data Source: Unifying Access with Amazon Quick", "abstract": "Your data lives in one platform. Your reports live in another. Your documents live somewhere else. Every time someone needs an answer, they spend time figuring out where to look before they can act. Decisions slow down. Teams duplicate work because they cannot find what already exists. New employees take months to become productive because institutional knowledge is trapped in systems they do not know how to navigate. Hear from a customer who solved this by giving their team a single AI assistant that connects across all their enterprise systems. Instead of training people on where to find information, they ask Amazon Quick and get answers grounded in their real business data, regardless of where it lives. Learn how they configured the integration, how their teams adopted it, and what changed about the speed and quality of decision-making across the organization.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1780441465825001Gj53", "sources": ["business_agents"], "ko_desc": "데이터가 여러 플랫폼에 분산될 때 AI 어시스턴트가 어디를 봐야 할지 결정 — Amazon Quick으로 모든 데이터 소스에 단일 접근 포인트 제공.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ303", "title": "One Context Layer, Every Surface: Enterprise Knowledge for Agents That Work Anywhere", "abstract": "Your AI agents are only as smart as the data they can reach. In most enterprises, that data is scattered across dozens of systems, siloed, ungoverned, and invisible to the agents that need it most. In this chalk talk, we architect a context layer from the ground up: connecting enterprise knowledge into a unified index, then enriching that foundation with a knowledge graph that maps organizational relationships, business rules, and domain context, giving agents permission-scoped, relationship-aware intelligence at runtime. Then we take that intelligence to where users work: browser, desktop, mobile, collaboration tools, and productivity suites. Each surface independently governed yet sharing one agent identity, one memory, and one set of guardrails. Bring your architecture. We'll whiteboard the end-to-end path together.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1780442236121001cr4i", "sources": ["business_agents"], "ko_desc": "AI 에이전트는 데이터에 접근할 수 있을 만큼만 스마트 — 수십 개 시스템에 흩어진 사일로화된 데이터를 에이전트가 어디서나 활용 가능하게 만드는 컨텍스트 레이어.", "company": "AWS", "thu_am": false, "start_time": "12:00", "length": 60}, {"code": "BIZ209", "title": "Prevent supply chain disruptions with AI-driven insights and action", "abstract": "Only 25% of organizations feel ready to prevent disruptions, and 85% take two or more weeks to resolve the urgent ones. Join a supply chain leader and Amazon to see how agentic AI catches emerging risks early, so teams act before problems turn costly. You will hear the honest before and after, including the hurdles, not just the wins, and leave knowing how to move your team from reacting under pressure to planning ahead with a clear view of risk.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1780441466048001GxY5", "sources": ["business_agents"], "ko_desc": "전체 조직의 25%만 공급망 혼란에 대비됨, 85%는 해결에 2주 이상 소요 — 에이전틱 AI가 조기에 위험을 감지하고 팀이 선제적으로 대응하도록 지원.", "company": "AWS (공급망)", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "BIZ310", "title": "Secure and Scalable Multi-Tenant Deployment Patterns for Amazon Quick", "abstract": "As organizations scale their adoption of Amazon Quick across business units, subsidiaries, and partner ecosystems, deploying a secure multi-tenant architecture becomes critical. This chalk talk explores proven deployment patterns that balance tenant isolation, governance, and operational efficiency when rolling out Amazon Quick at enterprise scale. We will walk through two primary isolation strategies: multi-account separation using AWS Organizations for environment-level boundaries (dev/staging/prod), and namespace-based logical isolation within a single account for user-cohort segmentation.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236064001cUg0", "sources": ["business_agents"], "ko_desc": "사업부·자회사·파트너 생태계 전반에 Amazon Quick를 확장할 때 보안 멀티테넌트 아키텍처의 배포 패턴.", "company": "AWS", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "BIZ305", "title": "Security → Zero-Trust Identity & Data Protection in Amazon Quick", "abstract": "Security reviews stall AI rollouts more than any capability gap, and agentic AI raises the bar. This chalk talk goes past \"is it secure?\" to the architecture that gets a CISO to yes for Amazon Quick. We'll whiteboard the full identity path in Quick: SSO through providers like Okta and Ping, with end-user identity propagated to the data so authorization is enforced per user, in real time, across 1P AWS and 3P sources. Then we extend that trust to Quick agents: agent identity, deterministic policy checks on every tool call, and data protection, including Purview DLP, default guardrails, deny-by-default, and full SIEM auditability.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236230001cn8Y", "sources": ["business_agents"], "ko_desc": "AI 롤아웃을 가장 많이 지연시키는 것은 보안 검토 — CISO의 승인을 받기 위한 Amazon Quick의 제로-트러스트 아이덴티티·데이터 보호 아키텍처.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "BIZ324", "title": "Self-Tuning Demand Forecasts: How Agentic AI Puts Business Users in the Driver's Seat", "abstract": "Amazon Connect Decisions is redefining how organizations approach demand forecast tuning. Traditionally, improving forecast accuracy meant navigating complex data engineering pipelines and hyperparameter optimization — work that was time-intensive, technically demanding, and largely inaccessible to business users. In this chalk talk, we unpack how Amazon Connect Decisions takes an agentic approach to solve this: intelligent agents continuously self-tune demand forecast models by incorporating business user feedback directly into the refinement loop, removing the undifferentiated heavy lifting. Walk through a live demonstration of self-tuning in action, learn how this business-first approach shifts forecast ownership to the people who understand the demand signals best, and discuss how Amazon Connect Decisions is shaping the future of agentic supply chain solutions.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236832001c07O", "sources": ["business_agents"], "ko_desc": "Amazon Connect Decisions로 수요 예측 튜닝을 복잡한 데이터 엔지니어링 파이프라인 없이 비즈니스 사용자가 직접 수행 — 자기 조정 수요 예측.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ105", "title": "Shaping the Future of Guest Support at lululemon with an AI-powered experience", "abstract": "What if you could design Guest Support for the future, not just improve the operation you have today?\n\nAt lululemon, that question shifted the conversation. Rather than patching together fragmented tools and manual planning processes, the team envisioned the experience they wanted to create for guests and their people, then worked backward to build it. The result was a unified, AI-powered experience launched globally, giving employees more time to build meaningful connections with guests.\n\nThis session explores how lululemon built a fundamentally different future for Guest Support and the principles leaders can use to do the same at their organization.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1780441465546001GTJc", "sources": ["business_agents"], "ko_desc": "lululemon이 기존 운영 개선이 아닌 미래를 위한 게스트 지원 설계 — 파편화된 도구와 수동 계획에서 AI 기반 경험으로 전환.", "company": "lululemon", "thu_am": false, "start_time": "13:00", "length": 60}, {"code": "BIZ102", "title": "Taking Every Interaction from Mundane to Magic: Agentic CX with Connect Customer", "abstract": "Every brand is racing to put AI in front of its customers, the biggest opportunity in a generation, but also a risk. In 2026, deflection is dead. Even the customers you help are quietly leaving, because being processed isn't the same as being known. In this session, the VP, Amazon Connect Customer, and SVP, Client Operations Technology, U.S. Bank, show what's possible when serving customers is AI-first by design: your brand shows up before they ask, and every customer feels like your only customer. If you own the customer relationship, this is the one session you can't afford to miss.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1780441465437001Gk4A", "sources": ["business_agents"], "ko_desc": "2026년 편향 처리(deflection)는 죽었다 — AI로 처리받는 느낌 없이 진짜 도움을 받는 경험으로 CX를 마법처럼 만드는 에이전틱 CX.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ404", "title": "Teaching Quick to Remember and Connect with Memory and Knowledge Graphs", "abstract": "Every conversation with an AI assistant starts from scratch. Your agent doesn't remember what worked yesterday, can't tell you who owns a project without searching again, and repeats the same mistakes because failures are never captured. In this chalk talk, we show how Amazon Quick breaks out of statelessness with two primitives: a continuous-learning memory layer where a background agent extracts reusable knowledge after each session and scores it with a probabilistic confidence model, and a personal knowledge graph that connects people, projects, decisions, and evidence across your tools so the agent has a map of your world before it reads a single document. We'll whiteboard the architecture and the tradeoffs that shaped it, then open it up — bring your hardest questions about memory staleness, confidence calibration, graph noise, or making agents that actually get better over time.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Palace", "sessionID": "1780442236004001cAY2", "sources": ["business_agents"], "ko_desc": "AI 어시스턴트가 매 대화를 처음부터 시작하는 문제 — 실패를 기억하고 소유관계를 파악하며 프로젝트를 추적하는 메모리와 지식 그래프 구현.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "BIZ331-S", "title": "Token-efficient retrieval for production AI agents (sponsored by Exa)", "abstract": "Most agent bills aren't driven by the model,  they're driven by the context it's given. Raw web pages, HTML boilerplate, and 10 blue links padded with irrelevant text quietly multiply token spend and degrade answer quality. This lightning talk walks through how Exa engineered retrieval to hand LLMs exactly the text they need: neural search that returns precise passages instead of whole pages, highlight extraction tuned to the query, and context-budgeting techniques that cut input tokens dramatically without hurting accuracy. Using real production traces, we'll show how token-efficient retrieval changes the economics of agents at scale on AWS, and give you a practical checklist you can apply to any RAG or agent pipeline this week. This presentation is brought to you by Exa, an AWS Partner.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Venetian", "sessionID": "1780442268244001cXPG", "sources": ["business_agents"], "ko_desc": "에이전트 비용의 주범은 모델이 아닌 컨텍스트 — HTML 보일러플레이트·불필요한 텍스트 없이 토큰 효율적인 검색으로 비용 절감하는 방법 (Exa 스폰서).", "company": "Exa", "thu_am": false, "start_time": null, "length": 20}, {"code": "BIZ114", "title": "What's New in Amazon Connect Customer", "abstract": "Your customers don't experience departments — they experience one journey. But siloed systems, fragmented data, and manual processes between teams create gaps they absolutely feel. This session introduces new Amazon Connect Customer capabilities that close those gaps end to end. Come see how these capabilities work together to deliver the seamless experience your customers expect and the certainty your business demands.", "type": "Breakout session", "level": "100 – Foundational", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780441471338001Gp4a", "sources": ["business_agents"], "ko_desc": "Amazon Connect Customer의 새로운 기능 소개 — 시스템 간 사일로를 제거해 단절 없는 고객 여정을 지원하는 최신 업데이트.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "BIZ405-R", "title": "Zero to multimodal in 60 mins: Building Live Sync on Connect Customer", "abstract": "What does it take to synchronize a live voice conversation with a real-time visual interface — and make it feel like magic? In this chalk talk, we'll answer that question by building one from scratch. Starting from first principles, we'll construct a fully functional voice AI agent that leverages the patented Live Sync on Amazon Connect Customer: the signaling that keeps voice and visual in lock-step, the state machine that drives bi-directional interaction, and the rendering layer that turns conversational intent into on-screen UI in real time. No slides, no hand-waving — just building, live, from zero to a working multimodal agent in 60 minutes. At the end, we'll deploy what we built and every phone in the room becomes a live demo.", "type": "Code talk", "level": "400 – Expert", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1788453086708001w991", "sources": ["business_agents"], "ko_desc": "음성 대화와 실시간 시각 인터페이스를 동기화하는 멀티모달 경험 구축 — Amazon Connect Customer에서 60분 만에 Live Sync 완성하는 방법.", "company": "AWS", "thu_am": null, "start_time": "13:00", "length": 60}, {"code": "BIZ405-R1", "title": "Zero to multimodal in 60 mins: Building Live Sync on Connect Customer", "abstract": "What does it take to synchronize a live voice conversation with a real-time visual interface — and make it feel like magic? In this chalk talk, we'll answer that question by building one from scratch. Starting from first principles, we'll construct a fully functional voice AI agent that leverages the patented Live Sync on Amazon Connect Customer: the signaling that keeps voice and visual in lock-step, the state machine that drives bi-directional interaction, and the rendering layer that turns conversational intent into on-screen UI in real time. No slides, no hand-waving — just building, live, from zero to a working multimodal agent in 60 minutes. At the end, we'll deploy what we built and every phone in the room becomes a live demo.", "type": "Code talk", "level": "400 – Expert", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Wynn/Encore", "sessionID": "1790358247381001i7Ig", "sources": ["business_agents"], "ko_desc": "음성-시각 멀티모달 경험 구축 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "BIZ332", "title": "​Every Candidate, Every Time: AI-Led Interviews with Connect Talent", "abstract": "​​Who you hire is the most important decision you make, and the hardest to get right at scale. Built on Amazon Connect and grounded in Amazon’s hiring science, Amazon Connect Talent runs AI-led interviews that evaluate every candidate consistently. In this chalk talk, we show how role requirements become evaluation criteria and questions, how AI agents hold a natural conversation while covering each competency and gathering evidence, and how responses are scored against a rubric tied to specific evidence. See a single job posting become a scored, evidence-backed evaluation. Leave knowing how to tell hiring science from gut feel, and why that shows up in better hires and a fairer experience for every candidate.​​ \n", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1780442241479001cVUQ", "sources": ["business_agents"], "ko_desc": "채용에서 가장 중요하면서 규모에서 가장 어려운 결정 — Amazon Connect와 Amazon 채용 과학을 기반으로 한 AI 면접 시스템 소개.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "COP101-S", "title": "Move Fast With AI Agents Without Betting the Business (sponsored by MontyCloud)", "abstract": "You are under pressure to put AI agents to work fast, without betting the business. Everyone is racing to build agents, but no one is governing them. MontyCloud is an AI-native, autonomous CloudOps platform built on one conviction. As agents become easy to create, value moves to trusted execution. Walk away with a blueprint for turning insights into governed workflows, and governed workflows into trusted outcomes. See a live demo where any agent, model, or tool acts only with the right context, identity, policy, approvals, and cost controls. Learn why the unit of value is the governed workflow. This presentation is brought to you by MontyCloud, an AWS Partner.", "type": "Lightning talk", "level": "100 – Foundational", "topic": "Business Agents, Cloud Operations", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1780442269063001cDiT", "sources": ["business_agents"], "ko_desc": "빠르게 AI 에이전트를 배포하면서도 비즈니스 위험을 감수하지 않는 방법 — MontyCloud의 AI 네이티브 자율 CloudOps 플랫폼 (MontyCloud 스폰서).", "company": "MontyCloud", "thu_am": null, "start_time": "14:00", "length": 20}, {"code": "AIM260-S", "title": "The Frontier Doesn't Hold Still: Running Claude Agents at Scale on AWS (sponsored by Anthropic)", "abstract": "Enterprises are moving faster with AI than ever. And they're falling further behind. Once the first agents land and the numbers look good, most teams turn to cost control while the frontier keeps moving. This session covers how to do both with Claude on AWS: the security and compliance controls enterprises require, execution inside your own boundary, observability and cost governance, and the safeguards that let you trust agents with more. Then how to keep expanding what agents do as new models arrive, so efficiency doesn't become the ceiling. This presentation is brought to you by Anthropic, an AWS Partner.", "type": "Breakout session", "level": "200 – Intermediate", "topic": "Business Agents, Cloud Operations, Security & Identity", "area_of_interest": "", "industry": "", "features": "AWS Partners, Lecture-style", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1780441487810001GBWT", "sources": ["business_agents"], "ko_desc": "에이전트로 초기 성과 달성 후 비용 통제에 집중하는 동안 AI 프론티어는 계속 발전한다 — AWS에서 Claude 에이전트를 대규모로 실행하는 방법 (Anthropic 스폰서).", "company": "Anthropic", "thu_am": null, "start_time": null, "length": 60}, {"code": "AIM333-R", "title": "The Agent Harness: Unifying Fragmented Tools for Mission AI Advisors", "abstract": "Advisors across mission-driven organizations—financial advisors, benefits navigators, program coordinators—juggle fragmented tools, manual research, and delayed plan delivery while clients go underserved. AI agents change this equation. See how to collapse this fragmentation into configuration using the Amazon Bedrock AgentCore Harness. Learn to securely plug domain-specific skills and disparate Model Context Protocol (MCP) servers directly into the harness to generate tailored action plans in real time. Then, deploy the agent to isolated microVM sessions utilizing native memory strategies and Bedrock Guardrails. Leave with sample configurations, deployment patterns, and blueprints for building production advisors that scale.", "type": "Code talk", "level": "300 – Advanced", "topic": "Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1780442253517001cLD0", "sources": ["business_agents"], "ko_desc": "재무 어드바이저·복지 담당자·프로그램 코디네이터 같은 미션 주도 조직의 어드바이저가 단편화된 도구와 수동 조사에서 벗어나도록 AI 에이전트 하네스 통합.", "company": "AWS", "thu_am": true, "start_time": "09:00", "length": 60}, {"code": "AIM333-R1", "title": "The Agent Harness: Unifying Fragmented Tools for Mission AI Advisors", "abstract": "Advisors across mission-driven organizations—financial advisors, benefits navigators, program coordinators—juggle fragmented tools, manual research, and delayed plan delivery while clients go underserved. AI agents change this equation. See how to collapse this fragmentation into configuration using the Amazon Bedrock AgentCore Harness. Learn to securely plug domain-specific skills and disparate Model Context Protocol (MCP) servers directly into the harness to generate tailored action plans in real time. Then, deploy the agent to isolated microVM sessions utilizing native memory strategies and Bedrock Guardrails. Leave with sample configurations, deployment patterns, and blueprints for building production advisors that scale.", "type": "Code talk", "level": "300 – Advanced", "topic": "Business Agents, Industry Solutions", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Palace", "sessionID": "1790358243674001ilV9", "sources": ["business_agents"], "ko_desc": "미션 주도 조직 어드바이저를 위한 AI 에이전트 하네스 통합 (반복 세션).", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "MAM347", "title": "Meet Your AI Teammate for WorkSpaces Administration", "abstract": "Whether you run WorkSpaces today or are evaluating cloud desktops for the first time, operational overhead follows every virtual desktop deployment: ongoing monitoring, systemic issues that surface as tickets, and end-user requests that consume administrator time. Most teams operate reactively, triaging problems after they surface and manually guiding users through resolution. This session explores how Amazon WorkSpaces Advisor is using AI to reduce resolution time for both IT administrators and end users. We'll walk through the operational challenges we're hearing from customers, share our approach to solving them, and demonstrate early results from production environments. Bring your deployment architecture questions.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Business Agents, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "MGM Grand", "sessionID": "1780442242053001cKxl", "sources": ["business_agents"], "ko_desc": "WorkSpaces 관리를 위한 AI 팀원 — 지속적 모니터링·시스템적 문제를 티켓으로 감지·최종 사용자 셀프서비스 지원.", "company": "AWS", "thu_am": null, "start_time": "14:00", "length": 60}, {"code": "AWS119-R", "title": "AWS Village in Expo", "abstract": "New launches land here first. Test what's new the day it's announced, go hands-on with agentic AI and the latest AWS innovations, and get direct time with the experts building it all.", "type": "Expo", "level": "100 – Foundational", "topic": "Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Venetian", "sessionID": "1787852032924001jCcA", "sources": ["business_agents"], "ko_desc": "AWS Village 엑스포 — 신규 런치를 당일 테스트하고 에이전틱 AI와 최신 AWS 혁신을 체험.", "company": "AWS", "thu_am": null, "start_time": "16:00", "length": 180}, {"code": "AWS019-R1", "title": "AWS Village in Expo", "abstract": "New launches land here first. Test what's new the day it's announced, go hands-on with agentic AI and the latest AWS innovations, and get direct time with the experts building it all.", "type": "Expo", "level": "No Level", "topic": "Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Venetian", "sessionID": "1789513461971001Ljcg", "sources": ["business_agents"], "ko_desc": "AWS Village 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "AWS019-R2", "title": "AWS Village in Expo", "abstract": "New launches land here first. Test what's new the day it's announced, go hands-on with agentic AI and the latest AWS innovations, and get direct time with the experts building it all.", "type": "Expo", "level": "No Level", "topic": "Business Agents, Security & Identity", "area_of_interest": "", "industry": "", "features": "", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Venetian", "sessionID": "1787852034911001jLZG", "sources": ["business_agents"], "ko_desc": "AWS Village 엑스포 (반복).", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 480}, {"code": "HMC302", "title": "How Max Mara built multicloud FinOps with open source", "abstract": "Max Mara runs hundreds of applications across AWS, GCP, Alicloud, and on-prem serving 20+ million monthly visits, but had no unified view of cost or correlation to business outcomes. In this session, hear how they implemented open-source Cloud Intelligence Dashboards with FOCUS (FinOps Open Cost and Usage Specification) to consolidate all sources into a single framework. Learn how unit economics — \"Cost per Order\" across 11 brands — drove 21% monthly cost optimization with minimal engineering effort. Walk away with an open-source based playbook for multicloud FinOps that delivers measurable results at enterprise scale.", "type": "Lightning talk", "level": "300 – Advanced", "topic": "Cloud Operations, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "Retail & Consumer Goods", "features": "Lecture-style", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Wynn/Encore", "sessionID": "1780442263430001cLak", "sources": ["retail"], "ko_desc": "Max Mara가 AWS·GCP·Alicloud·온프레미스에 걸친 수백 개 애플리케이션의 멀티클라우드 FinOps를 오픈소스로 구현한 방법 — 비즈니스 성과와 비용 상관관계 확보.", "company": "Max Mara", "thu_am": null, "start_time": "14:00", "length": 20}, {"code": "COM302-R1", "title": "The judgment gap: when Terraform scans clean but fails the audit", "abstract": "Checkov, trivy, and Prowler check rules someone already wrote. SOC 2 CC6.1 is a sentence open to interpretation. Between them sits the judgment gap, where AI-generated Terraform for S3, CloudFront, API Gateway, and Lambda often lands. We map the gap on the whiteboard together: take real controls from SOC 2 and PCI DSS, set them against what scanner rules verify, and mark what is left over. Then we discuss what closes the remainder: better authoring-side skills, human review, multi-model review, or accepting the risk. Bring a control your team owns; we trace where its enforcement lives, or does not.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Cloud Operations, Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Forum", "sessionID": "1790358221665001ioq7", "sources": ["customer_story"], "ko_desc": "IaC 스캐너가 통과해도 SOC 2 감사에서 실패하는 '판단의 공백' — AI 생성 Terraform에서 SOC 2·PCI DSS 컨트롤과 스캐너 규칙 사이의 실제 컴플라이언스 갭 식별.", "company": "AWS", "thu_am": false, "start_time": "14:00", "length": 60}, {"code": "COM404-R1", "title": "Scaling Multi-Cluster EKS Without Burning Your Infrastructure Budget", "abstract": "Managing hundreds of Amazon EKS clusters breaks standard multi-tenant architectures under the weight of shared control planes, noisy neighbors, and runaway cross-AZ data transfer costs. This interactive chalk talk skips the slides to whiteboard the painful realities of multi-cluster fleet topology at scale. We will dissect the architectural trade-offs between monolithic clusters and localized micro-clusters, mapping out exact blast-radius constraints. Bring your worst infrastructure bottlenecks; we will openly debate cluster life-cycle automation, shared VPC patterns, and cost-allocation frameworks, leaving you with a battle-tested blueprint to optimize fleet operations on Monday morning.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Cloud Operations, Serverless", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1790358237850001iacX", "sources": ["customer_story"], "ko_desc": "수백 개 EKS 클러스터 운영 시 공유 컨트롤 플레인·노이지 네이버·크로스-AZ 비용 폭증 문제 해결 — 멀티 클러스터 플릿 토폴로지 아키텍처 트레이드오프.", "company": "AWS", "thu_am": false, "start_time": "12:00", "length": 60}, {"code": "CMP358", "title": "Graviton5 for data workloads", "abstract": "Data workloads are bottlenecked by how fast they can access and process information — whether that data lives on local storage, in memory, or behind a lightweight service. New Graviton5 instance families are purpose-built for each tier.", "type": "Breakout session", "level": "300 – Advanced", "topic": "Compute", "area_of_interest": "", "industry": "", "features": "Customer story, Lecture-style", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1780441471682001GwUd", "sources": ["customer_story"], "ko_desc": "Graviton5 데이터 워크로드 최적화 — 로컬 스토리지·메모리·경량 서비스 각 계층에 맞게 설계된 새 인스턴스 패밀리 소개.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "AIM311-R1", "title": "From 1 to 20,000: Scale reliably on AWS Trainium with AWS EKS", "abstract": "As AI workloads scale, infrastructure failures become inevitable, causing stalled jobs, degraded throughput, and wasted accelerator capacity. In this chalk talk, we'll show how to build resilient AI workloads on AWS Trainium with AWS EKS. We'll whiteboard the full resiliency stack: Neuron DRA Driver for topology-aware scheduling; UltraServer Operator for provisioning UltraServer workloads; Neuron Observer for sub-second fault detection; and Device Taint for automated recovery. These patterns support fault-tolerant distributed training and inference from a single accelerator to 20,000. You will leave able to assemble this resiliency stack yourself and keep training and inference running through hardware failures.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Compute, Containers", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "Caesars Palace", "sessionID": "1790358215538001iYTq", "sources": ["customer_story"], "ko_desc": "EKS에서 Trainium으로 AI 워크로드를 1노드→2만 노드까지 안정적으로 확장 — 토폴로지 인식 스케줄링과 UltraServer 운영자로 내결함성 스택 구축.", "company": "AWS", "thu_am": false, "start_time": null, "length": 60}, {"code": "HMC406", "title": "How Amazon Robotics runs AWS Outposts across hundreds of fulfillment centers", "abstract": "Amazon Robotics operates AWS Outposts across hundreds of fulfillment centers, each supporting multiple teams with distinct workload requirements. In this code talk, learn how the team architects isolation on shared Outposts infrastructure, manages resource quotas across competing workloads, and implements high-availability strategies that keep robotic systems running through hardware and network failures. The session walks through the team onboarding model, failover patterns between Outposts and the parent AWS Region, and monitoring strategies that detect degradation before it impacts fulfillment operations.", "type": "Code talk", "level": "400 – Expert", "topic": "Compute, Hybrid Cloud & Multicloud", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1780442256679001c8QA", "sources": ["robotics"], "ko_desc": "Amazon Robotics가 수백 개 물류 센터에 걸쳐 AWS Outposts를 운영 — 여러 팀이 공유 Outposts 인프라를 사용하면서 격리를 유지하는 아키텍처와 운영 방법.", "company": "Amazon Robotics", "thu_am": false, "start_time": null, "length": 60}, {"code": "IND359-R1", "title": "In-Country HPC: How TGS Processes Seismic Data on AWS Brazil", "abstract": "TGS -- one of the world's largest multi-client geoscience data providers -- faced a significant cost challenge running its business-critical Rackmon EFWI GPU workload at scale. By strategically deploying this workload on AWS infrastructure in Brazil, TGS leveraged Brazil's ReData Special Tax Regime to dramatically reduce the tax burden on GPU-intensive seismic processing. The result: material cost savings on one of the most computationally demanding workloads in the energy industry -- and a reusable in-country processing architecture that can serve future customers with data residency requirements in other geographies.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Compute, Migration & Modernization", "area_of_interest": "", "industry": "Energy & Utilities", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358232199001iAvH", "sources": ["customer_story"], "ko_desc": "TGS(세계 최대 지구과학 데이터 공급업체)가 AWS Brazil에서 GPU 집약 지진파 처리 시 브라질 ReData 세금 특례를 활용해 비용을 대폭 절감한 사례.", "company": "TGS", "thu_am": null, "start_time": "12:00", "length": 60}, {"code": "CMP411-R1", "title": "Aperf: An all-in-one tool for performance data collection and analysis", "abstract": "Aperf is an open-source project created by AWS to accelerate the performance debugging process by enabling experienced users to deep dive into extensive data and less experienced users to identify issues without specialized knowledge. During this session, we'll present its key features and run a demo showing the analysis workflow, from installation, data collection, and then analysis. Finally, we'll open the conversation to collect feedback and feature requests from the audience.", "type": "Code talk", "level": "400 – Expert", "topic": "Compute, Open Source", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1790358254636001iNtO", "sources": ["customer_story"], "ko_desc": "AWS 오픈소스 성능 분석 도구 Aperf 소개 — 전문가·비전문가 모두 성능 디버깅을 수행할 수 있는 설치→수집→분석 워크플로우 데모.", "company": "AWS", "thu_am": null, "start_time": "08:00", "length": 60}, {"code": "CMP408", "title": "The cloud holodeck: Stream NVIDIA Omniverse, scale headless sim on AWS", "abstract": "Interactive simulation needs RTX-class GPUs engineers lack; rendering millions of frames needs a fleet nobody wants to babysit. Amazon DCV streams a full NVIDIA Omniverse and Isaac Sim workstation from EC2 G instances to any browser, while AWS Batch runs the same scenes headless across GPU fleets for scale. The AWS Visual Asset Management System is the control plane: launching jobs, tracking runs, and versioning outputs. Watch an engineer open a cloud viewport and fan out a thousand-frame jobs live.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Compute, Open Source", "area_of_interest": "", "industry": "", "features": "Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "MGM Grand", "sessionID": "1780441497847001GawL", "sources": ["robotics"], "ko_desc": "Amazon DCV로 브라우저에서 NVIDIA Omniverse·Isaac Sim 워크스테이션 스트리밍 — GPU가 없는 엔지니어에게 RTX급 성능을 제공하고 헤드리스 시뮬레이션 확장.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "CMP316-R1", "title": "Storage performance in EC2 instances: What matters to your workload", "abstract": "Peak SSD IOPS and throughput dominate benchmarks, but production workloads tell a different story. In this chalk talk, we explore why latency-consistent mixed read/write performance drives real application outcomes across database, analytics, and distributed file system workloads. We'll walk through how workload profiles map to different performance dimensions (throughput vs. IOPS vs. latency consistency), how real-world write mixes reveal true storage performance, and how emerging AI workloads are creating demand for an entirely new storage performance profile.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Compute, Storage", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Friday, Dec 04", "venue": "Wynn/Encore", "sessionID": "1790358215908001ixeU", "sources": ["customer_story"], "ko_desc": "프로덕션에서 중요한 EC2 스토리지 성능 지표 — 최대 IOPS 벤치마크가 아닌 워크로드별 실제 결과를 결정하는 지연시간 일관성·읽기쓰기 혼합 분석.", "company": "AWS", "thu_am": null, "start_time": "10:00", "length": 60}, {"code": "MAM403-R1", "title": "Decompose a monolith database into microservices with agentic AI", "abstract": "Enterprise architects face a critical challenge: breaking monolithic database-centric applications into microservices while managing risk and cost. Where do you draw domain boundaries? How do you extract 20 years of business logic from stored procedures into the application layer? This chalk talk reveals the two-layer decomposition strategy—combining database structure and runtime execution patterns—to identify service boundaries. Leveraging AWS Transform and Kiro, collapse months of manual analysis, design and development into hours of executable code. Through live whiteboarding, learn the data-driven framework enabling business logic extraction, independent deployment, licensing cost reduction, and faster modernization.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Databases, Migration & Modernization", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358218240001iLbp", "sources": ["customer_story"], "ko_desc": "에이전틱 AI로 모놀리식 DB 기반 앱을 마이크로서비스로 분해 — 도메인 경계 설정과 스토어드 프로시저의 20년치 비즈니스 로직 추출 전략.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "NET301-R1", "title": "See the routes change: Live BGP with AWS Direct Connect", "abstract": "AWS Direct Connect can feel like a mystery beneath the surface, and many customers never get hands-on access. In this show and tell, we change that. Starting from a live connection and on-premises router, watch a Direct Connect maintenance unfold in real-time from both sides of the BGP session. See how AWS signals maintenance ahead of time through AS path prepending, graceful shutdown, and how traffic shifts to the backup path before any route is withdrawn. Whether you run 1G or hundreds of 100G ports, leave with the policy and checklist to get through your next maintenance without a page.", "type": "Code talk", "level": "300 – Advanced", "topic": "Hybrid Cloud & Multicloud, Networking & Content Delivery", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Palace", "sessionID": "1790358242568001iHNl", "sources": ["customer_story"], "ko_desc": "AWS Direct Connect BGP 라우팅 변화를 라이브 시연 — 유지보수 시 AS 경로 선행·그레이스풀 셧다운 등 실제 동작을 양측에서 실시간 확인.", "company": "AWS", "thu_am": null, "start_time": "11:00", "length": 60}, {"code": "IND405-R1", "title": "Build low latency real-time bidding workloads with AWS RTB Fabric", "abstract": "With the growth of digital media, including streaming video and retail media, customers that operate advertising platforms need to buy, sell, deliver, and measure millions of ad transactions per second while meeting stringent latency requirements. In this chalk talk, you will learn how to run real-time bidding workloads with your AdTech partners on a dedicated network in the cloud using AWS RTB Fabric. You will learn how to setup, onboard, and integrate AWS RTB Fabric with your supply and demand-side-platforms. Additionally, you will learn about key features including the core network, modules, and pricing model of the service.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Migration & Modernization, Industry Solutions", "area_of_interest": "", "industry": "Advertising & Marketing", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Caesars Forum", "sessionID": "1790358223207001iA4U", "sources": ["customer_story"], "ko_desc": "AWS RTB Fabric으로 디지털 광고 실시간 입찰 플랫폼 구축 — 스트리밍 비디오·리테일 미디어 포함 초당 수백만 광고 트랜잭션을 엄격한 지연시간 내에 처리.", "company": "AWS", "thu_am": null, "start_time": "15:00", "length": 60}, {"code": "IND314-R1", "title": "Modernizing Legacy Telecommunications OSS/BSS Systems", "abstract": "Legacy modernization is one of the most complex challenges facing Telecommunications companies today. In this Chalk Talk, we will explore strategies to accelerate VMware and mainframe migrations using Agentic AI. Using a real-world scenario, we will walk through how AWS Transform and Amazon Bedrock are used to meet the technical and business requirements of these projects and explore trade-offs in migration design and infrastructure choices. Come ready to discuss your own migration challenges!", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Migration & Modernization, Industry Solutions", "area_of_interest": "", "industry": "Telecommunications", "features": "Customer story, Discussion", "session_appendices": "", "day": "Monday, Nov 30", "venue": "Caesars Forum", "sessionID": "1790358239613001itc4", "sources": ["customer_story"], "ko_desc": "통신사 레거시 OSS/BSS 현대화 — AWS Transform과 Bedrock 기반 에이전틱 AI로 VMware·메인프레임 마이그레이션을 가속화하는 실전 시나리오.", "company": "AWS (통신사 사례)", "thu_am": null, "start_time": "16:00", "length": 60}, {"code": "MAM331-R1", "title": "Guide to deploying landing zones & modernized networks in hours", "abstract": "Reimagine what migration looks like when landing zone setup and network translation go from weeks to hours. In this chalk talk, we show how AWS Transform's agentic AI compresses that timeline, from migration inventory to fully deployed, validated landing zones and modernized networks. See how production-ready account structures deploy through Control Tower with guardrails in place, and how firewall configurations become optimized VPCs, subnets, and security groups. Bring your questions and hear from the experts building these capabilities.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Migration & Modernization, Networking & Content Delivery", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Tuesday, Dec 01", "venue": "Wynn/Encore", "sessionID": "1790358240014001i81w", "sources": ["customer_story"], "ko_desc": "AWS Transform 에이전틱 AI로 랜딩 존 설정·네트워크 전환을 수주→수 시간으로 단축 — Control Tower를 통한 프로덕션 준비 계정 구조 자동 배포.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "NET329-R1", "title": "Scaling and securing MCP Servers with AWS Load Balancing and WAF", "abstract": "MCP servers are becoming essential infrastructure in enterprise AI environments, and running them in production demands both scalability and security. Join this chalk talk to explore patterns for scaling and securing your MCP servers using AWS native services. We'll cover how to configure Application Load Balancer for MCP traffic characteristics, implement health checks and routing policies, and scale horizontally across availability zones. We'll also cover how to enforce security controls with AWS WAF, including request filtering, rate limiting, and tool-level access policies. Whether you're running a handful of MCP servers or deploying at enterprise scale, you'll leave with actionable architectures for production-ready deployments.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Migration & Modernization, Networking & Content Delivery", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1790358229744001i21L", "sources": ["customer_story"], "ko_desc": "엔터프라이즈 AI 환경의 MCP 서버 확장·보안 패턴 — ALB와 WAF로 MCP 트래픽 관리, 헬스체크, 라우팅 정책 설정.", "company": "AWS", "thu_am": false, "start_time": null, "length": 60}, {"code": "NET324-R1", "title": "Network security architecture: Deployment patterns for firewalls", "abstract": "As organizations scale across multiple accounts with hybrid connectivity, designing effective network inspection becomes critical. Join this chalk talk to discuss deployment patterns for AWS Network Firewall and Gateway Load Balancer with third-party firewalls for ingress and egress inspection.", "type": "Chalk talk", "level": "300 – Advanced", "topic": "Networking & Content Delivery, Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "Caesars Forum", "sessionID": "1790358235562001iGPY", "sources": ["customer_story"], "ko_desc": "멀티 계정·하이브리드 연결 환경의 네트워크 검사 아키텍처 — AWS Network Firewall과 Gateway Load Balancer 기반 인그레스/이그레스 검사 배포 패턴.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}, {"code": "INV502-R1", "title": "Attesting to Secrets in Zero Knowledge", "abstract": "It is possible to prove factual statements about systems to observers without revealing any details about those systems beyond the stated claims. This is surprising, but not as surprising as the fact that it is borderline practical using Zero Knowledge Proofs. This talk will give an overview of the mathematical foundations of Zero Knowledge Proofs and introduce both interactive and non-interactive proof schemes. It will then dive into the details of some of the current general purpose Zero Knowledge proof systems (e.g., zk-SNARK and zk-STARK) and show how to use Zero Knowledge libraries to attest to (or prove) properties of software systems without sharing the implementations of those systems.", "type": "Chalk talk", "level": "500 – Distinguished", "topic": "Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Thursday, Dec 03", "venue": "MGM Grand", "sessionID": "1780441495732001GgPZ", "sources": ["customer_story"], "ko_desc": "영지식 증명(ZKP) 개요 — 시스템 세부 정보를 공개하지 않고 사실을 증명하는 수학적 기반과 대화형·비대화형 프로토콜 소개.", "company": "AWS", "thu_am": true, "start_time": "09:00", "length": 60}, {"code": "SEC430-R1", "title": "Multi-tenant isolation with IAM: ABAC, session tags, and token vending machines", "abstract": "Multi-tenant SaaS has two isolation options: application-layer filtering or IAM enforcement. Filtering requires every query and API call to add tenant scoping — one missed filter leaks data. IAM enforcement holds even when code has a bug, and Attribute-Based Access Control (ABAC) makes it work without per-tenant policy explosion. We cover the stack: ABAC session tags, a Token Vending Machine minting tenant-scoped STS credentials, IAM condition keys for DynamoDB/S3 partition boundaries, and a credential-caching model that keeps latency acceptable at millions of requests per second across thousands of tenants. Leave with a deployable reference architecture and policy template.", "type": "Chalk talk", "level": "400 – Expert", "topic": "Security & Identity", "area_of_interest": "", "industry": "", "features": "Customer story, Discussion", "session_appendices": "", "day": "Wednesday, Dec 02", "venue": "MGM Grand", "sessionID": "1790358227852001iPKc", "sources": ["customer_story"], "ko_desc": "멀티테넌트 SaaS의 IAM 격리 전략 — ABAC 세션 태그와 Token Vending Machine으로 per-tenant 정책 폭발 없이 안전한 테넌트 격리 구현.", "company": "AWS", "thu_am": null, "start_time": null, "length": 60}];
